import type { RetrievalTrace, SummarySlice } from "../../shared/domain";
import { recallCoordinator } from "../recall-coordinator";
import { echoesApi } from "../api/client";
import { buildSummaryRetrievalText, summaryRetrievalDocumentId, summaryRetrievalContentHash } from "../summary/retrieval-document";
import type { SummaryWorldbookState } from "../worldbook/summary-worldbook";
import { actions, badge, button, detail, dialog, download, el, empty, fields, local, section, table, tool, type ViewContext } from "./core";
import { redactLog } from "./logs";

export function recallTraceView(trace: RetrievalTrace): HTMLElement {
  const root = el("div", "ew-page-content");
  const counts = trace.stages ?? [];
  root.append(
    table(["阶段", "数量"], counts.map((stage) => [stage.name, String(stage.count)])),
    detail("实际查询", trace.diagnostics?.queries ?? trace.query),
    detail("编排来源", trace.queryBlocks ?? []),
    detail("来源集合与分支状态", { sources: trace.sources, branches: trace.branches }),
    detail("注入文本", trace.injectionText ?? ""),
  );
  if (trace.message) root.append(el("p", "ew-muted", trace.message));
  if (trace.injectionBudget) {
    const budget = trace.injectionBudget;
    const labels = { status: "状态", recent: "近期总结", semantic: "普通召回", retained: "滞留切片", associated: "关联资料" };
    root.append(section("注入预算（本地估算 Token）",
      actions(badge(`预算 ${budget.limit || "不限"}`), badge(`全部候选 ${budget.requestedTokens}`),
        badge(`本轮 ${budget.injectedTokens}`, budget.overflow || budget.blocked ? "warning" : ""),
        budget.blocked ? badge("中止生成", "danger") : null),
      table(["类别", "预算筛选前", "预算筛选后"], budget.categories.map((item) => [labels[item.category], item.requestedTokens, item.injectedTokens])),
      detail("未注入内容", budget.omitted)));
  }
  const candidates = trace.diagnostics?.candidates ?? [];
  const host = el("div");
  let page = 0;
  const draw = () => {
    const previous = tool("上一页候选", "chevron-left", () => { page--; draw(); });
    const next = tool("下一页候选", "chevron-right", () => { page++; draw(); });
    previous.disabled = page === 0;
    next.disabled = (page + 1) * 50 >= candidates.length;
    const reasons = { selected: "后端通过", minimum_relevance: "低于阈值", result_limit: "超过后端返回上限" };
    host.replaceChildren(
      table(["切片", "融合分数", "重排分数", "加权后", "阈值", "去向", "详情"],
        candidates.slice(page * 50, (page + 1) * 50).map((candidate) => {
          const hit = candidate.hit;
          return [hit.document.sourceId, hit.rrfScore.toFixed(5), hit.rerankScore?.toFixed(5) ?? "-",
            hit.weightedScore?.toFixed(5) ?? "-", String(candidate.threshold), reasons[candidate.decision],
            tool("查看分数构成", "eye", () => {
              const body = el("div", "ew-page-content",
                badge("单项试算；仅 combined 行为最终合计"),
                table(["权重项", "原始分数", "加权重", "乘权重", "试算 / 合计"],
                  (hit.scoreSteps ?? []).map((step) => [step.label, String(step.before), String(step.add),
                    String(step.multiply), String(step.after)])),
                detail("分路命中", hit.queryMatches ?? []));
              dialog("排序诊断", body);
            })];
        })),
      actions(previous, badge(`${page + 1} / ${Math.max(1, Math.ceil(candidates.length / 50))}`), next),
    );
  };
  if (candidates.length) { draw(); root.append(section("候选筛选", host)); }
  if (trace.diagnostics?.omittedCandidates) root.append(badge(`其余 ${trace.diagnostics.omittedCandidates} 条未展开记录`));
  if (trace.decisions?.length) root.append(detail("前端排除原因", trace.decisions));
  return root;
}

export async function memoryPipelineView(ctx: ViewContext): Promise<HTMLElement> {
  const root = el("div", "ew-page-content");
  const history = recallCoordinator.history();
  const generation = ctx.summary.history();
  root.append(actions(
    badge("仅当前会话：最近 10 次召回 / 20 次总结"),
    button("导出链路记录", "download", () => {
      if (confirm("导出包含查询与注入正文，可能含私人剧情。继续？")) {
        download("echoes-pipeline.json", JSON.stringify(redactLog({ recall: history, summary: generation }), null, 2));
      }
    }),
    button("清空链路记录", "trash", async () => {
      recallCoordinator.clearHistory();
      ctx.summary.clearHistory();
      await ctx.refresh();
    }),
  ));
  root.append(section("总结生成链路", ...generation.map((trace) =>
    detail(`批次 ${trace.batchNumber} · ${trace.state} · ${new Date(trace.startedAt).toLocaleTimeString()}`, trace)),
  ...(generation.length ? [] : [empty("本次会话暂无总结生成记录")]),
  button("预览原消息与清洗结果", "eye", () => ctx.navigate("summary/tasks"))));
  const traceHost = el("div");
  if (history[0]) traceHost.append(recallTraceView(history[0]));
  else traceHost.append(empty("当前聊天暂无召回诊断"));
  root.append(section("召回链路", actions(
    ...history.map((trace, index) => button(
      `${index + 1} · ${trace.generationType === "preview" ? "预览" : "生成"} · ${new Date(trace.startedAt).toLocaleTimeString()}`,
      "clock", () => traceHost.replaceChildren(recallTraceView(trace)),
    )),
  ), traceHost));
  const worldbook = window.TavernHelper?.getChatWorldbookName("current");
  if (!worldbook) { root.append(empty("当前聊天尚未建立记忆世界书")); return root; }
  const state = await ctx.summary.store.inspect(worldbook);
  if (ctx.signal.aborted) return root;
  const inspect = fields([{ key: "slice", label: "切片来源与索引", type: "select",
    options: state.slices.map((slice) => [slice.id, `${slice.batch.batchNumber}.${slice.sliceNumber} ${slice.title}`]) }], false);
  root.append(section("写入与索引", inspect.node, button("检查选中切片", "magnifying-glass", async () => {
    ctx.guard();
    const slice = state.slices.find((item) => item.id === inspect.values().slice);
    if (!slice) throw new Error("没有可检查的切片。");
    const collection = state.catalog.retrievalCollectionId;
    const index = collection ? (await echoesApi.retrievalDocumentStatus([await summaryRetrievalDocumentId(collection, slice.id)])).documents[0] : undefined;
    ctx.guard();
    const hash = await summaryRetrievalContentHash(slice);
    const body = el("div", "ew-page-content",
      table(["阶段", "结果"], [
        ["来源批次", `${slice.batch.startMessageId} - ${slice.batch.endMessageId}`],
        ["提取与清洗", "仅保存了批次来源，原始生成过程未录制"],
        ["世界书写入", slice.id],
        ["检索表示", slice.retrievalText ? "独立表示" : "原文索引"],
        ["索引", index ? index.vectorState : "未建立"],
        ["索引内容校验", index ? index.contentHash === hash ? "一致" : "不一致" : "无"],
      ]), detail("批次元数据", slice.batch));
    dialog("切片链路", body);
  })));
  const draft = local(ctx, "recall-evaluation", () => ({ query: "", expected: "", forbidden: "" }));
  const form = fields([
    { key: "query", label: "测试查询", type: "textarea", rows: 4, value: draft.query, required: true },
    { key: "expected", label: "应召回切片 ID（每行一项）", type: "textarea", rows: 3, value: draft.expected },
    { key: "forbidden", label: "不应注入切片 ID（每行一项）", type: "textarea", rows: 3, value: draft.forbidden },
  ], false);
  form.node.addEventListener("input", () => Object.assign(draft, {
    query: form.controls.get("query")!.value,
    expected: form.controls.get("expected")!.value,
    forbidden: form.controls.get("forbidden")!.value,
  }));
  const resultHost = el("div");
  root.append(section("隔离召回测试", form.node, button("运行召回测试", "flask", async () => {
    const values = form.values();
    Object.assign(draft, values);
    if (!confirm("召回测试可能调用向量和重排序端点，但不会调用生成模型、注入记忆或移动检查点。继续？")) return;
    ctx.guard();
    const result = await ctx.run("隔离召回测试", () => recallCoordinator.preview([], values.query));
    ctx.guard();
    const ids = new Set([...result.hits.map((hit) => hit.document.sourceId),
      ...result.recentSlices.map((slice) => slice.id), ...(result.retainedSlices ?? []).map((slice) => slice.id)]);
    const parse = (text: string) => [...new Set(text.split(/\s+/).filter(Boolean))];
    const missing = parse(values.expected).filter((id) => !ids.has(id));
    const unexpected = parse(values.forbidden).filter((id) => ids.has(id));
    resultHost.replaceChildren(actions(badge(`漏召回 ${missing.length}`, missing.length ? "warning" : ""),
      badge(`不应注入 ${unexpected.length}`, unexpected.length ? "danger" : "")),
    detail("测试差异", { missing, unexpected }), recallTraceView(result.trace));
  }), resultHost));
  return root;
}

export function editRetrievalRepresentation(ctx: ViewContext, state: SummaryWorldbookState, slice: SummarySlice): void {
  let expected = state;
  const form = fields([
    { key: "body", label: "完整正文（只读）", type: "textarea", rows: 6, readonly: true, value: slice.content },
    { key: "text", label: "独立检索表示（空白使用原文）", type: "textarea", rows: 12, value: slice.retrievalText ?? "" },
    { key: "sync", label: "保存后同步索引（可能产生向量化费用）", type: "checkbox", value: false },
  ]);
  const replace = (text: string) => {
    form.controls.get("text")!.value = text;
    form.controls.get("text")!.dispatchEvent(new Event("input", { bubbles: true }));
  };
  dialog("检索表示 · " + slice.title, el("div", "ew-page-content", form.node, actions(
    button("从正文与标签重建", "rotate", () => replace(buildSummaryRetrievalText(slice))),
    button("恢复原文索引", "rotate-left", () => replace("")),
  )), async () => {
    const values = form.values();
    if (values.sync && !confirm("同步 1 个切片的索引，可能产生向量化费用。继续？")) {
      throw new Error("未保存。");
    }
    ctx.guard();
    expected = await ctx.summary.saveRetrievalTexts(expected, new Map([[slice.id, values.text || undefined]]));
    form.clean();
    if (values.sync) {
      await ctx.run("同步检索表示", () => ctx.summary.synchronizeSlices([slice.id]), () => ctx.summary.stop());
    }
    await ctx.refresh();
  }, form.dirty);
}
