import {
  evaluateStatusVariables,
  formatStatusVariableNumber,
  renderStatusVariables,
  replaceStatusVariable,
  type StatusVariable,
  type StatusVariableValue,
} from "../../shared/status-variables";
import { statusCoordinator } from "../status/status-coordinator";
import type { StatusWorldbookState } from "../worldbook/status-worldbook";
import { actions, badge, button, dialog, el, empty, fields, id, section, table, tool, type ViewContext } from "./core";

export function statusVariablesView(ctx: ViewContext, initial: StatusWorldbookState): HTMLElement {
  let state = initial;
  const page = el("div", "ew-page-content");
  const records = el("div"), output = el("pre", "ew-code ew-variable-preview");
  const variables = () => state.catalog.customVariables ?? [];

  const edit = (variable?: StatusVariable) => {
    const expected = structuredClone(variables());
    const variableId = variable?.id ?? id("status_variable");
    const form = fields([
      { key: "name", label: "变量名", value: variable?.name ?? "", required: true },
      { key: "type", label: "变量类型", type: "select", value: variable?.type ?? "fixed",
        options: [["fixed", "固定变量"], ["computed", "变化变量"]] },
      { key: "baseNumber", label: "基础值", type: "number", required: true,
        value: variable?.base.kind === "number" ? variable.base.value : 0 },
      { key: "baseFormula", label: "基础公式", type: "textarea", rows: 3, required: true,
        value: variable?.base.kind === "formula" ? variable.base.value : "" },
      { key: "extraKind", label: "额外值类型", type: "select", value: variable?.extra.kind ?? "number",
        options: [["number", "固定值"], ["formula", "公式"]] },
      { key: "extraNumber", label: "额外值", type: "number", required: true,
        value: variable?.extra.kind === "number" ? variable.extra.value : 0 },
      { key: "extraFormula", label: "额外公式", type: "textarea", rows: 3, required: true,
        value: variable?.extra.kind === "formula" ? variable.extra.value : "" },
    ]);
    for (const key of ["baseNumber", "extraNumber"]) (form.controls.get(key)! as HTMLInputElement).step = "any";
    for (const key of ["baseFormula", "extraFormula"]) {
      form.controls.get(key)!.title = '支持 + - * / % ^、括号及 abs / min / max / floor / ceil / round / sqrt；引用使用 base("变量名") 或 final("变量名")。';
    }
    const references = fields([
      { key: "target", label: "插入到", type: "select", options: [["baseFormula", "基础公式"], ["extraFormula", "额外公式"]] },
      { key: "variable", label: "引用固定变量", type: "select",
        options: expected.filter((item) => item.type === "fixed" && item.id !== variableId).map((item) => [item.name, item.name]) },
      { key: "part", label: "引用值", type: "select", options: [["base", "基础值"], ["final", "最终值"]] },
    ], false);
    references.node.addEventListener("submit", (event) => event.preventDefault());
    const insert = button("插入引用", "arrow-turn-down", () => {
      const choice = references.values();
      if (!choice.variable) throw new Error("当前没有可引用的其他固定变量。");
      const control = form.controls.get(choice.target) as HTMLTextAreaElement;
      const reference = `${choice.part}(${JSON.stringify(choice.variable)})`;
      control.setRangeText(reference, control.selectionStart, control.selectionEnd, "end");
      control.dispatchEvent(new Event("input", { bubbles: true }));
      control.focus();
    });
    references.node.append(actions(insert));
    const mode = () => {
      const computed = form.controls.get("type")!.value === "computed";
      const formulaExtra = form.controls.get("extraKind")!.value === "formula";
      for (const [key, enabled] of [
        ["baseNumber", !computed], ["baseFormula", computed],
        ["extraNumber", !formulaExtra], ["extraFormula", formulaExtra],
      ] as const) {
        const control = form.controls.get(key)!;
        control.disabled = !enabled;
        control.closest<HTMLElement>("label")!.hidden = !enabled;
      }
      const target = references.controls.get("target") as HTMLSelectElement;
      target.options[0]!.disabled = !computed;
      target.options[1]!.disabled = !formulaExtra;
      if (target.selectedOptions[0]?.disabled) target.value = computed ? "baseFormula" : "extraFormula";
      references.node.hidden = !computed && !formulaExtra;
      insert.disabled = !expected.some((item) => item.type === "fixed" && item.id !== variableId);
    };
    form.controls.get("type")!.addEventListener("change", mode);
    form.controls.get("extraKind")!.addEventListener("change", mode);
    mode();
    const candidate = () => {
      const value = form.values();
      return replaceStatusVariable(expected, {
        id: variableId, name: value.name, type: value.type,
        base: value.type === "fixed" ? { kind: "number", value: value.baseNumber } : { kind: "formula", value: value.baseFormula },
        extra: value.extraKind === "number" ? { kind: "number", value: value.extraNumber } : { kind: "formula", value: value.extraFormula },
      });
    };
    const preview = el("pre", "ew-code ew-variable-preview");
    preview.hidden = true;
    preview.setAttribute("aria-label", "变量试算结果");
    const body = el("div", "ew-page-content", form.node, references.node,
      actions(button("试算", "calculator", () => {
        preview.hidden = false;
        try { preview.textContent = renderStatusVariables(candidate()); }
        catch (error) { preview.textContent = error instanceof Error ? error.message : String(error); }
      })), preview);
    dialog(variable ? `编辑变量 · ${variable.name}` : "新增变量", body, async () => {
      ctx.guard();
      const next = candidate();
      state = await statusCoordinator.worldbook.saveVariables(state.worldbookName, next, expected, ctx.guard);
      draw();
    }, form.dirty);
  };

  const valueCell = (value: number, source: StatusVariableValue): HTMLElement => el("div", "ew-variable-value",
    el("span", "", formatStatusVariableNumber(value)),
    source.kind === "formula" ? el("code", "ew-muted", source.value) : null);
  const draw = () => {
    const saved = variables(), calculated = evaluateStatusVariables(saved);
    records.replaceChildren(saved.length ? table(
      ["变量名", "类型", "基础值", "额外值", "最终值", "操作"],
      saved.map((variable, index) => {
        const value = calculated[index]!;
        return [
          el("strong", "", variable.name), variable.type === "fixed" ? "固定变量" : "变化变量",
          valueCell(value.base, variable.base), valueCell(value.extra, variable.extra),
          el("strong", "", formatStatusVariableNumber(value.final)),
          actions(
            tool(`编辑变量 ${variable.name}`, "pen", () => edit(variable)),
            tool(`删除变量 ${variable.name}`, "trash", async () => {
              if (!confirm(`删除变量“${variable.name}”？`)) return;
              ctx.guard();
              const next = variables().filter((item) => item.id !== variable.id);
              evaluateStatusVariables(next);
              state = await statusCoordinator.worldbook.saveVariables(state.worldbookName, next, variables(), ctx.guard);
              draw();
            }, "danger"),
          ),
        ];
      }), "ew-variable-table") : empty("暂无自定义变量"));
    output.textContent = renderStatusVariables(saved);
    output.parentElement!.hidden = !saved.length;
  };
  page.append(
    actions(button("新增变量", "plus", () => edit(), "primary"),
      badge(state.catalog.enabled ? "状态注入已启用" : "状态注入未启用", state.catalog.enabled ? "success" : "warning"),
      button("状态注入设置", "sliders", () => ctx.navigate("status/injection"))),
    records, section("变量注入内容", output),
  );
  draw();
  return page;
}
