import { continuitySchema, DEFAULT_CONTINUITY, refKey, type ContinuityAttributes, type MemoryLink } from "../../shared/continuity";
import { getSettings, saveSettings } from "../state/settings";
import { readMemoryLinks, saveMemoryLinks, newMemoryLink, summaryOriginalSource } from "../worldbook/memory-links";
import { readMemoryHistory } from "../worldbook/memory-history";
import type { WorldbookMemoryState } from "../worldbook/worldbook-memory";
import { SummaryWorldbookStore, type SummaryWorldbookState } from "../worldbook/summary-worldbook";
import type { SummarySlice } from "../../shared/domain";
import { recallCoordinator } from "../recall-coordinator";
import { actions, badge, button, check, detail, dialog, editDialog, el, empty, fields, local, saveForm, searchBox, section, table, tool, type ViewContext } from "./core";

const historyLabels: Record<string, string> = {
  fact_change: "事实变化", knowledge_change: "认知变化", canon_correction: "设定更正",
  unclassified: "未分类变更", deleted: "删除条目",
};
export function editContinuity(title: string, value: ContinuityAttributes | undefined, save: (value: ContinuityAttributes) => Promise<unknown>) {
  return editDialog(title, [
    ...(["eventTime", "learnedTime", "validFrom", "validUntil"] as const).map((key, index) => ({
      key, label: ["事件时间", "得知时间", "有效起点", "有效终点"][index]!, value: value?.[key] ?? "",
    })),
    { key: "validity", label: "有效状态", type: "select", value: value?.validity ?? "",
      options: [["", "未标记"], ["current", "当前资料"], ["historical", "历史经历"], ["superseded", "整条已更正失效"]] },
    { key: "changeKind", label: "本次变更性质", type: "select", value: "",
      options: [["", "未分类"], ...Object.entries(historyLabels).filter(([key]) => !["unclassified", "deleted"].includes(key))] },
    { key: "note", label: "限定与不确定性说明", type: "textarea", value: value?.note ?? "", rows: 3 },
    { key: "knowledge", label: "角色认知（JSON）", type: "json", value: value?.knowledge ?? [], rows: 8 },
  ], async (raw) => {
    const parsed = continuitySchema.parse(Object.fromEntries(Object.entries(raw).filter(([, item]) => item !== "")));
    await save(parsed);
  });
}

export function continuityExtractionSettings(ctx: ViewContext) {
  const config = getSettings().continuity ?? DEFAULT_CONTINUITY;
  const form = fields([{ key: "extractAttributes", label: "提取时间与角色认知属性", type: "checkbox", value: config.extractAttributes }]);
  return section("时间与认知", saveForm(form, (values) => {
    ctx.guard();
    const settings = getSettings();
    settings.continuity = { ...(settings.continuity ?? structuredClone(DEFAULT_CONTINUITY)), extractAttributes: values.extractAttributes };
    saveSettings(settings);
  }));
}

export function continuityRecallSettings(ctx: ViewContext) {
  const config = getSettings().continuity ?? DEFAULT_CONTINUITY;
  const form = fields([
    { key: "links", label: "补充显式关联资料", type: "checkbox", value: config.associations.enabled },
    { key: "depth", label: "最大关联深度", type: "number", min: 1, max: 3, required: true, value: config.associations.maxDepth },
    { key: "items", label: "关联资料总上限", type: "number", min: 0, max: 50, required: true, value: config.associations.maxItems },
    { key: "triggers", label: "状态驱动查询", type: "checkbox", value: config.triggers.enabled },
    { key: "queries", label: "状态查询上限", type: "number", min: 1, max: 4, required: true, value: config.triggers.maxQueries },
    { key: "days", label: "约定临近天数", type: "number", min: 0, max: 30, required: true, value: config.triggers.nearDays },
    { key: "auto", label: "命中不足时自动补充检索", type: "checkbox", value: config.supplement.auto },
    { key: "requests", label: "最多补充请求数", type: "number", min: 0, max: 3, required: true, value: config.supplement.maxRequests },
    { key: "wait", label: "补充检索总等待（毫秒）", type: "number", min: 1000, max: 120000, required: true, value: config.supplement.maxWaitMs },
    { key: "extra", label: "补充切片上限", type: "number", min: 1, max: 20, required: true, value: config.supplement.maxItems },
    { key: "hits", label: "触发补充的最低命中数", type: "number", min: 0, max: 100, required: true, value: config.supplement.minimumHits },
    { key: "paid", label: "允许补充检索调用向量与重排序端点（可能收费）", type: "checkbox", value: config.supplement.allowPaid },
  ]);
  const manual = fields([{ key: "query", label: "补充检索查询", type: "textarea", rows: 3, required: true }], false);
  const results = el("div", "ew-page-content");
  return section("连续性增强", saveForm(form, (v) => {
    ctx.guard();
    const settings = getSettings();
    settings.continuity = { ...(settings.continuity ?? structuredClone(DEFAULT_CONTINUITY)),
      associations: { enabled: v.links, maxDepth: v.depth, maxItems: v.items },
      triggers: { enabled: v.triggers, maxQueries: v.queries, nearDays: v.days },
      supplement: { auto: v.auto, maxRequests: v.requests, maxWaitMs: v.wait, maxItems: v.extra, minimumHits: v.hits, allowPaid: v.paid } };
    saveSettings(settings);
  }, "保存连续性设置"), section("手动补充检索", manual.node, actions(button("补充检索预览", "magnifying-glass", async () => {
    ctx.guard();
    if (getSettings().continuity?.supplement.allowPaid && !confirm("本次补充检索允许调用向量与重排序端点，可能产生费用，继续？")) return;
    const result = await recallCoordinator.supplementPreview(manual.values().query, ctx.signal);
    if (ctx.signal.aborted) return;
    ctx.guard();
    results.replaceChildren(badge(`请求 ${result.calls} 次 / 命中 ${result.slices.length} 条`),
      ...result.messages.map((message) => el("p", "ew-muted", message)),
      ...result.slices.map(({ slice, worldbookName, chatId }) => section(slice.timestamp + " · " + slice.title,
        badge(chatId), detail("完整正文", slice.content), button("查看批次原文", "file-lines", async () => {
          ctx.guard();
          const source = await summaryOriginalSource(slice, { worldbookName, chatId });
          ctx.guard();
          dialog("批次原文回查", el("div", "ew-page-content", badge(source.scope),
            ...source.messages.map((message) => section(message.id + " / " + message.role, el("pre", "ew-code", message.content)))));
        }))));
  })), results));
}

export async function memoryLinksView(ctx: ViewContext, state: WorldbookMemoryState): Promise<HTMLElement> {
  let snapshot = await readMemoryLinks(state.worldbookName);
  const summary = await new SummaryWorldbookStore().inspect(state.worldbookName).catch(() => null);
  const nodes = [
    ...state.rows.map((row) => ({ ref: { kind: "row" as const, id: row.id }, label: `${state.catalog.types.find((t) => t.id === row.typeId)?.name} / ${row.dataName} / ${row.id}` })),
    ...(summary?.slices ?? []).map((slice) => ({ ref: { kind: "summary" as const, id: slice.id }, label: `总结 ${slice.batch.batchNumber}.${slice.sliceNumber} / ${slice.timestamp} / ${slice.title}` })),
  ];
  const labels = new Map(nodes.map((node) => [refKey(node.ref), node.label]));
  const ui = local(ctx, "links-filter", () => ({ query: "", page: 0 }));
  const host = el("div");
  const persist = async (links: MemoryLink[]) => {
    ctx.guard();
    await saveMemoryLinks(snapshot, links);
    snapshot = await readMemoryLinks(state.worldbookName);
    draw();
  };
  const edit = (old?: MemoryLink) => editDialog(old ? "编辑关联" : "新增关联", [
    { key: "from", label: "来源记忆", type: "select", required: true, value: old ? refKey(old.from) : undefined, options: nodes.map((node) => [refKey(node.ref), node.label]) },
    { key: "to", label: "目标记忆", type: "select", required: true, value: old ? refKey(old.to) : undefined, options: nodes.map((node) => [refKey(node.ref), node.label]) },
    { key: "relation", label: "关联说明", required: true, value: old?.relation ?? "" },
    { key: "enabled", label: "启用关联", type: "checkbox", value: old?.enabled ?? true },
  ], async (v) => {
    const from = nodes.find((node) => refKey(node.ref) === v.from)?.ref;
    const to = nodes.find((node) => refKey(node.ref) === v.to)?.ref;
    if (!from || !to) throw new Error("请选择有效的关联目标。");
    const link = { ...newMemoryLink(from, to, v.relation), ...(old ? { id: old.id } : {}), enabled: v.enabled };
    await persist(old ? snapshot.links.map((item) => item.id === old.id ? link : item) : [...snapshot.links, link]);
  });
  const draw = () => {
    const all = snapshot.links.filter((link) => `${labels.get(refKey(link.from))} ${labels.get(refKey(link.to))} ${link.relation}`.toLowerCase().includes(ui.query.toLowerCase()));
    const pages = Math.max(1, Math.ceil(all.length / 50));
    ui.page = Math.min(ui.page, pages - 1);
    const prev = tool("上一页关联", "chevron-left", () => { ui.page--; draw(); });
    const next = tool("下一页关联", "chevron-right", () => { ui.page++; draw(); });
    prev.disabled = ui.page === 0; next.disabled = ui.page >= pages - 1;
    host.replaceChildren(all.length ? table(["来源", "目标", "关联", "启用", "操作"], all.slice(ui.page * 50, ui.page * 50 + 50).map((link) => [
      labels.get(refKey(link.from)) ?? `已删除：${refKey(link.from)}`, labels.get(refKey(link.to)) ?? `已删除：${refKey(link.to)}`, link.relation,
      check("启用 " + link.relation, link.enabled, (enabled) => persist(snapshot.links.map((item) => item.id === link.id ? { ...item, enabled } : item))),
      actions(tool("编辑关联", "pen", () => edit(link)), tool("删除关联", "trash", async () => {
        if (confirm("删除此关联？记忆正文保持不变。")) await persist(snapshot.links.filter((item) => item.id !== link.id));
      }, "danger")),
    ])) : empty("暂无关联"), actions(prev, badge(`${ui.page + 1} / ${pages}`), next));
  };
  draw();
  return el("div", "ew-page-content", actions(button("新增关联", "plus", () => edit(), "primary")),
    searchBox(ui.query, (value) => { ui.query = value; ui.page = 0; draw(); }, "搜索关联", ctx.signal), host);
}

export async function memoryHistoryView(ctx: ViewContext, state: WorldbookMemoryState) {
  const records = await readMemoryHistory(state.worldbookName);
  const links = await readMemoryLinks(state.worldbookName);
  const summary = await new SummaryWorldbookStore().inspect(state.worldbookName).catch(() => null);
  const ui = local(ctx, "history-filter", () => ({ query: "", page: 0 }));
  const host = el("div");
  const draw = () => {
    const all = records.filter((record) => `${record.rowId} ${record.before?.name} ${record.after?.name}`.toLowerCase().includes(ui.query.toLowerCase()));
    const pages = Math.max(1, Math.ceil(all.length / 30));
    ui.page = Math.min(ui.page, pages - 1);
    const prev = tool("上一页变化", "chevron-left", () => { ui.page--; draw(); });
    const next = tool("下一页变化", "chevron-right", () => { ui.page++; draw(); });
    prev.disabled = ui.page === 0; next.disabled = ui.page >= pages - 1;
    host.replaceChildren(all.length ? table(["记录时间", "条目", "变更性质", "对照"], all.slice(ui.page * 30, ui.page * 30 + 30).map((record) => [
      new Date(record.recordedAt).toLocaleString(), record.after?.name ?? record.before?.name ?? record.rowId,
      historyLabels[record.kind] ?? record.kind, tool("查看前后对照", "code-compare", () => {
        const affected = links.links.flatMap((link) => refKey(link.from) === `row:${record.rowId}` && link.to.kind === "summary" ? [link.to.id]
          : refKey(link.to) === `row:${record.rowId}` && link.from.kind === "summary" ? [link.from.id] : []);
        dialog("历史变化对照", el("div", "ew-page-content",
          section("修改前", el("pre", "ew-code", record.before?.content ?? "无")),
          section("修改后", el("pre", "ew-code", record.after?.content ?? "已删除")),
          detail("元数据对照", { before: record.before?.metadata, after: record.after?.metadata }),
          detail("可能受影响的显式关联切片（未自动修改）", summary?.slices.filter((slice) => affected.includes(slice.id)).map((slice) => ({ id: slice.id, title: slice.title, timestamp: slice.timestamp })) ?? [])));
      }),
    ])) : empty("暂无历史变化"), actions(prev, badge(`${ui.page + 1} / ${pages}`), next));
  };
  draw();
  return el("div", "ew-page-content", searchBox(ui.query, (value) => { ui.query = value; ui.page = 0; draw(); }, "搜索历史条目", ctx.signal), host);
}

export async function showOriginalSource(ctx: ViewContext, state: SummaryWorldbookState, slice: SummarySlice) {
  ctx.guard();
  const source = await summaryOriginalSource(slice, { worldbookName: state.worldbookName, chatId: state.catalog.chatId });
  ctx.guard();
  dialog("批次原文回查", el("div", "ew-page-content", badge(source.scope), ...source.messages.map((message) =>
    section(`${message.id} / ${message.role}`, el("pre", "ew-code", message.content)))));
}
