import type { ChatMessageInput } from "../shared/domain";

export function indexedChatMessages(): Array<{ floor: number; message: ChatMessageInput }> {
  const seen = new Set<string>();
  return SillyTavern.getContext().chat.flatMap((entry, floor) => {
    const content = String(entry.mes ?? entry.message ?? "").trim();
    if (!content) return [];
    const rawId = String(entry.message_id ?? entry.id ?? floor);
    let id = seen.has(rawId) ? `${rawId}:${floor}` : rawId;
    while (seen.has(id)) id += `:${floor}`;
    seen.add(id);
    return [{ floor, message: { id,
      role: entry.is_user === true || entry.role === "user" ? "user" as const : "assistant" as const,
      content } }];
  });
}

export function checkpointFloor(messageId?: string | null): number {
  return indexedChatMessages().find((entry) => entry.message.id === messageId)?.floor ?? -1;
}

export function checkpointMessageAtFloor(floor: number): string | null {
  if (floor === -1) return null;
  if (!Number.isInteger(floor) || floor < 0 || floor >= SillyTavern.getContext().chat.length) {
    throw new Error("检查点楼层超出当前聊天范围。");
  }
  const entry = indexedChatMessages().find((entry) => entry.floor === floor);
  if (!entry) throw new Error("该楼层没有消息正文，请选择有内容的楼层。");
  return entry.message.id;
}

export function messageRangeByFloor(start: number, end: number) {
  if (!Number.isInteger(start) || !Number.isInteger(end) || start < 0 || end < start
    || end >= SillyTavern.getContext().chat.length) throw new Error("楼层范围无效或超出当前聊天范围。");
  const indexed = indexedChatMessages();
  const startIndex = indexed.findIndex((entry) => entry.floor >= start);
  let endIndex = indexed.length - 1;
  while (endIndex >= 0 && indexed[endIndex]!.floor > end) endIndex -= 1;
  if (startIndex < 0 || endIndex < startIndex) throw new Error("所选楼层没有可处理的消息正文。");
  const messages = indexed.slice(startIndex, endIndex + 1).map((entry) => entry.message);
  if (messages.length > 500) throw new Error("单次最多处理 500 条有内容的消息，请缩小楼层范围。");
  return { startIndex, endIndex, messages };
}
