import { randomUuid } from "../../shared/crypto-compat";
import { echoesApi } from "../api/client";
import type { JobRecord } from "../../shared/domain";
import { SummaryCoordinator } from "../summary/summary-coordinator";

export type Child = Node | string | number | null | undefined | false;
export function el<K extends keyof HTMLElementTagNameMap>(
  tag: K,
  cls = "",
  ...children: Child[]
): HTMLElementTagNameMap[K] {
  const node = document.createElement(tag);
  node.className = cls;
  for (const child of children)
    if (child !== null && child !== undefined && child !== false)
      node.append(child instanceof Node ? child : String(child));
  return node;
}
export function icon(name: string): HTMLElement {
  const node = el("i", "fa-solid fa-" + name);
  node.setAttribute("aria-hidden", "true");
  return node;
}
export function button(
  label: string,
  glyph: string,
  action: () => unknown,
  variant = "",
): HTMLButtonElement {
  const b = el(
    "button",
    "ew-button " + variant,
    icon(glyph),
    label ? el("span", "", label) : null,
  );
  b.type = "button";
  b.addEventListener("click", () => {
    if (b.disabled) return;
    let result: unknown;
    try {
      result = action();
    } catch (error) {
      notifyError(error);
      return;
    }
    if (result instanceof Promise) {
      b.disabled = true;
      b.setAttribute("aria-busy", "true");
      void result.catch(notifyError).finally(() => {
        b.disabled = false;
        b.removeAttribute("aria-busy");
      });
    }
  });
  return b;
}
export function tool(
  label: string,
  glyph: string,
  action: () => unknown,
  variant = "",
): HTMLButtonElement {
  const b = button("", glyph, action, "ew-icon " + variant);
  b.title = label;
  b.setAttribute("aria-label", label);
  return b;
}
export function badge(text: string, tone = "") {
  return el("span", "ew-badge " + tone, text);
}
export function actions(...items: Child[]) {
  return el("div", "ew-actions", ...items);
}
export function section(title: string, ...children: Child[]) {
  return el("section", "ew-section", el("h2", "", title), ...children);
}
export function empty(title: string, action?: Node) {
  return el("div", "ew-empty", icon("inbox"), el("p", "", title), action);
}
export function detail(title: string, value: unknown) {
  const node = el("details", "ew-detail", el("summary", "", title));
  let rendered = false;
  node.addEventListener("toggle", () => {
    if (!node.open || rendered) return;
    node.append(el("pre", "ew-code",
      typeof value === "string" ? value : JSON.stringify(value, null, 2)));
    rendered = true;
  });
  return node;
}
export function metric(label: string, value: Child) {
  return el("div", "ew-metric", el("span", "", label), el("strong", "", value));
}
export function notify(message: string, error = false) {
  const root = document.querySelector("#echoes-workbench") ?? document.body;
  const note = el("div", "ew-toast " + (error ? "is-error" : ""), message);
  note.setAttribute("role", error ? "alert" : "status");
  root.append(note);
  setTimeout(() => note.remove(), error ? 12000 : 3500);
}
export function notifyError(error: unknown) {
  const message = error instanceof Error ? error.message : String(error);
  console.error("[Echoes] Workbench operation failed.", error);
  notify(message, true);
}
export function download(name: string, content: string) {
  const url = URL.createObjectURL(
    new Blob([content], { type: "application/json;charset=utf-8" }),
  );
  const link = el("a");
  link.href = url;
  link.download = name;
  link.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
export function readFile(accept = ".json"): Promise<File | null> {
  return new Promise((resolve) => {
    const input = el("input");
    input.type = "file";
    input.accept = accept;
    input.addEventListener("change", () => resolve(input.files?.[0] ?? null), {
      once: true,
    });
    input.addEventListener("cancel", () => resolve(null), { once: true });
    input.click();
  });
}
export const id = (prefix: string) =>
  prefix + "_" + randomUuid().replaceAll("-", "");
export const now = () => new Date().toISOString();
export const stateNames: Record<string, string> = {
  ready: "向量就绪",
  pending: "待同步",
  failed: "失败",
  ambiguous: "结果待确认",
  stale: "源消息已变化",
  running: "运行中",
  queued: "排队中",
  succeeded: "已完成",
  cancelled: "已取消",
  permanent: "常驻",
  keyword: "关键词",
  vectorized: "向量",
  pass: "正常",
  warning: "需关注",
  fail: "异常",
  unavailable: "不可用",
};
export function stateBadge(state: string) {
  return badge(
    stateNames[state] ?? state,
    ["failed", "fail"].includes(state)
      ? "danger"
      : ["ready", "succeeded", "pass"].includes(state)
        ? "success"
        : ["ambiguous", "stale", "warning"].includes(state)
          ? "warning"
          : "",
  );
}

export interface Field {
  key: string;
  label: string;
  type?:
    | "text"
    | "textarea"
    | "number"
    | "checkbox"
    | "select"
    | "password"
    | "json";
  value?: unknown;
  required?: boolean;
  min?: number;
  max?: number;
  step?: number | undefined;
  wide?: boolean;
  options?: Array<[string, string]> | undefined;
  readonly?: boolean;
  rows?: number;
}
export interface Form {
  node: HTMLFormElement;
  controls: Map<
    string,
    HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement
  >;
  values: () => Record<string, any>;
  dirty: () => boolean;
  clean: () => void;
}
export function fields(spec: Field[], trackChanges = true): Form {
  const node = el("form", "ew-form");
  node.addEventListener("submit", (event) => event.preventDefault());
  const controls = new Map<
    string,
    HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement
  >();
  let changed = false;
  for (const field of spec) {
    const type = field.type ?? "text";
    const control =
      type === "select"
        ? el("select")
        : type === "textarea" || type === "json"
          ? el("textarea")
          : el("input");
    const inputId = id("field");
    control.id = inputId;
    control.name = field.key;
    control.setAttribute("aria-label", field.label);
    if (control instanceof HTMLInputElement) {
      control.type =
        type === "checkbox" || type === "number" || type === "password"
          ? type
          : "text";
      if (type === "checkbox") control.checked = Boolean(field.value);
      if (type === "number") {
        if (field.min !== undefined) control.min = String(field.min);
        if (field.max !== undefined) control.max = String(field.max);
        control.step = String(field.step ?? 1);
      }
    }
    if (control instanceof HTMLSelectElement)
      for (const [value, label] of field.options ?? [])
        control.add(new Option(label, value));
    if (control instanceof HTMLTextAreaElement) {
      control.rows = field.rows ?? 6;
      control.spellcheck = false;
    }
    if (!(control instanceof HTMLSelectElement) || field.value !== undefined) {
      control.value = type === "json"
        ? JSON.stringify(field.value ?? null, null, 2)
        : String(field.value ?? "");
    }
    if (field.readonly) {
      if (control instanceof HTMLSelectElement) control.disabled = true;
      else control.readOnly = true;
    }
    control.required = type !== "checkbox" && Boolean(field.required);
    const label = el(
      "label",
      "ew-field " +
        (field.wide || type === "textarea" || type === "json" ? "wide " : "") +
        (type === "checkbox" ? "ew-toggle" : ""),
    );
    label.htmlFor = inputId;
    if (type === "checkbox") label.append(control, el("span", "", field.label));
    else
      label.append(
        el("span", "", field.label + (field.required ? " *" : "")),
        control,
      );
    controls.set(field.key, control);
    node.append(label);
  }
  const markChanged = () => {
    if (trackChanges && !changed) {
      changed = true;
      node.dataset.dirty = "true";
    }
  };
  node.addEventListener("input", markChanged);
  node.addEventListener("change", markChanged);
  return {
    node,
    controls,
    dirty: () => changed,
    clean: () => {
      changed = false;
      delete node.dataset.dirty;
    },
    values: () => {
      if (!node.reportValidity()) throw new Error("请检查标记的字段。");
      const result: Record<string, any> = {};
      for (const field of spec) {
        const c = controls.get(field.key)!;
        result[field.key] =
          field.type === "checkbox"
            ? (c as HTMLInputElement).checked
            : field.type === "number"
              ? c.value === ""
                ? undefined
                : Number(c.value)
              : field.type === "json"
                ? JSON.parse(c.value)
                : c.value;
      }
      return result;
    },
  };
}
export function saveForm(
  form: Form,
  save: (values: Record<string, any>) => Promise<unknown> | unknown,
  label = "保存设置",
) {
  const status = el("span", "ew-muted");
  status.setAttribute("role", "status");
  let editVersion = 0;
  const markUnsaved = () => {
    editVersion++;
    if (status.textContent !== "未保存") status.textContent = "未保存";
  };
  form.node.addEventListener("input", markUnsaved);
  form.node.addEventListener("change", markUnsaved);
  const b = button(
    label,
    "floppy-disk",
    () => form.node.requestSubmit(),
    "primary",
  );
  const footer = actions(status, b);
  footer.classList.add("ew-form-footer");
  form.node.append(footer);
  form.node.addEventListener("submit", (event) => {
    event.preventDefault();
    if (b.disabled) return;
    let values: Record<string, any>;
    try {
      values = form.values();
    } catch (e) {
      notifyError(e);
      return;
    }
    b.disabled = true;
    const savingVersion = editVersion;
    status.textContent = "保存中…";
    void Promise.resolve()
      .then(() => save(values))
      .then(() => {
        if (savingVersion === editVersion) {
          form.clean();
          status.textContent = "已保存";
        } else {
          status.textContent = "未保存";
        }
      })
      .catch((error) => {
        status.textContent = "保存失败";
        notifyError(error);
      })
      .finally(() => {
        b.disabled = false;
      });
  });
  return form.node;
}
export function dialog(
  title: string,
  body: Node,
  save?: () => Promise<unknown> | unknown,
  dirty?: () => boolean,
): HTMLDialogElement {
  const root = document.querySelector("#echoes-workbench") ?? document.body;
  const node = el("dialog", "ew-dialog");
  node.dataset.theme =
    root instanceof HTMLElement ? (root.dataset.theme ?? "dark") : "dark";
  const close = () => {
    if (!dirty?.() || window.confirm("存在未保存的修改，放弃修改？"))
      node.close();
  };
  node.append(
    el("header", "", el("h2", "", title), tool("关闭编辑器", "xmark", close)),
  );
  const content = el("div", "ew-dialog-body", body);
  const error = el("p", "ew-inline-error");
  error.setAttribute("role", "alert");
  const footer = actions(error, button("取消", "xmark", close));
  if (save)
    footer.append(
      button(
        "保存",
        "floppy-disk",
        async () => {
          try {
            await save();
            node.close();
          } catch (e) {
            error.textContent = e instanceof Error ? e.message : String(e);
            throw e;
          }
        },
        "primary",
      ),
    );
  node.append(content, el("footer", "", footer));
  node.addEventListener("cancel", (e) => {
    e.preventDefault();
    close();
  });
  node.addEventListener("close", () => node.remove(), { once: true });
  root.append(node);
  node.showModal();
  return node;
}
export function editDialog(
  title: string,
  spec: Field[],
  save: (values: Record<string, any>) => Promise<unknown> | unknown,
) {
  const form = fields(spec);
  form.node.addEventListener("submit", (e) => e.preventDefault());
  return dialog(title, form.node, () => save(form.values()), form.dirty);
}
export function table(headers: string[], rows: Child[][], className = ""): HTMLElement {
  const t = el("table", "ew-table " + className);
  const h = el("tr");
  headers.forEach((label) => {
    const th = el("th", "", label);
    th.scope = "col";
    h.append(th);
  });
  const body = el("tbody");
  rows.forEach((cells) => {
    const row = el("tr");
    cells.forEach((value, i) => {
      const td = el("td", "", value);
      td.dataset.label = headers[i] ?? "";
      row.append(td);
    });
    body.append(row);
  });
  t.append(el("thead", "", h), body);
  return el("div", "ew-table-scroll", t);
}
export function check(
  label: string,
  checked: boolean,
  change: (value: boolean) => unknown,
) {
  const input = el("input");
  input.type = "checkbox";
  input.checked = checked;
  input.setAttribute("aria-label", label);
  input.addEventListener("change", () => {
    try {
      const result = change(input.checked);
      if (result instanceof Promise)
        void result.catch((error) => {
          input.checked = !input.checked;
          notifyError(error);
        });
    } catch (error) {
      input.checked = !input.checked;
      notifyError(error);
    }
  });
  return input;
}
export function searchBox(
  value: string,
  change: (value: string) => void,
  label = "搜索",
  signal?: AbortSignal,
) {
  const input = el("input", "ew-search");
  input.type = "search";
  input.value = value;
  input.placeholder = label;
  input.setAttribute("aria-label", label);
  let timer: ReturnType<typeof setTimeout> | undefined;
  let composing = false;
  let delivered = value;
  const cancel = () => { clearTimeout(timer); timer = undefined; };
  const flush = () => {
    cancel();
    if (composing || signal?.aborted || !input.isConnected || input.value === delivered) return;
    delivered = input.value;
    change(delivered);
  };
  const schedule = () => {
    cancel();
    if (!composing && !signal?.aborted) timer = setTimeout(flush, 500);
  };
  input.addEventListener("compositionstart", () => { composing = true; cancel(); });
  input.addEventListener("compositionend", () => { composing = false; schedule(); });
  input.addEventListener("input", (event) => {
    if ((event as InputEvent).isComposing) { cancel(); return; }
    schedule();
  });
  input.addEventListener("keydown", (event) => {
    if (event.key === "Enter" && !event.isComposing && !composing) {
      event.preventDefault();
      flush();
    }
  });
  signal?.addEventListener("abort", cancel, { once: true });
  return input;
}
export function move<T>(items: T[], from: number, offset: number): T[] {
  const result = [...items];
  const to = from + offset;
  if (to < 0 || to >= result.length) return result;
  const item = result.splice(from, 1)[0]!;
  result.splice(to, 0, item);
  return result;
}
export interface ViewContext {
  route: string;
  chatId: string;
  summary: SummaryCoordinator;
  signal: AbortSignal;
  state: Map<string, unknown>;
  guard: () => void;
  refresh: () => Promise<void>;
  navigate: (route: string) => void;
  run: <T>(
    label: string,
    work: () => Promise<T>,
    stop?: () => Promise<unknown>,
  ) => Promise<T>;
  job: <T>(label: string, start: () => Promise<JobRecord<T>>) => Promise<T>;
}
export type View = (ctx: ViewContext) => Promise<HTMLElement>;
export function local<T>(ctx: ViewContext, key: string, initial: () => T): T {
  if (!ctx.state.has(key)) ctx.state.set(key, initial());
  return ctx.state.get(key) as T;
}
export async function waitJob<T>(
  initial: JobRecord<T>,
  update: (job: JobRecord<T>) => void,
  signal: AbortSignal,
): Promise<T> {
  let job = initial;
  const deadline = Date.now() + 2 * 60 * 60_000;
  while (true) {
    signal.throwIfAborted();
    update(job);
    if (job.status === "succeeded") {
      if (job.result === undefined) throw new Error("任务没有返回结果。");
      return job.result;
    }
    if (job.status === "cancelled")
      throw new DOMException(job.message || "任务已取消", "AbortError");
    if (["failed", "ambiguous"].includes(job.status))
      throw new Error(job.error?.message ?? job.message);
    if (Date.now() >= deadline)
      throw new Error("任务等待超时，请在任务日志中检查后台状态。");
    await new Promise<void>((resolve, reject) => {
      const abort = () => {
        clearTimeout(timer);
        reject(signal.reason);
      };
      const timer = setTimeout(() => {
        signal.removeEventListener("abort", abort);
        resolve();
      }, 750);
      signal.addEventListener("abort", abort, { once: true });
    });
    job = await echoesApi.getJob<T>(job.id);
  }
}
