export const echoesSettingsV2Schema = z.object({
  continuity: continuitySettingsSchema.optional(),
  extractionContext: extractionContextPolicySchema.optional(),
  taskBudget: z.object({
    maxProviderCalls: z.number().int().min(0).max(10000),
    maxInputCharacters: z.number().int().min(0).max(100_000_000),
    maxDurationMs: z.number().int().min(0).max(86_400_000),
  }).optional(),
  automaticBatchLimit: z.number().int().min(0).max(10000).optional(),
  formatVersion: z.literal(2),
  generationGroups: z.array(generationEndpointGroupSchema.safeExtend({
    endpoints: z.array(generationEndpointSchema).max(10),
  })).max(100),
  generationWorkflows: z.object({
    extraction: workflowConfigSchema,
    summary: workflowConfigSchema,
    status: workflowConfigSchema,
  }).strict(),
  extractionMessageCount: z.number().int().min(2).max(500),
  typeTemplates: z.array(memoryTypeTemplateSchema).min(1).max(500),
  statusTemplates: z.array(statusTemplateSchema).min(1).max(500),
  summary: z.object({
    batchOverviewPrompt: z.string().trim().min(1).max(100_000).default(DEFAULT_BATCH_OVERVIEW_PROMPT),
    batching: summaryBatchingSchema.optional(),
    messageCount: z.number().int().min(2).max(500),
    promptPreset: summaryPromptPresetSchema,
    preprocessRules: z.array(summaryPreprocessRuleSchema).max(200),
    embeddingGroupId: z.string().max(240),
    embeddingBatchSize: z.number().int().min(1).max(100).default(10),
  }).strict(),
  retrieval: z.object({
    failoverPolicy: failoverPolicySchema,
    embeddingGroups: z.array(embeddingEndpointGroupSchema.safeExtend({
      endpoints: z.array(retrievalEndpointSchema).max(10),
    })).max(100),
    rerankSets: z.array(rerankEndpointSetSchema.safeExtend({
      endpoints: z.array(retrievalEndpointSchema).max(10),
    })).max(100),
    query: z.object({
      vectorEnabled: z.boolean(),
      bm25Enabled: z.boolean(),
      rerankEnabled: z.boolean(),
      finalTopK: z.number().int().min(1).max(100),
    }).strict(),
    recall: z.object({
      budget: injectionBudgetSchema.optional(),
      relevanceProfiles: z.record(z.string().max(500), z.number().finite()).optional(),
      minimumRelevance: z.number().finite().default(0),
      flagRules: recallFlagRulesSchema.default([]),
      retentionMaxSlices: z.number().int().min(0).max(1000).default(20),
      queryPreset: retrievalQueryPresetSchema,
      vectorEnabled: z.boolean(),
      bm25Enabled: z.boolean(),
      rerankEnabled: z.boolean(),
      vectorTopK: z.number().int().min(1).max(200),
      bm25TopK: z.number().int().min(1).max(200),
      rerankTopK: z.number().int().min(1).max(100),
      finalTopK: z.number().int().min(1).max(100),
      rerankSetId: z.string().max(240),
      injection: retrievalInjectionConfigSchema,
    }).strict(),
  }).strict(),
}).strict().superRefine((settings, context) => {
  for (const [path, ids] of [
    ["generationGroups", settings.generationGroups.map((item) => item.id)],
    ["typeTemplates", settings.typeTemplates.map((item) => item.id)],
    ["statusTemplates", settings.statusTemplates.map((item) => item.id)],
    ["embeddingGroups", settings.retrieval.embeddingGroups.map((item) => item.id)],
    ["rerankSets", settings.retrieval.rerankSets.map((item) => item.id)],
  ] as Array<[string, string[]]>) {
    if (new Set(ids).size !== ids.length) {
      context.addIssue({ code: "custom", path: [path], message: `${path} IDs must be unique.` });
    }
  }
});

function migrateLegacySecondaryApi(raw: unknown): GenerationEndpointGroup[] {
  if (!raw || typeof raw !== "object") return [];
  const legacy = raw as Partial<SecondaryApiConfig>;
  if (!legacy.baseUrl || !legacy.model) return [];
  return [{
    id: "migrated_generation_group",
    name: "迁移的副 API",
    endpoints: [{
      id: "migrated_generation_endpoint",
      name: "原副 API",
      baseUrl: legacy.baseUrl,
      ...(legacy.apiKey ? { apiKey: legacy.apiKey } : {}),
      model: legacy.model,
      timeoutMs: legacy.timeoutMs ?? 300_000,
      temperature: legacy.temperature ?? 0.1,
      streaming: legacy.streaming ?? true,
      jsonMode: legacy.jsonMode ?? true,
      enabled: true,
      order: 0,
    }],
  }];
}

function uniqueId(prefix: string): string {
  return `${prefix}_${randomUuid().replaceAll("-", "")}`;
}

function normalizeTemplates(raw: unknown): MemoryTypeTemplate[] {
  const templates = Array.isArray(raw)
    ? raw.filter((item): item is MemoryTypeTemplate => Boolean(item && typeof item === "object"))
    : [];
  const withoutBuiltIn = templates.filter(
    (template) => !BUILT_IN_MEMORY_TEMPLATE_IDS.has(template.id),
  );
  return [
    ...structuredClone(BUILT_IN_MEMORY_TYPE_TEMPLATES),
    ...structuredClone(withoutBuiltIn),
  ];
}

function normalizeStatusTemplates(raw: unknown): StatusTemplate[] {
  const templates = Array.isArray(raw)
    ? raw.filter((item): item is StatusTemplate => Boolean(item && typeof item === "object"))
    : [];
  return [
    structuredClone(DEFAULT_STATUS_TEMPLATE),
    ...structuredClone(templates.filter((template) => template.id !== DEFAULT_STATUS_TEMPLATE_ID)),
  ];
}

function normalizeSummaryPromptPreset(raw: unknown): SummaryPromptPreset {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) {
    return structuredClone(DEFAULT_SUMMARY_PROMPT_PRESET);
  }
  const preset = raw as SummaryPromptPreset;
  const items = Array.isArray(preset.items) ? preset.items : [];
  const legacyIds = [
    "default_summary_main",
    "default_summary_character",
    "default_summary_persona",
    "default_summary_previous",
    "default_summary_messages",
  ];
  const legacyMain = items.find((item) => item.id === "default_summary_main");
  const isUntouchedLegacyDefault = preset.id === "default_summary_prompt_preset"
    && items.length === legacyIds.length
    && legacyIds.every((id, index) => items[index]?.id === id)
    && legacyMain?.kind === "custom"
    && legacyMain.content === LEGACY_DEFAULT_SUMMARY_MAIN_PROMPT;
  const versionOneIds = DEFAULT_SUMMARY_PROMPT_PRESET.items.map((item) => item.id);
  const isUntouchedVersionOneDefault = preset.id === "default_summary_prompt_preset"
    && preset.updatedAt === DEFAULT_TEMPLATE_TIME
    && items.length === versionOneIds.length
    && versionOneIds.every((id, index) => items[index]?.id === id);
  if (isUntouchedLegacyDefault || isUntouchedVersionOneDefault) {
    const migrated = structuredClone(DEFAULT_SUMMARY_PROMPT_PRESET);
    for (const item of migrated.items) {
      const previous = items.find((candidate) => candidate.id === item.id);
      if (previous) item.enabled = previous.enabled;
    }
    return migrated;
  }
  return structuredClone(preset);
}

function normalizeSettings(current: Record<string, any>): EchoesSettings {
  const configuredGroups = Array.isArray(current.generationGroups)
    ? structuredClone(current.generationGroups)
    : [];
  const migratedGroups = configuredGroups.length > 0
    ? configuredGroups
    : migrateLegacySecondaryApi(current.secondaryApi);
  const defaultGenerationGroupId = migratedGroups[0]?.id ?? "";
  const settings: EchoesSettings = {
    ...structuredClone(DEFAULT_SETTINGS),
    ...current,
    formatVersion: 2,
    extractionMessageCount: Math.max(
      2,
      Math.min(500, Math.floor(Number(current.extractionMessageCount ?? DEFAULT_SETTINGS.extractionMessageCount))),
    ),
    generationGroups: migratedGroups,
    generationWorkflows: {
      extraction: {
        groupId: current.generationWorkflows?.extraction?.groupId ?? defaultGenerationGroupId,
        failoverPolicy: current.generationWorkflows?.extraction?.failoverPolicy ?? "confirm_ambiguous",
      },
      summary: {
        groupId: current.generationWorkflows?.summary?.groupId ?? defaultGenerationGroupId,
        failoverPolicy: current.generationWorkflows?.summary?.failoverPolicy ?? "confirm_ambiguous",
      },
      status: {
        groupId: current.generationWorkflows?.status?.groupId ?? defaultGenerationGroupId,
        failoverPolicy: current.generationWorkflows?.status?.failoverPolicy ?? "confirm_ambiguous",
      },
    },
    summary: {
      ...structuredClone(DEFAULT_SETTINGS.summary),
      ...(current.summary ?? {}),
      promptPreset: normalizeSummaryPromptPreset(current.summary?.promptPreset),
      preprocessRules: Array.isArray(current.summary?.preprocessRules)
        ? structuredClone(current.summary.preprocessRules)
        : [],
    },
    retrieval: {
      ...DEFAULT_SETTINGS.retrieval,
      ...(current.retrieval ?? {}),
      embeddingGroups: Array.isArray(current.retrieval?.embeddingGroups)
        ? structuredClone(current.retrieval.embeddingGroups)
        : [],
      rerankSets: Array.isArray(current.retrieval?.rerankSets)
        ? structuredClone(current.retrieval.rerankSets)
        : [],
      query: {
        ...DEFAULT_SETTINGS.retrieval.query,
        ...(current.retrieval?.query ?? {}),
      },
      recall: {
        ...structuredClone(DEFAULT_SETTINGS.retrieval.recall),
        ...(current.retrieval?.recall ?? {}),
        queryPreset: {
          ...structuredClone(DEFAULT_SETTINGS.retrieval.recall.queryPreset),
          ...(current.retrieval?.recall?.queryPreset ?? {}),
          items: Array.isArray(current.retrieval?.recall?.queryPreset?.items)
            ? structuredClone(current.retrieval.recall.queryPreset.items)
            : structuredClone(DEFAULT_SETTINGS.retrieval.recall.queryPreset.items),
        },
        injection: {
          ...structuredClone(DEFAULT_SETTINGS.retrieval.recall.injection),
          ...(current.retrieval?.recall?.injection ?? {}),
        },
      },
    },
    typeTemplates: normalizeTemplates(current.typeTemplates),
    statusTemplates: normalizeStatusTemplates(current.statusTemplates),
  };
  delete (settings as EchoesSettings & { secondaryApi?: unknown }).secondaryApi;
  return settings;
}

export function validateEchoesSettings(settings: EchoesSettings): EchoesSettings {
  return echoesSettingsV2Schema.parse({
    ...structuredClone(settings),
    formatVersion: 2,
    typeTemplates: normalizeTemplates(settings.typeTemplates),
    statusTemplates: normalizeStatusTemplates(settings.statusTemplates),
    summary: {
      ...structuredClone(settings.summary),
      promptPreset: normalizeSummaryPromptPreset(settings.summary.promptPreset),
    },
  }) as EchoesSettings;
}

export function parseImportedSettings(raw: unknown): EchoesSettings {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) {
    throw new Error("Imported global settings must be an object.");
  }
  const record = structuredClone(raw) as Record<string, any>;
  if (record.formatVersion !== undefined && record.formatVersion !== 1 && record.formatVersion !== 2) {
    throw new Error(`Unsupported Echoes settings format: ${String(record.formatVersion)}.`);
  }
  const candidate = record.formatVersion === 2
    ? record as unknown as EchoesSettings
    : normalizeSettings(record);
  const parsed = validateEchoesSettings(candidate);
  const endpoints = [
    ...parsed.generationGroups.flatMap((group) => group.endpoints),
    ...parsed.retrieval.embeddingGroups.flatMap((group) => group.endpoints),
    ...parsed.retrieval.rerankSets.flatMap((set) => set.endpoints),
  ];
  if (endpoints.some((endpoint) => Boolean(endpoint.apiKey))) {
    throw new Error("Imported global settings must not contain inline API keys.");
  }
  return parsed;
}

export function getSettings(): EchoesSettings {
  const context = SillyTavern.getContext();
  const current = context.extensionSettings[SETTINGS_KEY] ?? {};
  return normalizeSettings(current);
}

export interface LegacyCredentialEndpoint {
  kind: "generation" | "embedding" | "rerank";
  containerId: string;
  endpointId: string;
  endpointName: string;
  apiKey: string;
}

export function legacyCredentialEndpoints(settings = getSettings()): LegacyCredentialEndpoint[] {
  const values: LegacyCredentialEndpoint[] = [];
  for (const group of settings.generationGroups) {
    for (const endpoint of group.endpoints) {
      if (endpoint.apiKey) values.push({
        kind: "generation",
        containerId: group.id,
        endpointId: endpoint.id,
        endpointName: endpoint.name,
        apiKey: endpoint.apiKey,
      });
    }
  }
  for (const group of settings.retrieval.embeddingGroups) {
    for (const endpoint of group.endpoints) {
      if (endpoint.apiKey) values.push({
        kind: "embedding",
        containerId: group.id,
        endpointId: endpoint.id,
        endpointName: endpoint.name,
        apiKey: endpoint.apiKey,
      });
    }
  }
  for (const set of settings.retrieval.rerankSets) {
    for (const endpoint of set.endpoints) {
      if (endpoint.apiKey) values.push({
        kind: "rerank",
        containerId: set.id,
        endpointId: endpoint.id,
        endpointName: endpoint.name,
        apiKey: endpoint.apiKey,
      });
    }
  }
  return values;
}

export function applyCredentialMigration(
  bindings: Array<Pick<LegacyCredentialEndpoint, "kind" | "containerId" | "endpointId"> & { credentialId: string }>,
): EchoesSettings {
  const settings = structuredClone(getSettings());
  const byEndpoint = new Map(bindings.map((binding) => [
    `${binding.kind}:${binding.containerId}:${binding.endpointId}`,
    binding.credentialId,
  ]));
  const migrate = (
    kind: LegacyCredentialEndpoint["kind"],
    containerId: string,
    endpoint: { id: string; apiKey?: string | undefined; credentialId?: string | undefined },
  ): void => {
    const credentialId = byEndpoint.get(`${kind}:${containerId}:${endpoint.id}`);
    if (!credentialId) return;
    endpoint.credentialId = credentialId;
    delete endpoint.apiKey;
  };
  for (const group of settings.generationGroups) {
    group.endpoints.forEach((endpoint) => migrate("generation", group.id, endpoint));
  }
  for (const group of settings.retrieval.embeddingGroups) {
    group.endpoints.forEach((endpoint) => migrate("embedding", group.id, endpoint));
  }
  for (const set of settings.retrieval.rerankSets) {
    set.endpoints.forEach((endpoint) => migrate("rerank", set.id, endpoint));
  }
  saveSettings(settings);
  return settings;
}

export function redactedSettings(settings = getSettings()): Record<string, unknown> {
  const copy = structuredClone(settings) as EchoesSettings;
  const redactEndpoint = (endpoint: { apiKey?: string | undefined; baseUrl: string }): void => {
    delete endpoint.apiKey;
    try {
      const url = new URL(endpoint.baseUrl);
      url.username = "";
      url.password = "";
      url.search = "";
      url.hash = "";
      endpoint.baseUrl = url.toString().replace(/\/$/, "");
    } catch {
      endpoint.baseUrl = "";
    }
  };
  for (const group of copy.generationGroups) group.endpoints.forEach(redactEndpoint);
  for (const group of copy.retrieval.embeddingGroups) group.endpoints.forEach(redactEndpoint);
  for (const set of copy.retrieval.rerankSets) set.endpoints.forEach(redactEndpoint);
  return copy as unknown as Record<string, unknown>;
}

export function saveSettings(settings: EchoesSettings): void {
  const context = SillyTavern.getContext();
  context.extensionSettings[SETTINGS_KEY] = validateEchoesSettings(settings);
  invalidateRecall();
  context.saveSettingsDebounced();
}

export function saveTypeTemplate(
  rawInput: MemoryTypeTemplateInput,
  current?: MemoryTypeTemplate,
): MemoryTypeTemplate {
  const input = memoryTypeTemplateInputSchema.parse(rawInput);
  const settings = getSettings();
  const now = new Date().toISOString();
  const template: MemoryTypeTemplate = {
    ...input,
    id: current?.id ?? input.id ?? uniqueId("template"),
    builtIn: current?.builtIn ?? false,
    version: (current?.version ?? 0) + 1,
    createdAt: current?.createdAt ?? now,
    updatedAt: now,
  };
  const index = settings.typeTemplates.findIndex((candidate) => candidate.id === template.id);
  if (index >= 0) settings.typeTemplates[index] = template;
  else settings.typeTemplates.push(template);
  saveSettings(settings);
  return structuredClone(template);
}

export function deleteTypeTemplate(templateId: string): boolean {
  if (BUILT_IN_MEMORY_TEMPLATE_IDS.has(templateId)) return false;
  const settings = getSettings();
  const originalLength = settings.typeTemplates.length;
  settings.typeTemplates = settings.typeTemplates.filter((template) => template.id !== templateId);
  if (settings.typeTemplates.length === originalLength) return false;
  saveSettings(settings);
  return true;
}

export function instantiateType(
  template: MemoryTypeTemplate,
  name = template.name.replace(/模板$/, ""),
): MemoryTypeDefinition {
  const now = new Date().toISOString();
  return {
    id: uniqueId("type"),
    templateId: template.id,
    name,
    description: template.description,
    columns: structuredClone(template.columns),
    writePrompt: template.writePrompt,
    enabled: true,
    version: 1,
    createdAt: now,
    updatedAt: now,
  };
}

function instantiateCatalogBuiltInType(
  template: MemoryTypeTemplate,
  catalog: StructuredMemoryCatalog,
): MemoryTypeDefinition {
  const baseId = `type_${template.id}`;
  let id = baseId;
  let suffix = 2;
  while (catalog.types.some((type) => type.id === id)) {
    id = `${baseId}_${suffix}`;
    suffix += 1;
  }
  const defaultName = template.name.replace(/模板$/, "");
  let name = defaultName;
  if (catalog.types.some((type) => type.name.toLocaleLowerCase() === name.toLocaleLowerCase())) {
    const baseName = `${defaultName}（内置）`;
    name = baseName;
    let nameSuffix = 2;
    while (catalog.types.some((type) => type.name.toLocaleLowerCase() === name.toLocaleLowerCase())) {
      name = `${baseName} ${nameSuffix}`;
      nameSuffix += 1;
    }
  }
  const timestamp = catalog.updatedAt || DEFAULT_TEMPLATE_TIME;
  return {
    ...instantiateType(template, name),
    id,
    createdAt: timestamp,
    updatedAt: timestamp,
  };
}

function builtInWriterPromptId(typeId: string): string {
  return `prompt_writer_${typeId}`;
}

function isUntouchedLegacyGenericType(type: MemoryTypeDefinition): boolean {
  return type.templateId === DEFAULT_TEMPLATE_ID
    && type.name === "通用记忆"
    && type.description === DEFAULT_TYPE_TEMPLATE.description
    && JSON.stringify(type.columns) === JSON.stringify(DEFAULT_TYPE_TEMPLATE.columns)
    && (type.writePrompt === DEFAULT_WRITE_PROMPT || type.writePrompt === LEGACY_WRITE_PROMPT);
}

export function refreshBuiltInMemoryPrompts(catalog: StructuredMemoryCatalog): StructuredMemoryCatalog {
  const refreshed = structuredClone(catalog);
  for (const item of refreshed.promptPreset.items) {
    if (item.kind === "main" && (
      item.content === LEGACY_MAIN_PROMPT || item.content === PREVIOUS_DEFAULT_MAIN_PROMPT
    )) {
      item.content = DEFAULT_MAIN_PROMPT;
    }
  }
  for (const type of refreshed.types) {
    if (type.templateId === DEFAULT_TEMPLATE_ID && type.writePrompt === LEGACY_WRITE_PROMPT) {
      type.writePrompt = DEFAULT_WRITE_PROMPT;
    }
  }

  if ((refreshed.builtInTypeSetVersion ?? 0) < CURRENT_BUILT_IN_MEMORY_TYPE_SET_VERSION) {
    const missingTemplates = DEFAULT_CHAT_MEMORY_TYPE_TEMPLATES.filter(
      (template) => !refreshed.types.some((type) => type.templateId === template.id),
    );
    if (missingTemplates.length > 0) {
      for (const type of refreshed.types) {
        if (isUntouchedLegacyGenericType(type)) type.enabled = false;
      }
      for (const template of missingTemplates) {
        const type = instantiateCatalogBuiltInType(template, refreshed);
        refreshed.types.push(type);
        const basePromptId = builtInWriterPromptId(type.id);
        let promptId = basePromptId;
        let suffix = 2;
        while (refreshed.promptPreset.items.some((item) => item.id === promptId)) {
          promptId = `${basePromptId}_${suffix}`;
          suffix += 1;
        }
        refreshed.promptPreset.items.push({
          id: promptId,
          kind: "type_writer",
          title: `${type.name}写表提示词`,
          role: "system",
          enabled: true,
          typeId: type.id,
        });
      }
    }
    refreshed.builtInTypeSetVersion = CURRENT_BUILT_IN_MEMORY_TYPE_SET_VERSION;
  }
  return refreshed;
}

export function createDefaultCatalog(chatId: string): StructuredMemoryCatalog {
  const now = new Date().toISOString();
  const types = DEFAULT_CHAT_MEMORY_TYPE_TEMPLATES.map((template) =>
    instantiateType(template),
  );
  const promptPreset: PromptPreset = {
    id: "default_prompt_preset",
    name: "默认增量记忆预设",
    items: [
      {
        id: "default_main_prompt",
        kind: "main",
        title: "结构化长期记忆主提示词",
        role: "system",
        enabled: true,
        content: DEFAULT_MAIN_PROMPT,
      },
      ...types.map((type) => ({
        id: builtInWriterPromptId(type.id),
        kind: "type_writer",
        title: `${type.name}写表提示词`,
        role: "system",
        enabled: true,
        typeId: type.id,
      } as const)),
    ],
    updatedAt: now,
  };
  return {
    formatVersion: 1,
    chatId,
    types,
    promptPreset,
    automation: { enabled: false },
    builtInTypeSetVersion: CURRENT_BUILT_IN_MEMORY_TYPE_SET_VERSION,
    updatedAt: now,
  };
}

