type Listener = (worldbookName?: string) => void;
const listeners = new Set<Listener>();

export function onRecallInvalidated(listener: Listener): () => void {
  listeners.add(listener);
  return () => { listeners.delete(listener); };
}

export function invalidateRecall(worldbookName?: string): void {
  for (const listener of [...listeners]) listener(worldbookName);
}
