import { sha256Hex as hashIdentifier } from "../../shared/crypto-compat";
import type {
  RetrievalDocumentInput,
  SummarySlice,
} from "../../shared/domain";

export async function summaryRetrievalDocumentId(
  collectionId: string,
  sliceId: string,
): Promise<string> {
  return `summary_doc_${(await hashIdentifier(`${collectionId}\0${sliceId}`)).slice(0, 48)}`;
}

export function summaryRetrievalText(slice: Pick<SummarySlice, "timestamp" | "title" | "content" | "retrievalText">): string {
  return `[${slice.timestamp}] ${slice.title}\n${slice.retrievalText?.trim() || slice.content}`;
}

export function buildSummaryRetrievalText(slice: SummarySlice): string {
  const keywords = slice.tags.length ? `关键词：${slice.tags.join(" / ")}\n` : "";
  return `${keywords}${slice.content}`.slice(0, 100_000);
}

export async function summaryRetrievalContentHash(
  slice: Pick<SummarySlice, "timestamp" | "title" | "content" | "retrievalText">,
): Promise<string> {
  return hashIdentifier(summaryRetrievalText(slice));
}

export async function summaryRetrievalDocument(
  collectionId: string,
  slice: SummarySlice,
  chatId: string,
): Promise<RetrievalDocumentInput> {
  return {
    documentId: await summaryRetrievalDocumentId(collectionId, slice.id),
    collectionId,
    sourceType: "chat_summary",
    sourceId: slice.id,
    text: summaryRetrievalText(slice),
    tags: slice.tags,
    metadata: {
      summaryTitle: slice.title,
      bodyHash: await hashIdentifier(slice.content),
      chatId,
      batchId: slice.batch.id,
      batchNumber: slice.batch.batchNumber,
      sliceNumber: slice.sliceNumber,
      startMessageId: slice.batch.startMessageId,
      endMessageId: slice.batch.endMessageId,
      messageIds: slice.batch.messageIds,
      sourceHash: slice.batch.sourceHash,
      revision: slice.batch.revision,
    },
  };
}
