import type { MemoryColumnDefinition, MemoryRow } from "./domain";

export interface MissingColumnValues {
  column: MemoryColumnDefinition;
  count: number;
  rowNames: string[];
}

export class MemorySchemaBackfillRequiredError extends Error {
  constructor(readonly missing: MissingColumnValues[]) {
    super(`表结构尚未保存：${missing.map(({ column, count }) => `“${column.name}”在 ${count} 条已有记录中缺值`).join("；")}。请设置有效默认值或暂设为非必填。`);
    this.name = "MemorySchemaBackfillRequiredError";
  }
}

export function checkRequiredColumnBackfill(columns: MemoryColumnDefinition[], rows: MemoryRow[]): void {
  const empty = (value: unknown) => value === undefined || value === null || value === "";
  const missing = columns.filter((column) => column.required && empty(column.defaultValue)).flatMap((column) => {
    const affected = rows.filter((row) => empty(row.values[column.id]));
    return affected.length ? [{ column, count: affected.length, rowNames: affected.slice(0, 5).map((row) => row.dataName) }] : [];
  });
  if (missing.length) throw new MemorySchemaBackfillRequiredError(missing);
}
