import type {
  GenerationEndpoint,
  RetrievalEndpoint,
  EmbeddingEndpointGroup,
  RerankEndpointSet,
} from "../../shared/domain";
import { echoesApi as api } from "../api/client";
import {
  getSettings,
  saveSettings,
  legacyCredentialEndpoints,
  applyCredentialMigration,
} from "../state/settings";
import {
  el,
  actions,
  button,
  tool,
  table,
  fields,
  saveForm,
  section,
  empty,
  detail,
  badge,
  check,
  editDialog,
  dialog,
  id,
  move,
  type ViewContext,
  type Field,
} from "./core";

const policies: Array<[string, string]> = [
  ["confirm_ambiguous", "不确定时确认"],
  ["definitive_only", "仅明确失败时切换"],
  ["always", "自动切换"],
];
export async function connectionsView(ctx: ViewContext): Promise<HTMLElement> {
  const page = el("div", "ew-page-content");
  const settings = getSettings();
  if (ctx.route === "api/workflows") {
    const options: Array<[string, string]> = [
      ["", "未配置"],
      ...settings.generationGroups.map(
        (g) => [g.id, g.name] as [string, string],
      ),
    ];
    const spec: Field[] = [];
    for (const [key, label] of [
      ["extraction", "结构化记忆提取"],
      ["summary", "总结记忆生成"],
      ["status", "状态记忆更新"],
    ] as const) {
      spec.push(
        {
          key: key + "Group",
          label: label + " · 端点组",
          type: "select",
          value: settings.generationWorkflows[key].groupId,
          options,
        },
        {
          key: key + "Policy",
          label: label + " · 故障策略",
          type: "select",
          value: settings.generationWorkflows[key].failoverPolicy,
          options: policies,
        },
      );
    }
    const f = fields(spec);
    page.append(
      section(
        "生成工作流",
        saveForm(f, (v) => {
          const s = getSettings();
          for (const k of ["extraction", "summary", "status"] as const)
            s.generationWorkflows[k] = {
              groupId: v[k + "Group"],
              failoverPolicy: v[k + "Policy"],
            };
          saveSettings(s);
        }),
      ),
    );
    const vector = fields([
      {
        key: "embedding",
        label: "总结向量化端点组",
        type: "select",
        value: settings.summary.embeddingGroupId,
        options: [
          ["", "暂不同步向量"],
          ...settings.retrieval.embeddingGroups.map(
            (g) => [g.id, g.name] as [string, string],
          ),
        ],
      },
      {
        key: "batchSize",
        label: "单次向量化切片数量",
        type: "number",
        min: 1,
        max: 100,
        value: settings.summary.embeddingBatchSize,
        required: true,
      },
      {
        key: "rerank",
        label: "总结召回重排序组",
        type: "select",
        value: settings.retrieval.recall.rerankSetId,
        options: [
          ["", "不使用"],
          ...settings.retrieval.rerankSets.map(
            (g) => [g.id, g.name] as [string, string],
          ),
        ],
      },
      {
        key: "policy",
        label: "检索故障策略",
        type: "select",
        value: settings.retrieval.failoverPolicy,
        options: policies,
      },
    ]);
    page.append(
      section(
        "向量化与检索",
        saveForm(vector, async (v) => {
          ctx.guard();
          if (ctx.chatId && v.embedding && v.embedding !== getSettings().summary.embeddingGroupId) {
            const state = await ctx.summary.load();
            if (state.slices.length || state.catalog.retrievalCollectionId) {
              if (!confirm("将当前聊天总结迁移到所选向量空间？全部校验成功后才切换绑定，过程中可停止。")) throw new Error("未更改向量配置。");
              await ctx.run("迁移总结向量空间", () => ctx.summary.migrateEmbeddingSpace(v.embedding), () => ctx.summary.stop());
              ctx.guard();
            }
          }
          const s = getSettings();
          s.summary.embeddingGroupId = v.embedding;
          s.summary.embeddingBatchSize = v.batchSize;
          s.retrieval.recall.rerankSetId = v.rerank;
          s.retrieval.failoverPolicy = v.policy;
          saveSettings(s);
        }),
      ),
    );
    const budget = settings.taskBudget;
    const limits = fields([
      { key: "calls", label: "单个后台任务请求上限（0：不限）", type: "number",
        min: 0, max: 10000, value: budget?.maxProviderCalls ?? 20, required: true },
      { key: "characters", label: "单个后台任务累计请求字符上限（0：不限）", type: "number",
        min: 0, max: 100000000, value: budget?.maxInputCharacters ?? 0, required: true },
      { key: "duration", label: "单个后台任务最长秒数（0：不限）", type: "number",
        min: 0, max: 86400, value: (budget?.maxDurationMs ?? 0) / 1000, required: true },
      { key: "batches", label: "单轮自动总结批次上限（0：不限）", type: "number",
        min: 0, max: 10000, value: settings.automaticBatchLimit ?? 5, required: true },
    ]);
    page.append(section("任务预算", saveForm(limits, (v) => {
      const s = getSettings();
      s.taskBudget = { maxProviderCalls: v.calls, maxInputCharacters: v.characters, maxDurationMs: v.duration * 1000 };
      s.automaticBatchLimit = v.batches;
      saveSettings(s);
    }), badge("已发送请求可能仍计费；不是金额上限", "warning"),
    button("查看任务用量", "list", () => ctx.navigate("maintenance/jobs"))));
    return page;
  }
  if (ctx.route === "api/credentials") {
    const credentials = await api.listCredentials();
    const edit = (current?: (typeof credentials)[number]) =>
      editDialog(
        current ? "修改凭据" : "新增凭据",
        [
          { key: "name", label: "名称", value: current?.name, required: true },
          {
            key: "secret",
            label: current ? "新密钥（留空保留）" : "API 密钥",
            type: "password",
            required: !current,
          },
        ],
        async (v) => {
          if (current)
            await api.updateCredential(current.id, {
              name: v.name,
              ...(v.secret ? { secret: v.secret } : {}),
            });
          else await api.createCredential({ name: v.name, secret: v.secret });
          await ctx.refresh();
        },
      );
    const legacy = legacyCredentialEndpoints();
    page.append(
      actions(
        button("新增凭据", "key", () => edit(), "primary"),
        legacy.length
          ? button("迁移旧凭据", "file-import", async () => {
              if (!confirm("将旧配置中的密钥迁移到服务端凭据存储？")) return;
              const bindings = legacy.map(
                ({ kind, containerId, endpointId }) => ({
                  kind,
                  containerId,
                  endpointId,
                  credentialId: id("credential"),
                }),
              );
              await api.migrateCredentials(
                legacy.map((e, i) => ({
                  id: bindings[i]!.credentialId,
                  name: e.endpointName,
                  secret: e.apiKey,
                })),
              );
              applyCredentialMigration(bindings);
              await ctx.refresh();
            })
          : null,
      ),
      credentials.length
        ? table(
            ["名称", "创建时间", "最后使用", "操作"],
            credentials.map((c) => [
              c.name,
              new Date(c.createdAt).toLocaleString(),
              c.lastUsedAt
                ? new Date(c.lastUsedAt).toLocaleString()
                : "尚未使用",
              actions(
                tool("修改凭据", "pen", () => edit(c)),
                tool(
                  "删除凭据",
                  "trash",
                  async () => {
                    const all = [
                      ...getSettings().generationGroups.flatMap(
                        (g) => g.endpoints,
                      ),
                      ...getSettings().retrieval.embeddingGroups.flatMap(
                        (g) => g.endpoints,
                      ),
                      ...getSettings().retrieval.rerankSets.flatMap(
                        (g) => g.endpoints,
                      ),
                    ];
                    if (all.some((e) => e.credentialId === c.id))
                      throw new Error(
                        "仍有端点使用此凭据，请先更换对应端点凭据。",
                      );
                    if (confirm("删除凭据 " + c.name + "？")) {
                      await api.deleteCredential(c.id);
                      await ctx.refresh();
                    }
                  },
                  "danger",
                ),
              ),
            ]),
          )
        : empty("尚未配置凭据"),
    );
    return page;
  }
  const kind = ctx.route.split("/")[1] as "generation" | "embedding" | "rerank";
  type Group = {
    id: string;
    name: string;
    endpoints: Array<GenerationEndpoint | RetrievalEndpoint>;
    embeddingSpaceId?: string | undefined;
    dimensions?: number | undefined;
    requestDimensions?: boolean | undefined;
  };
  const groups: Group[] =
    kind === "generation"
      ? settings.generationGroups
      : kind === "embedding"
        ? settings.retrieval.embeddingGroups
        : settings.retrieval.rerankSets;
  const update = (group: Group, remove = false) => {
    const s = getSettings();
    const replace = (items: Group[]) =>
      remove
        ? items.filter((x) => x.id !== group.id)
        : items.some((x) => x.id === group.id)
          ? items.map((x) => (x.id === group.id ? group : x))
          : [...items, group];
    if (kind === "generation")
      s.generationGroups = replace(s.generationGroups) as any;
    else if (kind === "embedding")
      s.retrieval.embeddingGroups = replace(s.retrieval.embeddingGroups) as any;
    else s.retrieval.rerankSets = replace(s.retrieval.rerankSets) as any;
    saveSettings(s);
  };
  const editGroup = async (group?: Group, copy = false) => {
    const inUse = kind === "embedding" && group && !copy
      ? (await api.listRetrievalCollections()).some((c) => c.collection.embeddingSpaceId === group.embeddingSpaceId)
      : false;
    return editDialog(
      copy ? "创建新向量空间" : group ? "编辑端点组" : "新增端点组",
      [
        { key: "name", label: "组名称", value: copy ? group!.name + " 副本" : group?.name, required: true },
        ...(kind === "embedding"
          ? ([
              {
                key: "embeddingSpaceId",
                label: "向量空间 ID",
                value: copy ? id("space") : group?.embeddingSpaceId ?? id("space"),
                required: true,
                readonly: !!group && !copy,
              },
              {
                key: "dimensions",
                label: "向量维度",
                type: "number",
                value: group?.dimensions ?? 1024,
                readonly: Boolean(inUse),
                min: 1,
                max: 65536,
                required: true,
              },
              {
                key: "requestDimensions",
                label: "向模型发送维度参数",
                type: "checkbox",
                value: group?.requestDimensions ?? false,
              },
            ] as Field[])
          : []),
      ],
      async (v) => {
        update({
          ...group,
          id: copy ? id("group") : group?.id ?? id("group"),
          name: v.name,
          endpoints: group?.endpoints ?? [],
          ...(kind === "embedding"
            ? {
                embeddingSpaceId: v.embeddingSpaceId,
                dimensions: v.dimensions,
                requestDimensions: v.requestDimensions,
              }
            : {}),
        });
        await ctx.refresh();
      },
    );
  };
  const editEndpoint = async (
    group: Group,
    current?: GenerationEndpoint | RetrievalEndpoint,
  ) => {
    const credentials = await api.listCredentials();
    const inUse = kind === "embedding"
      && (await api.listRetrievalCollections()).some((c) => c.collection.embeddingSpaceId === group.embeddingSpaceId);
    const c = current as GenerationEndpoint | undefined;
    const f = fields([
      { key: "name", label: "端点名称", value: current?.name, required: true },
      {
        key: "baseUrl",
        label: "API 地址",
        value: current?.baseUrl ?? "",
        required: true,
      },
      {
        key: "model",
        label: "模型名称",
        value: current?.model ?? "",
        readonly: Boolean(inUse && current),
        required: true,
      },
      {
        key: "credentialId",
        label: "凭据",
        type: "select",
        value: current?.credentialId ?? "",
        options: [
          ["", "无凭据"],
          ...credentials.map((x) => [x.id, x.name] as [string, string]),
        ],
      },
      {
        key: "timeoutMs",
        label: "超时（毫秒）",
        type: "number",
        value: current?.timeoutMs ?? 120000,
        min: kind === "generation" ? 10000 : 1000,
        max: kind === "generation" ? 1800000 : 600000,
        required: true,
      },
      {
        key: "enabled",
        label: "启用端点",
        type: "checkbox",
        value: current?.enabled ?? true,
      },
      {
        key: "allowPrivateNetwork",
        label: "允许访问私有网络",
        type: "checkbox",
        value: current?.allowPrivateNetwork ?? false,
      },
      ...(kind === "generation"
        ? ([
            {
              key: "temperature",
              label: "Temperature",
              type: "number",
              value: c?.temperature ?? 0.7,
              min: 0,
              max: 2,
              step: 0.1,
            },
            {
              key: "streaming",
              label: "流式响应",
              type: "checkbox",
              value: c?.streaming ?? false,
            },
            {
              key: "jsonMode",
              label: "JSON 响应模式",
              type: "checkbox",
              value: c?.jsonMode ?? false,
            },
          ] as Field[])
        : []),
    ]);
    const modelList = el("datalist");
    modelList.id = id("models");
    f.controls.get("model")!.setAttribute("list", modelList.id);
    const load = button("获取模型列表", "rotate", async () => {
      const result = await ctx.job("获取模型列表", () =>
        api.listEndpointModels({
          baseUrl: f.controls.get("baseUrl")!.value,
          credentialId: f.controls.get("credentialId")!.value || undefined,
          timeoutMs: Number(f.controls.get("timeoutMs")!.value),
          allowPrivateNetwork: (
            f.controls.get("allowPrivateNetwork") as HTMLInputElement
          ).checked,
        }),
      );
      modelList.replaceChildren(
        ...result.models.map((m) => {
          const o = el("option");
          o.value = m;
          return o;
        }),
      );
      load.querySelector("span")!.textContent =
        "已载入 " + result.models.length + " 个模型";
    });
    const body = el("div", "ew-page-content", f.node, actions(load), modelList);
    dialog(
      current ? "编辑端点" : "新增端点",
      body,
      async () => {
        const v = f.values();
        const { credentialId, ...rest } = v;
        if (inUse && group.endpoints.some((e) => e.model !== rest.model)) {
          throw new Error("已有集合正在使用此向量空间；更换模型请先创建新空间副本，再迁移总结。");
        }
        const endpoint = {
          ...rest,
          id: current?.id ?? id("endpoint"),
          order: current?.order ?? group.endpoints.length,
          ...(credentialId ? { credentialId } : {}),
        } as GenerationEndpoint;
        const fresh = getSettings();
        const currentGroup = (
          kind === "generation"
            ? fresh.generationGroups
            : kind === "embedding"
              ? fresh.retrieval.embeddingGroups
              : fresh.retrieval.rerankSets
        ).find((g) => g.id === group.id);
        if (!currentGroup) throw new Error("端点组已被删除。");
        const endpoints = current
          ? currentGroup.endpoints.map((e) =>
              e.id === current.id ? endpoint : e,
            )
          : [...currentGroup.endpoints, endpoint];
        update({ ...currentGroup, endpoints });
        await ctx.refresh();
      },
      f.dirty,
    );
  };
  page.append(
    actions(button("新增端点组", "plus", () => editGroup(), "primary")),
  );
  if (!groups.length) page.append(empty("尚未配置端点组"));
  for (const group of groups) {
    const endpoints = [...group.endpoints].sort((a, b) => a.order - b.order);
    page.append(
      section(
        group.name,
        actions(
          kind === "embedding"
            ? badge((group.dimensions ?? 0) + " 维 · " + group.embeddingSpaceId)
            : badge(endpoints.length + " 个端点"),
          button("添加端点", "plus", () => editEndpoint(group)),
          tool("编辑组", "pen", () => editGroup(group)),
          kind === "embedding" ? button("创建新空间副本", "copy", () => editGroup(group, true)) : null,
          tool(
            "删除组",
            "trash",
            async () => {
              const s = getSettings();
              const used =
                kind === "generation"
                  ? Object.values(s.generationWorkflows).some(
                      (w) => w.groupId === group.id,
                    )
                  : kind === "embedding"
                    ? s.summary.embeddingGroupId === group.id
                    : s.retrieval.recall.rerankSetId === group.id;
              if (used)
                throw new Error("此端点组正在被工作流使用，请先解除绑定。");
              if (confirm("删除端点组 " + group.name + "？")) {
                update(group, true);
                await ctx.refresh();
              }
            },
            "danger",
          ),
        ),
        endpoints.length
          ? table(
              ["顺序", "端点", "模型", "地址", "启用", "操作"],
              endpoints.map((endpoint, i) => [
                i + 1,
                endpoint.name,
                endpoint.model,
                endpoint.baseUrl,
                check("启用 " + endpoint.name, endpoint.enabled, (v) => {
                  endpoint.enabled = v;
                  update({ ...group, endpoints });
                }),
                actions(
                  tool("编辑端点", "pen", () => editEndpoint(group, endpoint)),
                  tool("上移端点", "arrow-up", async () => {
                    update({
                      ...group,
                      endpoints: move(endpoints, i, -1).map((e, n) => ({
                        ...e,
                        order: n,
                      })),
                    });
                    await ctx.refresh();
                  }),
                  tool("下移端点", "arrow-down", async () => {
                    update({
                      ...group,
                      endpoints: move(endpoints, i, 1).map((e, n) => ({
                        ...e,
                        order: n,
                      })),
                    });
                    await ctx.refresh();
                  }),
                  tool("测试端点", "flask", async () => {
                    const result = await ctx.job("测试 " + endpoint.name, () =>
                      kind === "generation"
                        ? api.testGenerationEndpoint(
                            endpoint as GenerationEndpoint,
                          )
                        : api.testRetrievalEndpoint({
                            kind,
                            endpoint,
                            ...(kind === "embedding" && group.requestDimensions
                              ? { requestedDimensions: group.dimensions }
                              : {}),
                          }),
                    );
                    dialog(
                      "端点测试",
                      el(
                        "div",
                        "ew-page-content",
                        badge("完成 · " + result.latencyMs + " ms", "success"),
                        result.dimensions
                          ? el("p", "", "实际维度：" + result.dimensions)
                          : null,
                        detail("尝试记录", result.attempts),
                      ),
                    );
                  }),
                  tool(
                    "删除端点",
                    "trash",
                    async () => {
                      if (confirm("删除端点 " + endpoint.name + "？")) {
                        update({
                          ...group,
                          endpoints: endpoints.filter(
                            (e) => e.id !== endpoint.id,
                          ),
                        });
                        await ctx.refresh();
                      }
                    },
                    "danger",
                  ),
                ),
              ]),
            )
          : empty("未配置端点"),
      ),
    );
  }
  return page;
}
