import { createBatchOrder, summarySuffix } from "../summary/batch-order";
import { currentChatMessages } from "../summary/summary-request";
import { summaryBatchSnapshot } from "../worldbook/summary-worldbook";
import type { SummarySlice } from "../../shared/domain";
import { getSettings, saveSettings } from "../state/settings";
import { checkpointFloor } from "../chat-message-index";
import { recallCoordinator } from "../recall-coordinator";
import { recallEnhancements, assignRecallFlags } from "./recall-enhancements";
import { recallTraceView, editRetrievalRepresentation } from "./recall-diagnostics";
import { buildSummaryRetrievalText } from "../summary/retrieval-document";
import { DEFAULT_SUMMARY_BATCHING } from "../summary/adaptive-batches";
import { summaryCoverageView } from "./summary-coverage";
import { continuityExtractionSettings, continuityRecallSettings, editContinuity, showOriginalSource } from "./continuity";
import { summaryProviderMessages } from "../../shared/summary-protocol";
import { DEFAULT_BATCH_OVERVIEW_PROMPT } from "../../shared/batch-overview";
import {
  el,
  actions,
  button,
  tool,
  table,
  fields,
  saveForm,
  section,
  empty,
  detail,
  badge,
  stateBadge,
  check,
  searchBox,
  editDialog,
  dialog,
  local,
  now,
  id,
  metric,
  injectionFields,
  notify,
  notifyError,
  type ViewContext,
} from "./core";
import {
  orderedEditor,
  promptEditor,
  promptDescription,
  ruleEditor,
} from "./editors";

export async function summaryView(ctx: ViewContext): Promise<HTMLElement> {
  if (ctx.route === "summary/coverage") return summaryCoverageView(ctx);
  const coordinator = ctx.summary;
  const page = el("div", "ew-page-content");
  const settings = getSettings();
  if (ctx.route === "summary/rules") {
    const batching = settings.summary.batching ?? DEFAULT_SUMMARY_BATCHING;
    const f = fields([
      {
        key: "count",
        label: "自动总结消息阈值",
        type: "number",
        min: 2,
        max: 500,
        value: settings.summary.messageCount,
      },
      { key: "adaptive", label: "按文本量拆分子请求", type: "checkbox", value: batching.enabled },
      { key: "characters", label: "单个子请求正文字符预算", type: "number", min: 2000, max: 200000, value: batching.maxCharacters, required: true },
      { key: "overlap", label: "相邻子请求背景重叠字符", type: "number", min: 0, max: 10000, value: batching.overlapCharacters, required: true },
      { key: "parts", label: "每批最多子请求数", type: "number", min: 1, max: 100, value: batching.maxSubBatches, required: true },
    ]);
    page.append(
      saveForm(f, (v) => {
        const s = getSettings();
        s.summary.messageCount = v.count;
        s.summary.batching = { enabled: v.adaptive, maxCharacters: v.characters, overlapCharacters: v.overlap, maxSubBatches: v.parts };
        saveSettings(s);
      }),
      actions(
        button("向量化调用配置", "arrow-up-right-from-square", () =>
          ctx.navigate("api/workflows"),
        ),
      ),
    );
    page.append(continuityExtractionSettings(ctx));
    return page;
  }
  if (ctx.route === "summary/prompts") {
    const overviewPrompt = fields([{ key: "prompt", label: "批次总结独立提示词", type: "textarea",
      rows: 16, value: settings.summary.batchOverviewPrompt ?? DEFAULT_BATCH_OVERVIEW_PROMPT, required: true }]);
    page.append(
      orderedEditor(
        ctx,
        "提示词",
        settings.summary.promptPreset.items,
        promptDescription,
        promptEditor("summary"),
        (items) => {
          const s = getSettings();
          s.summary.promptPreset = {
            ...s.summary.promptPreset,
            items,
            updatedAt: now(),
          };
          saveSettings(s);
        },
      ),
      button("预览待总结请求", "eye", () => ctx.navigate("summary/tasks")),
      section("批次总结提示词", saveForm(overviewPrompt, (v) => {
        const s = getSettings();
        s.summary.batchOverviewPrompt = v.prompt;
        saveSettings(s);
      }, "保存批次总结提示词"), button("恢复内置批次总结提示词", "rotate-left", async () => {
        if (!confirm("恢复内置批次总结提示词？")) return;
        const s = getSettings();
        s.summary.batchOverviewPrompt = DEFAULT_BATCH_OVERVIEW_PROMPT;
        saveSettings(s);
        await ctx.refresh();
      })),
    );
    return page;
  }
  if (ctx.route === "summary/cleaning") {
    page.append(
      orderedEditor(
        ctx,
        "规则",
        settings.summary.preprocessRules,
        (r) => [r.name, r.type],
        ruleEditor,
        (items) => {
          const s = getSettings();
          s.summary.preprocessRules = items.map((r, i) => ({ ...r, order: i }));
          saveSettings(s);
        },
      ),
    );
    return page;
  }
  const state = await coordinator.load();
  if (ctx.signal.aborted) return page;
  if (ctx.route === "summary/recall") return recallView(ctx, state);
  if (ctx.route === "summary/tasks") {
    const checkpoint = checkpointFloor(state.catalog.lastCommittedMessageId);
    const lastFloor = Math.max(0, SillyTavern.getContext().chat.length - 1);
    const f = fields(
      [
        {
          key: "start",
          label: "起始楼层",
          type: "number",
          min: 0,
          max: lastFloor,
          value: Math.min(checkpoint + 1, lastFloor),
          required: true,
        },
        {
          key: "end",
          label: "结束楼层",
          type: "number",
          min: 0,
          max: lastFloor,
          value: lastFloor,
          required: true,
        },
      ],
      false,
    );
    const metrics = el("div", "ew-metrics");
    const updateMetrics = (latest: typeof state) => {
      if (ctx.signal.aborted || latest.worldbookName !== state.worldbookName) return;
      state.catalog = latest.catalog;
      const floor = checkpointFloor(latest.catalog.lastCommittedMessageId);
      metrics.replaceChildren(
        metric("聊天消息", SillyTavern.getContext().chat.length),
        metric("检查点", !latest.catalog.lastCommittedMessageId ? "尚未处理" : floor < 0 ? "原消息已不存在" : `第 ${floor} 楼`),
        metric("下一批次", latest.catalog.nextBatchNumber),
      );
    };
    updateMetrics(state);
    const unsubscribe = coordinator.subscribeProgress(updateMetrics);
    ctx.signal.addEventListener("abort", unsubscribe, { once: true });
    page.append(
      metrics,
      actions(button("修改检查点", "pen", () => editDialog("修改总结检查点", [
        { key: "floor", label: "检查点楼层（-1：尚未处理）", type: "number", min: -1,
          max: SillyTavern.getContext().chat.length - 1,
          value: checkpointFloor(state.catalog.lastCommittedMessageId), required: true },
      ], async (v) => {
        ctx.guard();
        if (!confirm("修改检查点会关闭自动总结，保留已有切片。下一次从所选楼层之后开始，继续？")) return;
        await coordinator.relocateCheckpointToFloor(v.floor);
        await ctx.refresh();
      }))),
      section(
        "手动生成",
        f.node,
        actions(
          button("预览输入", "eye", async () => {
            const v = f.values();
            ctx.guard();
            const request = await coordinator.previewManual(v.start, v.end);
            dialog("总结输入预览", detail("最终提示词与消息", { ...request,
              providerMessages: summaryProviderMessages({ promptMessages: request.promptMessages,
                extractAttributes: getSettings().continuity?.extractAttributes ?? false }) }));
          }),
          button(
            "生成总结",
            "play",
            async () => {
              const v = f.values();
              ctx.guard();
              await ctx.run(
                "总结 " + v.start + "–" + v.end,
                () => coordinator.runManual(v.start, v.end),
                () => coordinator.stop(),
              );
              await ctx.refresh();
            },
            "primary",
          ),
          button("停止总结", "stop", () => coordinator.stop(), "danger"),
        ),
      ),
      section(
        "自动运行",
        actions(
          el(
            "label",
            "ew-toggle",
            check("自动总结", state.catalog.autoRun, async (v) => {
              ctx.guard();
              await ctx.run("更新自动总结设置", () =>
                coordinator.setAutoRun(v),
              );
              if (v)
                void ctx
                  .run(
                    "自动总结",
                    () => coordinator.runAutomatic(),
                    () => coordinator.stop(),
                  )
                  .catch(notifyError);
            }),
            "自动总结",
          ),
          button("检查待处理消息", "rotate", () =>
            ctx
              .run(
                "自动总结",
                () => coordinator.runAutomatic(),
                () => coordinator.stop(),
              )
              .then(() => ctx.refresh()),
          ),
        ),
      ),
    );
    const batch = fields([
      {
        key: "number",
        label: "下一批次编号",
        type: "number",
        min: 1,
        value: state.catalog.nextBatchNumber,
        required: true,
      },
    ]);
    page.append(
      section(
        "批次编号",
        saveForm(
          batch,
          async (v) => {
            ctx.guard();
            await coordinator.setNextBatchNumber(v.number);
          },
          "设置编号",
        ),
      ),
    );
    return page;
  }
  if (ctx.route === "summary/hiding") {
    const status = await coordinator.compression.inspect(state);
    const c = state.catalog.compression;
    const f = fields([
      { key: "enabled", label: "自动隐藏", type: "checkbox", value: c.enabled },
      {
        key: "keepRecentMessages",
        label: "保留最近原消息数",
        type: "number",
        min: 0,
        max: 1000,
        value: c.keepRecentMessages,
      },
      {
        key: "recentBatchCount",
        label: "固定近期总结批次数",
        type: "number",
        min: 0,
        max: 100,
        value: c.recentBatchCount,
      },
      {
        key: "deletionPolicy",
        label: "删除总结时",
        type: "select",
        value: c.deletionPolicy,
        options: [
          ["restore_first", "先恢复对应原消息"],
          ["confirm_restore", "每次确认处理方式"],
          ["keep_hidden", "保留隐藏状态"],
        ],
      },
    ]);
    page.append(
      el(
        "div",
        "ew-metrics",
        metric("已隐藏原消息", status.hidden),
        metric("固定可见", status.pinned),
        metric("可隐藏", status.compressible),
        metric("召回", state.catalog.recallEnabled ? "已启用" : "未启用"),
      ),
      ...(status.blockedReason
        ? [el("p", "ew-muted", status.blockedReason)]
        : []),
      section(
        "隐藏策略",
        saveForm(f, async (v) => {
          ctx.guard();
          await coordinator.saveCompression(v as any);
          await ctx.refresh();
        }),
        actions(
          button("重新应用隐藏", "arrows-rotate", async () => {
            ctx.guard();
            const result = await ctx.run("重新应用隐藏", () => coordinator.compression.reconcile());
            notify(result.blockedReason ?? `已应用隐藏策略：已隐藏 ${result.hidden} 条，固定可见 ${result.pinned} 条。`);
            await ctx.refresh();
          }),
          button("召回设置", "arrow-up-right-from-square", () =>
            ctx.navigate("summary/recall"),
          ),
        ),
      ),
    );
    const range = fields([
      {
        key: "start",
        label: "起始楼层",
        type: "number",
        min: 0,
        value: 0,
        required: true,
      },
      {
        key: "end",
        label: "结束楼层",
        type: "number",
        min: 0,
        value: Math.max(0, SillyTavern.getContext().chat.length - 1),
        required: true,
      },
    ]);
    page.append(
      section(
        "恢复原消息",
        range.node,
        actions(
          button("恢复选定范围", "eye", async () => {
            const v = range.values();
            ctx.guard();
            await coordinator.compression.restoreRange(state, v.start, v.end);
            await ctx.refresh();
          }),
          button("恢复全部原消息", "eye", async () => {
            if (confirm("恢复所有由 Echoes 隐藏的原消息？")) {
              ctx.guard();
              await coordinator.compression.restoreAll(state);
              await ctx.refresh();
            }
          }),
        ),
      ),
    );
    return page;
  }
  const ui = local(ctx, "summary-list", () => ({
    query: "",
    status: "all",
    selected: new Set<string>(),
    expanded: new Set<string>(),
    page: 0,
  }));
  const ids = new Set(state.slices.map((s) => s.id));
  for (const selected of ui.selected)
    if (!ids.has(selected)) ui.selected.delete(selected);
  const slicesByBatch = new Map<string, SummarySlice[]>();
  for (const slice of state.slices) {
    const batch = slicesByBatch.get(slice.batch.id);
    if (batch) batch.push(slice);
    else slicesByBatch.set(slice.batch.id, [slice]);
  }
  const groups = [...slicesByBatch.values()]
    .sort((a, b) => b[0]!.batch.batchNumber - a[0]!.batch.batchNumber);
  let compression:
    | Awaited<ReturnType<typeof coordinator.compression.inspectVisibility>>
    | undefined;
  try {
    compression = await coordinator.compression.inspectVisibility(state);
  } catch {}
  if (ctx.signal.aborted) return page;
  const visibilityByBatch = new Map(compression?.map((batch) => [batch.batchId, batch]));
  const host = el("div");
  const openOverview = (batch: SummarySlice["batch"]) => {
    let overview = state.batchOverviews?.find((item) => item.batch.id === batch.id);
    const body = el("div", "ew-page-content");
    const status = !overview ? "尚未生成" : overview.state === "ready" ? "已生成" : overview.state === "failed" ? "生成失败" : "待生成或生成中";
    body.append(actions(badge(status), el("label", "ew-toggle",
      check("常驻批次总结", overview?.enabled ?? true, async (enabled) => {
        ctx.guard();
        const updated = await coordinator.store.saveBatchOverview(state, batch.id, { enabled });
        state.batchOverviews = updated.batchOverviews ?? [];
        overview = state.batchOverviews.find((item) => item.batch.id === batch.id);
        draw();
      }), "常驻批次总结")));
    if (overview?.error) body.append(el("p", "ew-muted", overview.error));
    if (batch.state === "stale" || overview && overview.batch.sourceHash !== batch.sourceHash) {
      body.append(badge("原消息已变化；当前保留旧批次总结，请核对后重建批次", "warning"));
    }
    if (overview?.content && overview.state !== "ready") body.append(badge("当前保留上次正文", "warning"));
    if (overview?.content) {
      const text = el("div", "ew-batch-overview-text", overview.content);
      text.style.whiteSpace = "pre-wrap";
      text.style.overflowWrap = "anywhere";
      body.append(text);
    } else body.append(empty("暂无批次总结正文"));
    body.append(actions(button(overview?.content ? "重新生成批次总结" : "生成批次总结", "rotate", async () => {
      ctx.guard();
      if (!confirm("将单独调用总结生成副 API，可能产生费用；不会重新生成常规切片。继续？")) return;
      modal.close();
      await ctx.run("生成批次总结", () => coordinator.regenerateBatchOverview(batch.id), () => coordinator.stop());
      await ctx.refresh();
    }), button("编辑批次总结", "pen", () => editDialog("编辑批次总结 " + batch.batchNumber, [
      { key: "content", label: "正文", type: "textarea", rows: 20, value: overview?.content ?? "", required: true },
    ], async (v) => {
      ctx.guard();
      await coordinator.store.saveBatchOverview(state, batch.id, { content: v.content.trim(), state: "ready" });
      modal.close();
      await ctx.refresh();
    }))));
    const modal = dialog("批次总结 " + batch.batchNumber, body);
  };
  const selection = el("div", "ew-selection ew-summary-selection");
  const edit = (slice: SummarySlice) =>
    editDialog(
      "编辑切片 " + slice.batch.batchNumber + "." + slice.sliceNumber,
      [
        {
          key: "timestamp",
          label: "独立时间戳",
          value: slice.timestamp,
          required: true,
        },
        { key: "title", label: "标题", value: slice.title, required: true },
        {
          key: "tags",
          label: "标签（每行一项）",
          type: "textarea",
          value: slice.tags.join("\n"),
          rows: 3,
        },
        {
          key: "content",
          label: "正文",
          type: "textarea",
          value: slice.content,
          rows: 20,
          required: true,
        },
      ],
      async (v) => {
        ctx.guard();
        await ctx.run("保存并同步切片", () =>
          coordinator.editSlice(slice.id, {
            timestamp: v.timestamp,
            title: v.title,
            content: v.content,
            tags: v.tags
              .split("\n")
              .map((x: string) => x.trim())
              .filter(Boolean),
          }, slice.batch.revision),
        );
        await ctx.refresh();
      },
    );
  const operate = async (action: string, slices: SummarySlice[]) => {
    ctx.guard();
    if (!slices.length) return;
    const batches = [
      ...new Map(slices.map((s) => [s.batch.id, s.batch])).values(),
    ].sort(createBatchOrder(currentChatMessages()).compare);
    const batchIds = batches.map((b) => b.id);
    if (action === "representation") {
      if (!confirm(`从正文与标签重建 ${slices.length} 个切片的检索表示？将覆盖已有自定义表示，不修改正文，也不调用模型。`)) return;
      await coordinator.saveRetrievalTexts(state, new Map(slices.map((slice) => [slice.id, buildSummaryRetrievalText(slice)])));
    } else if (action === "sync") {
      if (!confirm(`同步 ${slices.length} 个选中切片的索引，可能产生向量化费用。继续？`)) return;
      await ctx.run("同步选中切片索引", () => coordinator.synchronizeSlices(slices.map((slice) => slice.id)), () => coordinator.stop());
    } else if (action === "delete") {
      if (
        !confirm(
          "删除 " +
            slices.length +
            " 个切片，涉及 " +
            batches.length +
            " 个批次？清空整个批次时也会删除对应批次总结。",
        )
      )
        return;
      const policy = state.catalog.compression.deletionPolicy;
      if (
        policy === "restore_first" ||
        (policy === "confirm_restore" && confirm("同时恢复这些批次的原消息？"))
      ) {
        ctx.guard();
        await coordinator.compression.restoreBatch(state, batchIds);
      }
      ctx.guard();
      await ctx.run("删除总结切片", () =>
        coordinator.deleteSlices(slices.map((s) => s.id)),
      );
      ui.selected.clear();
    } else if (action === "reset") {
      const start = batches[0]!.batchNumber;
      const affected = summarySuffix(state.slices, start, currentChatMessages());
      if (
        !confirm(
          "从批次 " +
            start +
            " 重置，将清除后续 " +
            affected.length +
            " 个生成切片及对应批次总结，并恢复对应原消息。继续？",
        )
      )
        return;
      ctx.guard();
      await coordinator.compression.restoreBatch(state, [
        ...new Set(affected.map((s) => s.batch.id)),
      ]);
      ctx.guard();
      await coordinator.resetFrom(start);
      ui.selected.clear();
    } else if (action === "rebuild") {
      if (batches.some((b) => b.source?.kind === "imported"))
        throw new Error("导入批次没有原聊天消息，不能重新总结。");
      if (
        !confirm("重新总结 " + batches.length + " 个批次会调用生成模型，继续？")
      )
        return;
      await ctx.run(
        "批量重新总结",
        () => coordinator.rebuildBatches(batches.map((b) => b.batchNumber)),
        () => coordinator.stop(),
      );
    } else if (action === "restore") {
      await coordinator.compression.restoreBatch(state, batchIds);
    } else if (action === "hide") {
      await coordinator.compression.recompressBatch(state, batchIds);
    }
    await ctx.refresh();
  };
  const drawSelection = () => {
    const selected = state.slices.filter((s) => ui.selected.has(s.id));
    selection.hidden = !selected.length;
    const commands: Array<[string, string, () => unknown, string?]> = [
      ["重新总结批次", "rotate", () => operate("rebuild", selected)],
      ["设置标志", "flag", () => assignRecallFlags(ctx, state, selected)],
      ["重建检索表示", "file-lines", () => operate("representation", selected)],
      ["同步选中索引", "arrows-rotate", () => operate("sync", selected)],
      ["恢复原消息", "eye", () => operate("restore", selected)],
      ["重新隐藏", "eye-slash", () => operate("hide", selected)],
      ["从最早批次重置", "rotate-left", () => operate("reset", selected), "danger"],
      ["删除切片", "trash", () => operate("delete", selected), "danger"],
    ];
    const commandButtons = (before?: () => void) => commands.map(([label, icon, run, variant]) =>
      button(label, icon, () => { before?.(); return run(); }, variant));
    const inline = actions(...commandButtons());
    inline.classList.add("ew-bulk-inline");
    const compact = button("批量操作", "list-check", () => {
      const modal = dialog("批量操作 · " + selected.length + " 个切片",
        el("div", "ew-bulk-commands", ...commandButtons(() => modal.close())));
      modal.setAttribute("aria-label", "批量操作");
    }, "ew-bulk-mobile");
    selection.replaceChildren(
      el(
        "strong",
        "ew-selection-count",
        "已选 " +
          selected.length +
          " 个切片 · " +
          new Set(selected.map((s) => s.batch.id)).size +
          " 个批次",
      ),
      inline,
      compact,
      tool("取消选择", "xmark", () => {
        ui.selected.clear();
        draw();
      }),
    );
  };
  const draw = () => {
    drawSelection();
    host.replaceChildren();
    const visible = groups
      .map((slices) =>
        slices.filter(
          (s) =>
            (ui.status === "all" || s.batch.state === ui.status) &&
            (!ui.query || [s.title, s.content, s.timestamp, ...s.tags]
              .join(" ")
              .toLowerCase()
              .includes(ui.query.toLowerCase())),
        ),
      )
      .filter((s) => s.length);
    const totalPages = Math.max(1, Math.ceil(visible.length / 20));
    ui.page = Math.min(ui.page, totalPages - 1);
    if (!visible.length) {
      host.append(
        empty(
          "没有匹配的总结记录",
          button("生成总结", "plus", () => ctx.navigate("summary/tasks")),
        ),
      );
      return;
    }
    for (const slices of visible.slice(ui.page * 20, (ui.page + 1) * 20)) {
      const b = slices[0]!.batch;
      const all = slicesByBatch.get(b.id)!;
      const c = visibilityByBatch.get(b.id);
      const head = el(
        "div",
        "ew-batch-head",
        actions(
          check(
            "选择批次 " + b.batchNumber,
            slices.every((s) => ui.selected.has(s.id)),
            (v) => {
              slices.forEach((s) =>
                v ? ui.selected.add(s.id) : ui.selected.delete(s.id),
              );
              draw();
            },
          ),
          button(
            "批次 " + b.batchNumber,
            ui.expanded.has(b.id) ? "chevron-down" : "chevron-right",
            () => {
              ui.expanded.has(b.id)
                ? ui.expanded.delete(b.id)
                : ui.expanded.add(b.id);
              draw();
            },
          ),
          badge(all.length + " 个切片"),
          button("批次总结", "file-lines", () => openOverview(b)),
          badge((() => {
            const item = state.batchOverviews?.find((overview) => overview.batch.id === b.id);
            return !item ? "批次总结未生成" : item.state === "failed" ? "批次总结失败"
              : item.state === "pending" ? "批次总结待生成" : item.enabled ? "批次总结常驻" : "批次总结已关闭";
          })()),
          el("span", "ew-muted", b.startMessageId + " – " + b.endMessageId),
        ),
        actions(
          badge(
            "向量就绪 " +
              all.filter((s) => s.batch.state === "ready").length +
              " / " +
              all.length,
          ),
          el(
            "span",
            "ew-muted",
            c
              ? "已隐藏 " + c.hidden + " / " + c.covered + " 条原消息"
              : "隐藏状态不可用",
          ),
          tool("重新总结此批次", "rotate", () => operate("rebuild", all)),
          tool("恢复此批次原消息", "eye", () => operate("restore", all)),
          tool("检查此批次覆盖", "magnifying-glass", () => {
            ctx.state.set("summary-coverage-range", { start: checkpointFloor(b.startMessageId),
              end: checkpointFloor(b.endMessageId), instructions: "" });
            ctx.navigate("summary/coverage");
          }),
        ),
      );
      const group = el("section", "ew-batch", head);
      if (ui.expanded.has(b.id) || ui.query)
        group.append(
          table(
            ["选择", "切片", "故事时间", "标题", "向量状态", "操作"],
            slices.map((s) => [
              check("选择切片 " + s.sliceNumber, ui.selected.has(s.id), (v) => {
                v ? ui.selected.add(s.id) : ui.selected.delete(s.id);
                drawSelection();
              }),
              b.batchNumber + "." + s.sliceNumber,
              s.timestamp,
              s.title,
              stateBadge(s.batch.state),
              actions(
                tool("编辑切片", "pen", () => edit(s)),
                tool("时间与认知属性", "clock", () => editContinuity(s.title + " · 时间与认知", s.continuity, async (continuity) => {
                  ctx.guard();
                  await coordinator.store.saveSlice(state.worldbookName, s.id, {
                    timestamp: s.timestamp, title: s.title, content: s.content, tags: s.tags, continuity,
                  }, s.batch.revision);
                  await ctx.refresh();
                })),
                tool("查看批次原文", "file-lines", () => showOriginalSource(ctx, state, s)),
                tool("编辑检索表示", "file-lines", () => editRetrievalRepresentation(ctx, state, s)),
                tool("设置标志", "flag", () => assignRecallFlags(ctx, state, [s])),
                tool(
                  "删除切片",
                  "trash",
                  () => operate("delete", [s]),
                  "danger",
                ),
              ),
            ]),
            "ew-summary-table",
          ),
        );
      host.append(group);
    }
    host.append(
      actions(
        button("上一页", "chevron-left", () => {
          ui.page = Math.max(0, ui.page - 1);
          draw();
        }),
        el("span", "ew-muted", ui.page + 1 + " / " + totalPages + " 页"),
        button("下一页", "chevron-right", () => {
          ui.page = Math.min(totalPages - 1, ui.page + 1);
          draw();
        }),
      ),
    );
  };
  const filter = fields(
    [
      {
        key: "state",
        label: "向量状态",
        type: "select",
        value: ui.status,
        options: [
          ["all", "全部"],
          ["ready", "就绪"],
          ["pending", "待同步"],
          ["failed", "失败"],
          ["ambiguous", "待确认"],
          ["stale", "源消息变化"],
        ],
      },
    ],
    false,
  );
  filter.controls.get("state")!.addEventListener("change", () => {
    ui.status = filter.controls.get("state")!.value;
    ui.page = 0;
    draw();
  });
  page.append(
    el(
      "div",
      "ew-toolbar",
      searchBox(
        ui.query,
        (v) => {
          ui.query = v;
          ui.page = 0;
          draw();
        },
        "搜索标题、正文或时间",
        ctx.signal,
      ),
      actions(
        filter.node,
        button("修复索引", "screwdriver-wrench", () =>
          ctx
            .run("修复总结索引", () => coordinator.repairIndex(), () => coordinator.stop())
            .then(() => ctx.refresh()),
        ),
        button(
          "生成总结",
          "plus",
          () => ctx.navigate("summary/tasks"),
          "primary",
        ),
      ),
    ),
    actions(
      button("选择筛选结果", "check-double", () => {
        state.slices
          .filter(
            (s) =>
              (ui.status === "all" || s.batch.state === ui.status) &&
              [s.title, s.content, s.timestamp, ...s.tags]
                .join(" ")
                .toLowerCase()
                .includes(ui.query.toLowerCase()),
          )
          .forEach((s) => ui.selected.add(s.id));
        draw();
      }),
    ),
    selection,
    host,
  );
  draw();
  for (const draft of coordinator.rebuildDrafts()) {
    const current = state.slices.filter((slice) => slice.batch.id === draft.batch.id);
    const expected = summaryBatchSnapshot(state.slices, draft.batch.id);
    page.append(section(`批次 ${draft.batch.batchNumber} 重建候选（未写入）`,
      actions(button("核对正文", "eye", () => dialog("重建冲突对照",
        el("div", "", detail("当前已保存切片", current), detail("待确认生成结果", draft.candidates)))),
      button("确认替换该批次", "floppy-disk", async () => {
        ctx.guard();
        if (!confirm("用这些候选替换该批次的当前正文？不会重新生成切片，但会单独调用总结副 API 生成批次总结；未确认对应的关联不会自动迁移。")) return;
        await ctx.run("保存重建候选与批次总结", () => coordinator.commitRebuildDraft(draft.batch.id, expected), () => coordinator.stop());
        await ctx.refresh();
      }),
      button("丢弃候选", "trash", async () => {
        ctx.guard();
        if (!confirm("丢弃本次会话保留的重建候选？")) return;
        coordinator.discardRebuildDraft(draft.batch.id);
        await ctx.refresh();
      }, "danger"))));
  }
  return page;
}

async function recallView(
  ctx: ViewContext,
  state: Awaited<ReturnType<ViewContext["summary"]["load"]>>,
): Promise<HTMLElement> {
  const page = el("div", "ew-page-content");
  const panels = {
    strategy: el("div", "ew-page-content"),
    enhancements: el("div", "ew-page-content"),
    continuity: el("div", "ew-page-content"),
    query: el("div", "ew-page-content"),
    injection: el("div", "ew-page-content"),
  };
  const sections = [
    ["strategy", "检索排序"], ["enhancements", "来源与标志"],
    ["continuity", "连续性增强"], ["query", "查询编排"], ["injection", "预算与注入"],
  ] as const;
  const tabList = el("div", "ew-page-tabs");
  tabList.setAttribute("role", "tablist");
  tabList.setAttribute("aria-label", "召回设置分区");
  const tabs = new Map<string, HTMLButtonElement>();
  const selectSection = (key: string) => {
    for (const [name] of sections) {
      const active = name === key;
      panels[name].hidden = !active;
      const tab = tabs.get(name)!;
      tab.setAttribute("aria-selected", String(active));
      tab.tabIndex = active ? 0 : -1;
    }
    ctx.state.set("recall-section", key);
  };
  sections.forEach(([key, label], index) => {
    const panel = panels[key];
    const tab = button(label, "", () => selectSection(key), "ew-page-tab");
    tab.querySelector("i")?.remove();
    tab.id = id("recall_tab");
    panel.id = id("recall_panel");
    tab.setAttribute("role", "tab");
    tab.setAttribute("aria-controls", panel.id);
    panel.setAttribute("role", "tabpanel");
    panel.setAttribute("aria-labelledby", tab.id);
    panel.tabIndex = 0;
    tab.addEventListener("keydown", (event) => {
      if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) return;
      event.preventDefault();
      const next = event.key === "Home" ? 0 : event.key === "End" ? sections.length - 1
        : (index + (event.key === "ArrowRight" ? 1 : -1) + sections.length) % sections.length;
      const target = sections[next]![0];
      selectSection(target);
      tabs.get(target)!.focus();
    });
    tabs.set(key, tab);
    tabList.append(tab);
  });
  const active = local(ctx, "recall-section", () => "strategy");
  selectSection(sections.some(([key]) => key === active) ? active : "strategy");
  page.append(tabList, ...Object.values(panels));
  const settings = getSettings();
  const r = settings.retrieval.recall;
  const f = fields([
    {
      key: "enabled",
      label: "当前聊天总结召回",
      type: "checkbox",
      value: state.catalog.recallEnabled,
    },
    { key: "minimumRelevance", label: "最低相关性（0：不启用）", type: "number", step: 0.001,
      value: r.minimumRelevance ?? 0 },
    {
      key: "vectorEnabled",
      label: "向量检索",
      type: "checkbox",
      value: r.vectorEnabled,
    },
    {
      key: "bm25Enabled",
      label: "BM25 文本检索",
      type: "checkbox",
      value: r.bm25Enabled,
    },
    {
      key: "rerankEnabled",
      label: "结果重排序",
      type: "checkbox",
      value: r.rerankEnabled,
    },
    ...(["vectorTopK", "bm25TopK", "rerankTopK", "finalTopK"] as const).map(
      (key) => ({
        key,
        label: {
          vectorTopK: "向量候选数",
          bm25TopK: "BM25 候选数",
          rerankTopK: "重排序候选数",
          finalTopK: "最终结果数",
        }[key],
        type: "number" as const,
        min: 1,
        max: key === "vectorTopK" || key === "bm25TopK" ? 200 : 100,
        value: r[key],
      }),
    ),
  ]);
  f.controls.get("enabled")!.closest("label")!.classList.add("wide");
  for (const [title, keys] of [
    ["候选检索", ["vectorEnabled", "vectorTopK", "bm25Enabled", "bm25TopK"]],
    ["结果重排序", ["rerankEnabled", "rerankTopK"]],
    ["结果输出与过滤", ["finalTopK", "minimumRelevance"]],
  ] as const) {
    const group = el("fieldset", "ew-recall-stage", el("legend", "", title));
    for (const key of keys) group.append(f.controls.get(key)!.closest("label")!);
    f.node.append(group);
  }
  panels.strategy.append(
    section(
      "召回策略",
      saveForm(f, async (v) => {
        ctx.guard();
        const s = getSettings();
        for (const k of [
          "vectorEnabled",
          "bm25Enabled",
          "rerankEnabled",
          "vectorTopK",
          "bm25TopK",
          "rerankTopK",
          "finalTopK",
          "minimumRelevance",
        ] as const)
          (s.retrieval.recall as any)[k] = v[k];
        saveSettings(s);
        await ctx.summary.setRecallEnabled(v.enabled);
      }, "保存检索策略"),
      button("检索预览", "flask", async () => {
        ctx.guard();
        const result = await ctx.run("召回预览", () =>
          recallCoordinator.preview(),
        );
        dialog("召回结果", recallTraceView(result.trace));
      }),
    ),
  );
  panels.enhancements.append(recallEnhancements(ctx, state));
  panels.continuity.append(continuityRecallSettings(ctx));
  const queryMode = fields([
    { key: "mode", label: "查询模式", type: "select", value: r.queryPreset.mode ?? "combined",
      options: [["combined", "合并查询"], ["multi", "多查询并行召回"]] },
    { key: "maxQueries", label: "最多查询项数（按编排顺序）", type: "number",
      min: 1, max: 8, value: r.queryPreset.maxQueries ?? 4, required: true },
    { key: "maxCharacters", label: "查询总字符预算", type: "number",
      min: 256, max: 12000, value: r.queryPreset.maxCharacters ?? 12000, required: true },
  ]);
  const profiles = [["rrf", "RRF（含重排降级）"],
    ...settings.retrieval.rerankSets.map((set) => [`rerank:${set.id}`, `重排序 · ${set.name}`])];
  const thresholds = fields(profiles.map(([key, label]) => ({
    key: key!, label: `${label} · 最低相关性（空白：沿用通用值）`, type: "number" as const,
    step: 0.0001, value: r.relevanceProfiles?.[key!],
  })));
  panels.strategy.append(section("分模式阈值", saveForm(thresholds, (v) => {
    const s = getSettings();
    const next = { ...s.retrieval.recall.relevanceProfiles };
    for (const [key] of profiles) {
      if (v[key!] === undefined) delete next[key!];
      else next[key!] = v[key!];
    }
    s.retrieval.recall.relevanceProfiles = next;
    saveSettings(s);
  }, "保存阈值")));
  panels.query.append(
    section(
      "查询编排",
      saveForm(queryMode, (v) => {
        const s = getSettings();
        s.retrieval.recall.queryPreset = { ...s.retrieval.recall.queryPreset, ...v, updatedAt: now() };
        saveSettings(s);
      }, "保存查询设置"),
      orderedEditor(
        ctx,
        "查询项",
        r.queryPreset.items,
        promptDescription,
        promptEditor("query"),
        (items) => {
          const s = getSettings();
          s.retrieval.recall.queryPreset = {
            ...s.retrieval.recall.queryPreset,
            items,
            updatedAt: now(),
          };
          saveSettings(s);
        },
      ),
    ),
  );
  const injection = fields(injectionFields(r.injection));
  const budget = fields([
    { key: "maxTokens", label: "记忆注入总预算（估算 Token，0：不限）", type: "number",
      min: 0, max: 1000000, value: r.budget?.maxTokens ?? 0, required: true },
    { key: "overflow", label: "超预算策略", type: "select", value: r.budget?.overflow ?? "preserve_protected",
      options: [["preserve_protected", "保留状态、近期与滞留；普通召回按预算筛选"],
        ["strict", "严格预算：状态保留，滞留优先于近期和普通召回"],
        ["abort", "任何超预算都中止生成"]] },
  ]);
  panels.injection.append(section("注入预算", saveForm(budget, (values) => {
    const s = getSettings();
    s.retrieval.recall.budget = { maxTokens: values.maxTokens, overflow: values.overflow };
    saveSettings(s);
  }, "保存注入预算"), badge("Token 为本地粗估；不缩短正文，滞留池仍可突破普通条数上限", "warning")));
  panels.injection.append(
    section(
      "注入设置",
      saveForm(injection, (v) => {
        const s = getSettings();
        s.retrieval.recall.injection = v as any;
        saveSettings(s);
      }, "保存注入设置"),
    ),
  );
  if (ctx.state.get("recall-focus") === "flags") {
    ctx.state.delete("recall-focus");
    requestAnimationFrame(() => {
      if (ctx.signal.aborted || !page.isConnected) return;
      const target = page.querySelector<HTMLElement>('[data-recall-anchor="flags"]');
      target?.scrollIntoView({ block: "start" });
      target?.focus({ preventScroll: true });
    });
  }
  return page;
}
