import { echoesApi } from "../api/client";
import { SummaryWorldbookStore } from "../worldbook/summary-worldbook";
import { summaryRetrievalContentHash, summaryRetrievalDocumentId } from "../summary/retrieval-document";

export interface WorldbookDiagnostics {
  formatVersions?: number[];
  staleInjectionCount?: number;
  summaryIndexMismatches?: number;
}

export async function inspectWorldbookDiagnostics(): Promise<{ worldbook: WorldbookDiagnostics; errors: string[] }> {
  const worldbook: WorldbookDiagnostics = {};
  const errors: string[] = [];
  const helper = window.TavernHelper;
  const name = helper?.getChatWorldbookName("current");
  if (!name || !helper) return { worldbook, errors: ["当前没有可检查的聊天世界书。"] };
  let entries: TavernWorldbookEntry[];
  try {
    entries = await helper.getWorldbook(name);
    worldbook.formatVersions = entries.flatMap((entry) => {
      const data = entry.extra?.echoes;
      if (!["summary_catalog", "summary_slice"].includes(String(data?.kind))) return [];
      const version = data?.catalog?.formatVersion ?? data?.formatVersion ?? data?.version;
      return Number.isInteger(version) ? [Number(version)] : [];
    });
    worldbook.staleInjectionCount = entries.filter((entry) => {
      const data = entry.extra?.echoes;
      const time = Date.parse(String(data?.updatedAt ?? data?.createdAt ?? ""));
      return entry.enabled && ["retrieval_injection", "status_injection"].includes(data?.kind)
        && (!Number.isFinite(time) || Date.now() - time > 300_000);
    }).length;
  } catch (error) {
    return { worldbook, errors: ["世界书读取失败：" + String(error)] };
  }
  if (!entries.some((entry) => entry.extra?.echoes?.kind === "summary_catalog")) {
    errors.push("当前世界书没有总结目录，未检查总结索引。");
    return { worldbook, errors };
  }
  try {
    const state = await new SummaryWorldbookStore().inspect(name);
    const slices = state.slices.filter((s) => s.batch.state !== "stale");
    let mismatches = state.catalog.pendingRetrievalDeletes.length;
    const collection = state.catalog.retrievalCollectionId;
    if (!collection) mismatches += slices.length;
    else for (let offset = 0; offset < slices.length; offset += 1000) {
      const expected = await Promise.all(slices.slice(offset, offset + 1000).map(async (slice) => ({
        id: await summaryRetrievalDocumentId(collection, slice.id),
        hash: await summaryRetrievalContentHash(slice),
      })));
      const actual = await echoesApi.retrievalDocumentStatus(expected.map((item) => item.id));
      const byId = new Map(actual.documents.map((item) => [item.documentId, item]));
      mismatches += expected.filter((item) => {
        const document = byId.get(item.id);
        return document?.contentHash !== item.hash || document.vectorState !== "ready";
      }).length;
    }
    worldbook.summaryIndexMismatches = mismatches;
  } catch (error) {
    errors.push("总结索引检查失败：" + String(error));
  }
  if (helper.getChatWorldbookName("current") !== name) throw new Error("检查期间世界书已切换，请重新诊断。");
  return { worldbook, errors };
}
