import type { ChatMessageInput, SummarySliceCandidate } from "../../shared/domain";
import { summaryPropositionKey } from "./adaptive-batches";

function terms(text: string): Set<string> {
  const result = new Set<string>();
  for (const word of text.normalize("NFKC").toLowerCase().match(/[\p{L}\p{N}]+/gu) ?? []) {
    if (/\p{Script=Han}/u.test(word)) {
      for (let index = 0; index < word.length - 1; index++) result.add(word.slice(index, index + 2));
    } else if (word.length > 1) result.add(word);
  }
  return result;
}

export function inspectSummaryCoverage(messages: ChatMessageInput[], slices: SummarySliceCandidate[], entityNames: string[] = []) {
  const summaryText = slices.map((slice) => `${slice.title}\n${slice.content}`).join("\n");
  const summaryTerms = terms(summaryText);
  const names = [...new Set(entityNames.filter((name) => name.trim().length > 1))];
  const regions = messages.flatMap((message) => {
    const regions = [];
    for (let start = 0; start < message.content.length; start += 4000) {
      const text = message.content.slice(start, start + 4000);
      const tokens = terms(text);
      const matched = [...tokens].filter((term) => summaryTerms.has(term)).length;
      const ratio = tokens.size ? matched / tokens.size : null;
      regions.push({
        messageId: message.id, start, end: start + text.length, characters: text.length,
        matchedRatio: ratio, warning: ratio !== null && ratio < 0.15,
        names: names.filter((name) => text.includes(name)),
        years: [...new Set(text.match(/(?<!\d)\d{4}(?=年|-\d{2})/g) ?? [])],
        excerpt: text.slice(0, 220),
      });
    }
    return regions;
  });
  const distribution = new Map<string, number>();
  for (const slice of slices) distribution.set(slice.timestamp, (distribution.get(slice.timestamp) ?? 0) + 1);
  return {
    inputMessages: messages.length,
    inputCharacters: messages.reduce((sum, message) => sum + message.content.length, 0),
    outputSlices: slices.length,
    timestamps: [...distribution].map(([timestamp, count]) => ({ timestamp, count })),
    names: names.filter((name) => messages.some((message) => message.content.includes(name)))
      .map((name) => ({ name, inSummary: summaryText.includes(name) })),
    regions,
  };
}

export function compareSummaryCandidates(candidates: SummarySliceCandidate[], existing: SummarySliceCandidate[]) {
  const keys = new Set(existing.map(summaryPropositionKey));
  const existingTerms = existing.map((slice) => terms(slice.content));
  return candidates.map((candidate, index) => {
    const candidateTerms = terms(candidate.content);
    const similar = existing.flatMap((slice, existingIndex) => {
      const old = existingTerms[existingIndex]!;
      const shared = [...candidateTerms].filter((term) => old.has(term)).length;
      const ratio = shared / Math.max(1, Math.min(old.size, candidateTerms.size));
      return ratio >= 0.65 ? [{ existingIndex, title: slice.title, ratio }] : [];
    }).sort((a, b) => b.ratio - a.ratio).slice(0, 3);
    return { index, duplicate: keys.has(summaryPropositionKey(candidate)), similar };
  });
}
