import type { ExtractionRequest, MemoryRow } from "./domain";
import { declaredAliases, selectExtractionRows } from "./extraction-context";
import { CONTINUITY_EXTRACTION_GUIDE } from "./continuity";

export const EXTRACTION_ROW_REFERENCE_GUIDE = `Record references for this request:
currentRows supplies short rowId references such as R1 and R2. For update or delete, copy the rowId and typeId together from the same currentRows record. These references apply only to this request; the application resolves them to stored IDs.
For a new record, use add without a rowId and include its complete intended content. Combine changes to a newly proposed record into that add, rather than inventing an ID for a later update. Combine changes to an existing record into one operation.
Return the operations JSON object only, with Chinese natural-language values.`;

export const EXTRACTION_CLEANING_GUIDE = `This is a user-requested memory cleaning pass over a selected historical message range, not the next incremental batch.
Look for useful information previously missed. Compare concrete facts with currentRows and propose additions or updates that fill omissions. A previously processed message may still contain unrecorded information.
Retain valid existing knowledge. Preserve the chronology of historical facts; an earlier condition is not evidence that a later known condition should be reverted. Propose deletions only when explicitly supported. The application will present the proposals for review and preserve the normal extraction checkpoint.`;

export function extractionProviderMessages(request: ExtractionRequest) {
  return [
    ...request.promptMessages,
    ...(request.extractAttributes ? [{ role: "system" as const, content: CONTINUITY_EXTRACTION_GUIDE }] : []),
    { role: "system" as const, content: "Use optional aliases only for explicitly established alternate names of the same entity. Never equate similarly named entities automatically. In add or update.changes, aliases replaces the alias list; preserve valid earlier aliases." },
    { role: "system" as const, content: EXTRACTION_ROW_REFERENCE_GUIDE },
    ...(request.contextPolicy?.enabled ? [{ role: "system" as const, content: `The entityDirectory lists existing names in this chat's active tables for identity and duplicate checks. currentRows contains selected full records only. A missing detail record is not deleted or unknown. Update/delete only records supplied in currentRows. Reuse existing identities, including declared aliases, rather than creating duplicates. Preserve uncertainty and unchanged fields. The application validates references and revisions against the full stored snapshot.` }] : []),
    ...(request.batch.mode === "cleaning" ? [{ role: "system" as const, content: EXTRACTION_CLEANING_GUIDE }] : []),
    { role: "user" as const, content: JSON.stringify(extractionRuntimeInput(request)) },
    ...(request.additionalInstructions?.trim()
      ? [{ role: "system" as const, content: request.additionalInstructions.trim() }] : []),
  ];
}

export function extractionRowReferences(rows: MemoryRow[]): Map<string, string> {
  const storedIds = new Set(rows.map((row) => row.id));
  const references = new Map<string, string>();
  let index = 1;
  for (const row of rows) {
    while (storedIds.has(`R${index}`)) index += 1;
    references.set(`R${index++}`, row.id);
  }
  return references;
}

export function extractionRuntimeInput(request: Pick<ExtractionRequest, "types" | "rows" | "messages" | "contextPolicy">) {
  const referenceById = new Map([...extractionRowReferences(request.rows)].map(([ref, id]) => [id, ref]));
  const selected = selectExtractionRows(request.rows, request.types, request.messages.map((message) => message.content).join("\n"), request.contextPolicy);
  return {
    ...(request.contextPolicy?.enabled ? {
      entityDirectory: request.rows.map((row) => ({
        rowId: referenceById.get(row.id)!, typeId: row.typeId, dataName: row.dataName,
        aliases: declaredAliases(row, request.types), revision: row.revision,
      })),
      contextSelection: { fullRecords: selected.rows.length, omittedRecords: selected.omitted.length,
        detailCharacters: selected.detailCharacters },
    } : {}),
    activeTypes: request.types.map((type) => ({
      id: type.id,
      name: type.name,
      columns: type.columns.map((column) => ({
        id: column.id, name: column.name, type: column.type, required: column.required,
        description: column.description ?? "", enumValues: column.enumValues ?? [],
      })),
    })),
    currentRows: selected.rows.map((row) => ({
      rowId: referenceById.get(row.id)!, typeId: row.typeId, dataName: row.dataName,
      keywords: row.keywords, status: row.status, values: row.values,
      ...(row.aliases ? { aliases: row.aliases } : {}),
      ...(row.continuity ? { continuity: row.continuity } : {}),
    })),
    incrementalMessages: request.messages,
    responseShape: {
      operations: [
        { action: "add", typeId: "existing_type_id", dataName: "row display name",
          keywords: ["optional keyword"], status: "permanent | keyword | vectorized",
          values: { column_id: "typed value" } },
        { action: "update", typeId: "existing_type_id", rowId: "copy_from_currentRows",
          changes: { dataName: "optional replacement", keywords: ["optional replacement"],
            status: "optional replacement", values: { column_id: "only changed values" } } },
        { action: "delete", typeId: "existing_type_id", rowId: "copy_from_currentRows" },
      ],
    },
  };
}

export function unavailableExtractionRowReason(
  rowId: string,
  typeId: string,
  initialRows: MemoryRow[],
  currentRows: MemoryRow[],
): string {
  const initial = initialRows.find((row) => row.id === rowId);
  const prefix = `Operation references an unavailable row: ${rowId}. `;
  if (!initial) return prefix + "该引用不在本次请求的 currentRows 中；新增记录应使用 add，不能自行生成 rowId。";
  if (initial.typeId !== typeId) {
    return prefix + `记录“${initial.dataName}”属于 ${initial.typeId}，操作却指定了 ${typeId}；rowId 与 typeId 必须来自同一条记录。`;
  }
  if (!currentRows.some((row) => row.id === rowId)) {
    return prefix + `记录“${initial.dataName}”已被本批更早的操作删除；请合并对同一条记录的修改。`;
  }
  return prefix + "当前记录已不可用，请刷新记录后重试。";
}
