import type {
  ChatMessageInput,
  SummaryBatchMetadata,
  SummarySlice,
} from "../../shared/domain";

import { createBatchOrder } from "./batch-order";

export interface SummaryBatchCoverage {
  batch: SummaryBatchMetadata;
  slices: SummarySlice[];
  startIndex: number;
  endIndex: number;
}

export interface CompressionPlan {
  chain: SummaryBatchCoverage[];
  hideThroughIndex: number;
  coveredMessageIds: Set<string>;
  batchByMessageId: Map<string, string>;
}

function uniqueBatches(slices: SummarySlice[]): Array<{
  batch: SummaryBatchMetadata;
  slices: SummarySlice[];
}> {
  const grouped = new Map<string, SummarySlice[]>();
  for (const slice of slices) {
    const current = grouped.get(slice.batch.id) ?? [];
    current.push(slice);
    grouped.set(slice.batch.id, current);
  }
  return [...grouped.values()].map((items) => ({
    batch: items[0]!.batch,
    slices: [...items].sort((left, right) => left.sliceNumber - right.sliceNumber),
  }));
}

function exactMessageRange(
  messages: ChatMessageInput[],
  batch: SummaryBatchMetadata,
): { startIndex: number; endIndex: number } | null {
  const startIndex = messages.findIndex((message) => message.id === batch.startMessageId);
  if (startIndex < 0) return null;
  const selected = messages.slice(startIndex, startIndex + batch.messageIds.length);
  if (selected.length !== batch.messageIds.length
    || selected.some((message, index) => message.id !== batch.messageIds[index])) {
    return null;
  }
  const endIndex = startIndex + selected.length - 1;
  return messages[endIndex]?.id === batch.endMessageId
    ? { startIndex, endIndex }
    : null;
}

export function continuousSummaryCoverage(
  messages: ChatMessageInput[],
  slices: SummarySlice[],
  lastCommittedMessageId?: string,
): SummaryBatchCoverage[] {
  if (messages.length === 0 || !lastCommittedMessageId) return [];
  const committedIndex = messages.findIndex((message) => message.id === lastCommittedMessageId);
  if (committedIndex < 0) return [];
  const candidates = uniqueBatches(slices)
    .filter(({ batch }) => batch.state !== "stale" && batch.source?.kind !== "imported" && batch.purpose !== "supplement")
    .flatMap(({ batch, slices: batchSlices }): SummaryBatchCoverage[] => {
      const range = exactMessageRange(messages, batch);
      return range && range.endIndex <= committedIndex
        ? [{ batch, slices: batchSlices, ...range }]
        : [];
    });
  const chain: SummaryBatchCoverage[] = [];
  let expectedStart = 0;
  while (expectedStart <= committedIndex) {
    const next = candidates
      .filter((candidate) =>
        candidate.startIndex <= expectedStart && candidate.endIndex >= expectedStart)
      .sort((left, right) =>
        left.startIndex - right.startIndex
        || right.endIndex - left.endIndex
        || left.batch.id.localeCompare(right.batch.id))[0];
    if (!next) break;
    chain.push(next);
    expectedStart = next.endIndex + 1;
    if (next.endIndex === committedIndex) break;
  }
  return chain;
}

export function compressionPlan(
  messages: ChatMessageInput[],
  slices: SummarySlice[],
  lastCommittedMessageId: string | undefined,
  keepRecentMessages: number,
): CompressionPlan {
  const chain = continuousSummaryCoverage(messages, slices, lastCommittedMessageId);
  const latestEnd = chain.at(-1)?.endIndex ?? -1;
  const hideThroughIndex = latestEnd - Math.max(0, keepRecentMessages);
  const coveredMessageIds = new Set<string>();
  const batchByMessageId = new Map<string, string>();
  for (const coverage of chain) {
    for (const messageId of coverage.batch.messageIds) {
      coveredMessageIds.add(messageId);
      // Keep overlap ownership with the first covering batch, including when a later index is missing.
      if (!batchByMessageId.has(messageId)) batchByMessageId.set(messageId, coverage.batch.id);
    }
  }
  return { chain, hideThroughIndex, coveredMessageIds, batchByMessageId };
}

export function recentSummaryBatches(
  slices: SummarySlice[],
  count: number,
  messages: ChatMessageInput[] = [],
): SummaryBatchCoverage[] {
  if (count <= 0) return [];
  const { compare } = createBatchOrder(messages);
  return uniqueBatches(slices)
    .filter(({ batch }) => batch.state !== "stale" && batch.source?.kind !== "imported" && batch.purpose !== "supplement")
    .sort((left, right) => compare(left.batch, right.batch))
    .slice(-count)
    .map(({ batch, slices: batchSlices }) => ({
      batch,
      slices: batchSlices,
      startIndex: -1,
      endIndex: -1,
    }));
}
