import { stringify as stringifyYaml } from "yaml";

import type {
  ChatMessageInput,
  PromptMessageInput,
  StatusCatalog,
  StatusPromptItem,
  StatusSnapshot,
  StatusState,
} from "../../shared/domain";
import { sourceMessagesHash } from "../../shared/source-hash";
import { canonicalStatusJson } from "../../shared/status-core";
import { preprocessSummaryMessages } from "../summary/preprocess";
import { statusMessageId } from "./status-snapshots";

export interface StatusChatMessage extends ChatMessageInput {
  messageIndex: number;
}

export interface PreparedStatusRequest {
  originalMessages: ChatMessageInput[];
  cleanedMessages: ChatMessageInput[];
  promptMessages: PromptMessageInput[];
  sourceHash: string;
  rangeNotice?: string;
}

export function currentStatusMessages(): StatusChatMessage[] {
  return SillyTavern.getContext().chat.flatMap((message, messageIndex) => {
    const content = String(message.mes ?? message.message ?? "").trim();
    if (!content) return [];
    return [{
      id: statusMessageId(message, messageIndex),
      messageIndex,
      role: message.is_user === true || message.role === "user" ? "user" as const : "assistant" as const,
      content,
    }];
  });
}

export async function statusSourceHash(messages: ChatMessageInput[]): Promise<string> {
  return sourceMessagesHash(messages);
}

export function renderStatusYaml(state: StatusState): string {
  return stringifyYaml(state, { lineWidth: 0 }).trim() || "{}";
}

function macro(value: string, charName: string, userName: string): string {
  return value.replaceAll("{{char}}", charName).replaceAll("{{user}}", userName);
}

function characterCardContent(character: Record<string, any>, charName: string): string {
  const sections = [
    ["Name", charName],
    ["Description", character.description],
    ["Personality", character.personality],
    ["Scenario", character.scenario],
  ].flatMap(([title, raw]) => {
    const value = String(raw ?? "").trim();
    return value ? [`${title}:\n${value}`] : [];
  });
  return sections.join("\n\n");
}

function currentChatText(): string[] {
  return SillyTavern.getContext().chat.flatMap((message) => {
    if (message.is_hidden === true) return [];
    const content = String(message.mes ?? message.message ?? "").trim();
    return content ? [content] : [];
  });
}

async function activatedWorldbookContent(): Promise<string> {
  const context = SillyTavern.getContext();
  if (typeof context.getWorldInfoPrompt !== "function") {
    throw new Error("SillyTavern does not expose the worldbook activation API required by this status prompt.");
  }
  const result = await context.getWorldInfoPrompt(
    currentChatText(),
    Math.max(1, Math.floor(context.maxContext ?? 200_000)),
    true,
  );
  let content = String(result.worldInfoString ?? "").trim();
  const helper = window.TavernHelper;
  const worldbookName = helper?.getChatWorldbookName("current");
  if (content && helper && worldbookName) {
    const entries = await helper.getWorldbook(worldbookName);
    for (const entry of entries) {
      const kind = String(entry.extra?.echoes?.kind ?? "");
      if ((kind === "status_injection" || kind === "retrieval_injection") && entry.content) {
        content = content.replaceAll(entry.content, "");
      }
    }
  }
  return content.trim();
}

async function itemContent(
  item: StatusPromptItem,
  state: StatusState,
  messages: ChatMessageInput[],
): Promise<string> {
  const context = SillyTavern.getContext();
  const character = context.characters?.[context.characterId ?? -1] ?? {};
  const charName = String(character.name ?? "Character");
  const userName = String(context.powerUserSettings?.persona_name ?? context.name1 ?? "User");
  if (item.kind === "custom") return macro(item.content, charName, userName);
  if (item.kind === "character") {
    return characterCardContent(character, charName);
  }
  if (item.kind === "worldbook") return activatedWorldbookContent();
  if (item.kind === "persona") {
    const description = String(context.powerUserSettings?.persona_description ?? "").trim();
    return description ? `${userName}:\n${description}` : "";
  }
  if (item.kind === "current_state") return `Current complete state:\n${renderStatusYaml(state)}`;
  return messages.map((message) => {
    const name = message.role === "user" ? "Game Master / World" : charName;
    return `[${message.id}] ${name}: ${message.content}`;
  }).join("\n\n");
}

export function selectStatusSourceMessages(options: {
  baseSnapshot: StatusSnapshot | null;
  targetMessageIndex: number;
}): Pick<PreparedStatusRequest, "originalMessages" | "rangeNotice"> & { skippedCount: number } {
  const all = currentStatusMessages();
  let baseIndex = options.baseSnapshot
    ? all.find((message) => message.id === options.baseSnapshot!.targetMessageId)?.messageIndex ?? -1
    : -1;
  if (options.baseSnapshot && (baseIndex < 0 || baseIndex >= options.targetMessageIndex)) {
    throw new Error("状态快照的来源楼层已失效，请先检查或恢复状态快照。");
  }
  if (!options.baseSnapshot) {
    // Bootstrap current state from the latest turn, without replaying the entire chat.
    for (let index = all.length - 1; index >= 0; index -= 1) {
      const message = all[index]!;
      if (message.messageIndex < options.targetMessageIndex && message.role === "assistant") {
        baseIndex = message.messageIndex;
        break;
      }
    }
  }
  const incremental = all
    .filter((message) => message.messageIndex > baseIndex && message.messageIndex <= options.targetMessageIndex);
  const selected = incremental.slice(-500)
    .map(({ id, role, content }) => ({ id, role, content }));
  if (selected.length === 0) {
    throw new Error("目标楼层没有可用于更新状态的消息。");
  }
  const skippedCount = incremental.length - selected.length;
  const rangeNotice = skippedCount > 0
    ? `状态增量积压超过 500 条，本次仅处理最近 500 条；此前 ${skippedCount} 条未回溯，请核对当前状态。`
    : undefined;
  return { originalMessages: selected, skippedCount, ...(rangeNotice ? { rangeNotice } : {}) };
}

export async function prepareStatusRequest(options: {
  catalog: StatusCatalog;
  baseSnapshot: StatusSnapshot | null;
  targetMessageIndex: number;
}): Promise<PreparedStatusRequest> {
  const { originalMessages: selected, rangeNotice, skippedCount } = selectStatusSourceMessages(options);
  const cleaned = await preprocessSummaryMessages(selected, options.catalog.profile.preprocessRules);
  if (cleaned.length === 0) throw new Error("No status evidence remains after message preprocessing.");
  if (!options.catalog.profile.promptPreset.items.some((item) => item.enabled && item.kind === "messages")) {
    throw new Error("The status prompt preset requires an enabled incremental messages item.");
  }
  const baseState = options.baseSnapshot?.state ?? options.catalog.profile.initialState;
  const promptMessages: PromptMessageInput[] = [];
  if (rangeNotice) {
    promptMessages.push({
      role: "system",
      content: `The supplied incremental messages contain only the latest 500 messages. ${skippedCount} earlier messages after the base state are omitted. Update the current state using the supplied evidence; intermediate changes in the omitted interval are unknown.`,
    });
  }
  for (const item of options.catalog.profile.promptPreset.items) {
    if (!item.enabled) continue;
    const content = (await itemContent(item, baseState, cleaned)).trim();
    if (content) promptMessages.push({ role: item.role, content });
  }
  if (promptMessages.length === 0) throw new Error("The status prompt is empty.");
  return {
    originalMessages: selected,
    cleanedMessages: cleaned,
    promptMessages,
    sourceHash: await statusSourceHash(selected),
    ...(rangeNotice ? { rangeNotice } : {}),
  };
}

export function statusStateDebugValue(state: StatusState): string {
  return canonicalStatusJson(state);
}
