import type { JobRecord } from "../../shared/domain";
import { ECHOES_BUILD_INFO } from "../../shared/build-info";
import { echoesApi } from "../api/client";
import { SummaryCoordinator } from "../summary/summary-coordinator";
import { extractionCoordinator } from "../memory/extraction-coordinator";
import { memoryView } from "./memory";
import { summaryView } from "./summary";
import { statusView } from "./status";
import { connectionsView } from "./connections";
import { maintenanceView } from "./maintenance";
import {
  el,
  icon,
  button,
  tool,
  actions,
  badge,
  dialog,
  empty,
  detail,
  notifyError,
  waitJob,
  type ViewContext,
  type View,
} from "./core";

export const navigation = [
  {
    title: "API 连接",
    icon: "plug",
    pages: [
      ["api/workflows", "工作流分配"],
      ["api/generation", "生成端点"],
      ["api/embedding", "向量端点"],
      ["api/rerank", "重排序端点"],
      ["api/credentials", "凭据管理"],
    ],
  },
  {
    title: "结构化记忆",
    icon: "table-cells",
    pages: [
      ["memory/records", "记忆档案"],
      ["memory/tasks", "提取任务"],
      ["memory/cleaning", "记忆清洗"],
      ["memory/review", "操作审核"],
      ["memory/links", "记忆关联"],
      ["memory/history", "历史变化"],
    ],
  },
  {
    title: "结构化设置",
    icon: "table-columns",
    pages: [
      ["memory/schema", "表结构"],
      ["memory/prompts", "提示词编排"],
      ["memory/rules", "提取规则"],
      ["memory/templates", "类型模板"],
    ],
  },
  {
    title: "总结记忆",
    icon: "book-open",
    pages: [
      ["summary/records", "总结记录"],
      ["summary/tasks", "生成任务"],
      ["summary/coverage", "覆盖与补全"],
      ["summary/hiding", "上下文隐藏"],
    ],
  },
  {
    title: "总结设置",
    icon: "sliders",
    pages: [
      ["summary/rules", "生成规则"],
      ["summary/prompts", "提示词编排"],
      ["summary/cleaning", "消息清洗"],
      ["summary/recall", "召回与注入"],
    ],
  },
  {
    title: "状态记忆",
    icon: "heart-pulse",
    pages: [
      ["status/current", "当前状态"],
      ["status/variables", "自定义变量"],
      ["status/history", "历史快照"],
      ["status/rules", "校验"],
      ["status/prompts", "提示词与清洗"],
      ["status/injection", "状态注入"],
      ["status/templates", "初始值与模板"],
    ],
  },
  {
    title: "维护与恢复",
    icon: "screwdriver-wrench",
    pages: [
      ["maintenance/jobs", "任务日志"],
      ["maintenance/pipeline", "记忆链路"],
      ["maintenance/console", "控制台日志"],
      ["maintenance/collections", "检索集合"],
      ["maintenance/query", "检索实验"],
      ["maintenance/diagnostics", "诊断与修复"],
      ["maintenance/backup", "备份与恢复"],
      ["maintenance/system", "系统信息"],
    ],
  },
] as const;

interface Task {
  id: number;
  label: string;
  chatId: string;
  status: string;
  message: string;
  progress: number;
  stop?: (() => Promise<unknown>) | undefined;
}
export class MemoryPanel {
  private root = el("div");
  private main = el("main", "ew-main");
  private nav = el("nav", "ew-nav");
  private body = el("div", "ew-body", this.nav, this.main);
  private contextLabel = el("div", "ew-context");
  private footer = el("span");
  private taskButton = button("任务", "list-check", () => this.openTasks());
  private route = "memory/records";
  private scope = new AbortController();
  private state = new Map<string, Map<string, unknown>>();
  private scroll = new Map<string, number>();
  private activeChat = "";
  private previousFocus: HTMLElement | null = null;
  private summary = new SummaryCoordinator();
  private tasks: Task[] = [];
  private sequence = 0;
  private tasksHost: HTMLElement | null = null;
  private hostInert = new Map<HTMLElement, boolean>();
  private expanded = new Set<string>();
  private beforeUnload = (e: BeforeUnloadEvent) => {
    if (!this.root.hidden && this.dirty()) {
      e.preventDefault();
      e.returnValue = "";
    }
  };

  constructor() {
    this.root.id = "echoes-workbench";
    this.root.hidden = true;
    this.root.setAttribute("role", "dialog");
    this.root.setAttribute("aria-modal", "true");
    this.root.setAttribute("aria-label", "Echoes 记忆工作台");
    try {
      this.root.dataset.theme =
        localStorage.getItem("echoes.workbench.theme") ?? "dark";
    } catch {
      this.root.dataset.theme = "dark";
    }
    const mobile = tool("切换导航", "bars", () =>
      this.body.classList.toggle("nav-open"),
    );
    mobile.classList.add("ew-mobile-nav");
    const theme = tool("切换明暗主题", "circle-half-stroke", () => {
      this.root.dataset.theme =
        this.root.dataset.theme === "dark" ? "light" : "dark";
      this.root
        .querySelectorAll<HTMLElement>(".ew-dialog")
        .forEach((d) => (d.dataset.theme = this.root.dataset.theme!));
      try {
        localStorage.setItem(
          "echoes.workbench.theme",
          this.root.dataset.theme!,
        );
      } catch {}
    });
    const header = el(
      "header",
      "ew-header",
      mobile,
      el("strong", "ew-brand", icon("layer-group"), "Echoes"),
      this.contextLabel,
      actions(
        this.taskButton,
        theme,
        tool("关闭 Echoes", "xmark", () => this.close()),
      ),
    );
    this.root.append(
      el(
        "div",
        "ew-window",
        header,
        this.body,
        el(
          "footer",
          "ew-footer",
          el("span", "", "Echoes " + ECHOES_BUILD_INFO.appVersion),
          this.footer,
        ),
      ),
    );
    this.nav.setAttribute("aria-label", "记忆功能导航");
    this.main.tabIndex = -1;
    this.root.addEventListener("keydown", (e) => {
      if (this.root.querySelector("dialog[open]")) return;
      if (e.key === "Escape") {
        e.preventDefault();
        this.close();
      }
      if (e.key === "Tab") {
        const nodes = [
          ...this.root.querySelectorAll<HTMLElement>(
            'button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[tabindex="0"]',
          ),
        ].filter((n) => n.getClientRects().length);
        const first = nodes[0],
          last = nodes.at(-1);
        if (e.shiftKey && document.activeElement === first) {
          e.preventDefault();
          last?.focus();
        }
        if (!e.shiftKey && document.activeElement === last) {
          e.preventDefault();
          first?.focus();
        }
      }
    });
    window.addEventListener("beforeunload", this.beforeUnload);
    extractionCoordinator.subscribe(() => {
      this.updateTasks();
    });
  }

  async open() {
    if (!this.root.isConnected) document.body.append(this.root);
    if (this.root.hidden) {
      this.previousFocus =
        document.activeElement instanceof HTMLElement
          ? document.activeElement
          : null;
      for (const sibling of document.body.children)
        if (sibling instanceof HTMLElement && sibling !== this.root) {
          this.hostInert.set(sibling, sibling.inert);
          sibling.inert = true;
        }
      this.root.hidden = false;
    }
    await this.render();
    this.main.focus();
  }
  close() {
    if (this.dirty() && !confirm("存在未保存的修改，放弃修改并关闭？")) return;
    this.scope.abort();
    this.root
      .querySelectorAll<HTMLDialogElement>("dialog")
      .forEach((d) => d.close());
    this.root.hidden = true;
    for (const [node, inert] of this.hostInert) node.inert = inert;
    this.hostInert.clear();
    this.previousFocus?.focus();
  }
  async reload() {
    const changed = (SillyTavern.getContext().chatId ?? "") !== this.activeChat;
    if (changed) {
      this.scope.abort();
      this.root
        .querySelectorAll<HTMLDialogElement>("dialog")
        .forEach((d) => d.close());
    }
    if (!this.root.hidden && (changed || !this.dirty())) await this.render();
    else if (!this.root.hidden)
      this.footer.textContent = "数据已更新；未保存的编辑保持不变";
  }
  async reloadTables() {
    await this.reload();
  }
  async checkSummaryAutomation() {
    if (!SillyTavern.getContext().chatId || this.summary.isRunning()) return;
    try {
      await this.summary.runAutomatic();
    } catch (error) {
      if (!(error instanceof Error) || error.name !== "AbortError") notifyError(error);
    }
    await this.reload();
  }
  async checkExtractionAutomation() {
    if (!SillyTavern.getContext().chatId || extractionCoordinator.isRunning())
      return;
    await extractionCoordinator.runAutomatic();
    await this.reload();
  }
  private dirty() {
    return !!this.root.querySelector('[data-dirty="true"]');
  }
  private navigate(route: string) {
    if (route === this.route) return;
    if (this.dirty() && !confirm("存在未保存的修改，放弃修改并切换页面？"))
      return;
    this.scroll.set(this.activeChat + ":" + this.route, this.main.scrollTop);
    this.route = route;
    this.body.classList.remove("nav-open");
    void this.render();
  }
  private drawNavigation() {
    this.nav.replaceChildren();
    for (const group of navigation) {
      const active = group.pages.some(([route]) => route === this.route);
      if (active) this.expanded.add(group.title);
      const groupNode = el("div", "ew-nav-group");
      const title = button(group.title, group.icon, () => {
        this.expanded.has(group.title)
          ? this.expanded.delete(group.title)
          : this.expanded.add(group.title);
        children.hidden = !this.expanded.has(group.title);
        title.setAttribute("aria-expanded", String(!children.hidden));
      });
      title.className = "ew-nav-title" + (active ? " selected" : "");
      const children = el("div");
      children.hidden = !this.expanded.has(group.title);
      title.setAttribute("aria-expanded", String(!children.hidden));
      for (const [route, label] of group.pages) {
        const link = button(label, "", () => this.navigate(route));
        link.querySelector("i")?.remove();
        link.className = "ew-nav-link";
        if (route === this.route) link.setAttribute("aria-current", "page");
        children.append(link);
      }
      groupNode.append(title, children);
      this.nav.append(groupNode);
    }
  }
  private async render() {
    this.scope.abort();
    this.scope = new AbortController();
    const signal = this.scope.signal;
    const chatId = SillyTavern.getContext().chatId ?? "";
    this.activeChat = chatId;
    let worldbook =
      window.TavernHelper?.getChatWorldbookName("current") ?? null;
    this.contextLabel.textContent =
      (chatId || "未选择聊天") + (worldbook ? " · " + worldbook : "");
    this.contextLabel.title = this.contextLabel.textContent;
    const guard = () => {
      if (
        (SillyTavern.getContext().chatId ?? "") !== chatId ||
        (window.TavernHelper?.getChatWorldbookName("current") ?? null) !==
          worldbook
      )
        throw new Error("当前聊天或世界书已变化，请重新打开页面后操作。");
    };
    this.drawNavigation();
    const group = navigation.find((g) =>
      g.pages.some(([route]) => route === this.route),
    )!;
    const name = group.pages.find(([route]) => route === this.route)![1];
    const content = el(
      "div",
      "ew-page-content",
      el("p", "ew-muted", "正在读取…"),
    );
    this.main.replaceChildren(
      el(
        "div",
        "ew-page-head",
        el("div", "", el("p", "ew-eyebrow", group.title), el("h1", "", name)),
        tool("刷新页面", "rotate", () => {
          if (!this.dirty() || confirm("放弃未保存的修改并刷新？"))
            return this.render();
        }),
      ),
      content,
    );
    this.main.setAttribute("aria-busy", "true");
    if (!this.state.has(chatId)) this.state.set(chatId, new Map());
    const route = this.route;
    const ctx: ViewContext = {
      route,
      chatId,
      summary: this.summary,
      signal,
      state: this.state.get(chatId)!,
      guard,
      refresh: async () => {
        if (!signal.aborted) {
          guard();
          await this.render();
        }
      },
      navigate: (r) => this.navigate(r),
      run: async (label, work, stop) => {
        guard();
        return this.run(label, chatId, work, stop);
      },
      job: async (label, start) => {
        guard();
        let current: JobRecord | undefined;
        return this.run(
          label,
          chatId,
          async (task) => {
            current = await start();
            const controller = new AbortController();
            return waitJob(
              current,
              (job) => {
                current = job;
                task.progress = job.progress;
                task.message = job.message;
                this.updateTasks();
              },
              controller.signal,
            ) as Promise<any>;
          },
          async () => {
            if (!current) throw new Error("任务正在提交，稍后再停止。");
            const result = await echoesApi.cancelJob(current.id);
            if (!result.cancelled)
              throw new Error("后台未确认取消；请查看任务日志。");
          },
        );
      },
    };
    try {
      let view: View;
      if (route.startsWith("api/")) view = connectionsView;
      else if (route.startsWith("memory/")) view = memoryView;
      else if (route.startsWith("summary/")) view = summaryView;
      else if (route.startsWith("status/")) view = statusView;
      else view = maintenanceView;
      if (
        !chatId &&
        !route.startsWith("api/") &&
        !route.startsWith("maintenance/")
      ) {
        content.replaceChildren(empty("请先选择一个聊天"));
        return;
      }
      const result = await view(ctx);
      if (signal.aborted || (SillyTavern.getContext().chatId ?? "") !== chatId)
        return;
      if (
        worldbook !== null &&
        (window.TavernHelper?.getChatWorldbookName("current") ?? null) !==
          worldbook
      )
        throw new Error("读取期间世界书已改变，请刷新后操作。");
      worldbook = window.TavernHelper?.getChatWorldbookName("current") ?? null;
      content.replaceChildren(result);
      this.contextLabel.textContent =
        (chatId || "未选择聊天") + (worldbook ? " · " + worldbook : "");
      this.main.scrollTop = this.scroll.get(chatId + ":" + route) ?? 0;
      this.footer.textContent = "本地设置与当前聊天";
    } catch (error) {
      if (!signal.aborted)
        content.replaceChildren(
          empty(
            error instanceof Error ? error.message : String(error),
            button("重试", "rotate", () => this.render()),
          ),
        );
    } finally {
      if (!signal.aborted) this.main.removeAttribute("aria-busy");
      this.updateTasks();
    }
  }
  private async run<T>(
    label: string,
    chatId: string,
    work: (task: Task) => Promise<T>,
    stop?: () => Promise<unknown>,
  ): Promise<T> {
    const task: Task = {
      id: ++this.sequence,
      label,
      chatId,
      status: "运行中",
      message: "",
      progress: 0,
      stop,
    };
    this.tasks.push(task);
    this.updateTasks();
    try {
      const result = await work(task);
      task.status = "已完成";
      task.progress = 1;
      return result;
    } catch (error) {
      task.status =
        error instanceof Error && error.name === "AbortError"
          ? "已取消"
          : "失败";
      task.message = error instanceof Error ? error.message : String(error);
      throw error;
    } finally {
      task.stop = undefined;
      this.tasks = this.tasks.slice(-50);
      this.updateTasks();
    }
  }
  private updateTasks() {
    const running = this.tasks.filter((t) => t.status === "运行中").length;
    this.taskButton.querySelector("span")!.textContent =
      "任务" + (running ? " · " + running : "");
    if (!this.tasksHost?.isConnected) return;
    this.tasksHost.replaceChildren(
      actions(
        button("任务日志", "list", () => {
          this.tasksHost?.closest("dialog")?.close();
          this.navigate("maintenance/jobs");
        }),
        this.summary.isRunning()
          ? button("停止总结", "stop", () => this.summary.stop(), "danger")
          : null,
        extractionCoordinator.isRunning()
          ? button(
              "停止提取",
              "stop",
              () => extractionCoordinator.stopCurrent(),
              "danger",
            )
          : null,
      ),
      ...this.tasks
        .slice()
        .reverse()
        .map((t) =>
          el(
            "div",
            "ew-task",
            el(
              "div",
              "ew-task-main",
              el("strong", "", t.label),
              el("p", "ew-muted", t.chatId),
              t.message ? detail("详细信息", t.message) : null,
              t.status === "运行中"
                ? Object.assign(el("progress"), { max: 1, value: t.progress })
                : null,
            ),
            badge(t.status, t.status === "失败" ? "danger" : ""),
            t.stop
              ? tool(
                  "停止任务",
                  "stop",
                  async () => {
                    if (t.chatId !== (SillyTavern.getContext().chatId ?? ""))
                      throw new Error(
                        "请先切回此任务所属聊天，或从服务端任务日志中取消任务。",
                      );
                    t.message = "正在停止，等待后台确认";
                    this.updateTasks();
                    try {
                      await t.stop?.();
                    } catch (error) {
                      t.message = error instanceof Error ? error.message : String(error);
                      throw error;
                    } finally {
                      this.updateTasks();
                    }
                  },
                  "danger",
                )
              : null,
          ),
        ),
    );
    if (!this.tasks.length)
      this.tasksHost.append(empty("本次会话暂无手动任务"));
  }
  private openTasks() {
    if (this.tasksHost?.isConnected) {
      this.tasksHost.closest("dialog")?.focus();
      return;
    }
    this.tasksHost = el("div", "ew-page-content");
    dialog("任务中心", this.tasksHost);
    this.updateTasks();
  }
}
