import type {
  MemoryColumnDefinition,
  MemoryTypeTemplate,
  PromptPresetItem,
  SummaryPromptItem,
  StatusPromptItem,
  SummaryPreprocessRule,
  RetrievalQueryPresetItem,
} from "../../shared/domain";
import { MEMORY_COLUMN_TYPES } from "../../shared/domain";
import { MemorySchemaBackfillRequiredError } from "../../shared/memory-schema-migration";
import { validateMemoryValues } from "../../shared/schemas";
import {
  el,
  actions,
  button,
  tool,
  table,
  fields,
  editDialog,
  dialog,
  move,
  id,
  now,
  badge,
  check,
  type ViewContext,
  type Field,
} from "./core";

export function orderedEditor<T extends { id: string; enabled: boolean }>(
  ctx: ViewContext,
  title: string,
  original: T[],
  describe: (item: NoInfer<T>) => [string, string],
  edit: (item: NoInfer<T> | undefined, done: (item: T) => void) => void,
  save: (items: T[]) => Promise<unknown> | unknown,
  toggles = true,
): HTMLElement {
  let items = structuredClone(original);
  let dirty = false;
  const root = el("div", "ew-page-content");
  const host = el("div");
  const status = el("span", "ew-muted");
  const changed = () => {
    dirty = true;
    root.dataset.dirty = "true";
    status.textContent = "有未保存的修改";
    render();
  };
  const render = () => {
    host.replaceChildren(
      table(
        ["顺序", title, "类型", "启用", "操作"],
        items.map((item, i) => [
          String(i + 1),
          describe(item)[0],
          badge(describe(item)[1]),
          toggles
            ? check("启用 " + describe(item)[0], item.enabled, (v) => {
                item.enabled = v;
                changed();
              })
            : "始终",
          actions(
            tool("编辑", "pen", () =>
              edit(item, (v) => {
                items[i] = v;
                changed();
              }),
            ),
            tool("上移", "arrow-up", () => {
              items = move(items, i, -1);
              changed();
            }),
            tool("下移", "arrow-down", () => {
              items = move(items, i, 1);
              changed();
            }),
            tool(
              "删除",
              "trash",
              () => {
                if (confirm("删除这一配置项？")) {
                  items.splice(i, 1);
                  changed();
                }
              },
              "danger",
            ),
          ),
        ]),
      ),
    );
    const rows = host.querySelectorAll("tbody tr");
    rows.forEach((row, i) => {
      (row as HTMLElement).draggable = true;
      row.addEventListener("dragstart", (e) =>
        (e as DragEvent).dataTransfer?.setData("text/echoes-index", String(i)),
      );
      row.addEventListener("dragover", (e) => e.preventDefault());
      row.addEventListener("drop", (e) => {
        e.preventDefault();
        const raw = (e as DragEvent).dataTransfer?.getData("text/echoes-index");
        if (!raw) return;
        const from = Number(raw);
        if (!Number.isInteger(from) || from < 0 || from >= items.length) return;
        items = move(items, from, i - from);
        changed();
      });
    });
  };
  root.append(
    actions(
      button("添加", "plus", () =>
        edit(undefined, (v) => {
          items.push(v);
          changed();
        }),
      ),
      status,
      button(
        "保存编排",
        "floppy-disk",
        async () => {
          ctx.guard();
          await save(items);
          dirty = false;
          delete root.dataset.dirty;
          status.textContent = "已保存";
        },
        "primary",
      ),
    ),
    host,
  );
  void dirty;
  render();
  return root;
}
type Prompt =
  | PromptPresetItem
  | SummaryPromptItem
  | StatusPromptItem
  | RetrievalQueryPresetItem;
const kindNames: Record<string, string> = {
  scene: "时空状态",
  participants: "在场角色",
  commitments: "计划与承诺",
  main: "主提示词",
  custom: "自定义文本",
  type_writer: "写表提示词",
  character: "角色卡",
  worldbook: "世界书",
  persona: "用户设定",
  previous_summaries: "前文总结",
  messages: "增量消息",
  current_state: "当前状态",
  current_message: "当前消息",
  recent_messages: "近期消息",
};
export function promptEditor(
  mode: "structured" | "summary" | "status" | "query",
  types: Array<{ id: string; name: string }> = [],
) {
  return (item: Prompt | undefined, done: (item: any) => void) => {
    const kinds =
      mode === "structured"
        ? ["main", "custom", "type_writer"]
        : mode === "summary"
          ? [
              "custom",
              "character",
              "worldbook",
              "persona",
              "previous_summaries",
              "messages",
            ]
          : mode === "status"
            ? [
                "custom",
                "character",
                "worldbook",
                "persona",
                "current_state",
                "messages",
              ]
            : [
                "custom",
                "current_message",
                "recent_messages",
                "character",
                "persona",
                "scene",
                "participants",
                "commitments",
              ];
    const value = (item ?? {}) as any;
    const form = fields([
      { key: "title", label: "标题", value: value.title ?? "", required: true },
      {
        key: "kind",
        label: "内容类型",
        type: "select",
        value: value.kind ?? "custom",
        options: kinds.map((k) => [k, kindNames[k]!]),
      },
      ...(mode !== "query"
        ? [
            {
              key: "role",
              label: "消息角色",
              type: "select",
              value: value.role ?? "system",
              options: [
                ["system", "System"],
                ["user", "User"],
                ["assistant", "Assistant"],
              ],
            } as Field,
          ]
        : []),
      {
        key: "enabled",
        label: "启用",
        type: "checkbox",
        value: value.enabled ?? true,
      },
      {
        key: "typeId",
        label: "目标表",
        type: "select",
        value: value.typeId ?? types[0]?.id ?? "",
        options: types.map((t) => [t.id, t.name]),
      },
      {
        key: "count",
        label: "数量",
        type: "number",
        value: value.count ?? 2,
        min: 0,
        max: 100,
      },
      {
        key: "unit",
        label: "前文计数单位",
        type: "select",
        value: value.unit ?? "batches",
        options: [
          ["batches", "完整批次"],
          ["slices", "切片"],
        ],
      },
      {
        key: "content",
        label: "提示词内容",
        type: "textarea",
        value: value.content ?? "",
        rows: 18,
      },
    ]);
    const update = () => {
      const kind = form.controls.get("kind")!.value;
      for (const [key, show] of Object.entries({
        typeId: kind === "type_writer",
        count: ["previous_summaries", "recent_messages"].includes(kind),
        unit: kind === "previous_summaries",
        content: ["main", "custom"].includes(kind),
      })) {
        (form.controls.get(key)!.closest("label") as HTMLElement).hidden =
          !show;
        form.controls.get(key)!.disabled = !show;
      }
    };
    form.controls.get("kind")!.addEventListener("change", update);
    update();
    form.node.addEventListener("submit", (e) => e.preventDefault());
    dialog(
      item ? "编辑提示词" : "添加提示词",
      form.node,
      () => {
        const v = form.values();
        const result: any = {
          id: value.id ?? id("prompt"),
          title: v.title,
          kind: v.kind,
          enabled: v.enabled,
        };
        if (mode !== "query") result.role = v.role;
        if (["custom", "main"].includes(v.kind)) result.content = v.content;
        if (v.kind === "type_writer") result.typeId = v.typeId;
        if (["previous_summaries", "recent_messages"].includes(v.kind))
          result.count = v.count;
        if (v.kind === "previous_summaries") result.unit = v.unit;
        done(result);
      },
      form.dirty,
    );
  };
}
export function promptDescription(item: Prompt): [string, string] {
  return [item.title, kindNames[item.kind] ?? item.kind];
}
export function ruleEditor(
  item: SummaryPreprocessRule | undefined,
  done: (item: SummaryPreprocessRule) => void,
) {
  editDialog(
    item ? "编辑清洗规则" : "添加清洗规则",
    [
      { key: "name", label: "名称", value: item?.name, required: true },
      {
        key: "type",
        label: "操作",
        type: "select",
        value: item?.type ?? "remove",
        options: [
          ["remove", "删除匹配"],
          ["replace", "替换"],
          ["extract", "保留匹配"],
        ],
      },
      {
        key: "pattern",
        label: "正则表达式",
        value: item?.pattern,
        required: true,
        wide: true,
      },
      { key: "flags", label: "标志", value: item?.flags ?? "g" },
      { key: "replacement", label: "替换文本", value: item?.replacement },
      {
        key: "user",
        label: "用户消息",
        type: "checkbox",
        value: item?.roles.includes("user") ?? true,
      },
      {
        key: "assistant",
        label: "助手消息",
        type: "checkbox",
        value: item?.roles.includes("assistant") ?? true,
      },
    ],
    (v) => {
      new RegExp(v.pattern, v.flags);
      done({
        id: item?.id ?? id("rule"),
        name: v.name,
        type: v.type,
        pattern: v.pattern,
        flags: v.flags,
        replacement: v.replacement,
        roles: [
          ...(v.user ? ["user" as const] : []),
          ...(v.assistant ? ["assistant" as const] : []),
        ],
        enabled: item?.enabled ?? true,
        order: item?.order ?? 0,
      });
    },
  );
}
export function typeEditor(
  current: Pick<
    MemoryTypeTemplate,
    "name" | "description" | "columns" | "writePrompt"
  >,
  save: (value: {
    name: string;
    description: string;
    columns: MemoryColumnDefinition[];
    writePrompt: string;
  }) => Promise<unknown>,
  title = "编辑表结构",
) {
  let columns = structuredClone(current.columns);
  let columnsDirty = false;
  const form = fields([
    { key: "name", label: "名称", value: current.name, required: true },
    { key: "description", label: "用途", value: current.description },
    {
      key: "writePrompt",
      label: "写表提示词",
      type: "textarea",
      value: current.writePrompt,
      required: true,
      rows: 9,
    },
  ]);
  const host = el("div");
  const editColumn = (index?: number) => {
    const col = index === undefined ? undefined : columns[index];
    editDialog(
      col ? "编辑字段" : "添加字段",
      [
        {
          key: "id",
          label: "字段 ID",
          value: col?.id ?? id("column"),
          required: true,
          readonly: !!col,
        },
        { key: "name", label: "表头名称", value: col?.name, required: true },
        {
          key: "type",
          label: "字段类型",
          type: "select",
          value: col?.type ?? "text",
          options: MEMORY_COLUMN_TYPES.map((x) => [x, x]),
        },
        {
          key: "required",
          label: "必填",
          type: "checkbox",
          value: col?.required ?? false,
        },
        { key: "description", label: "字段说明", value: col?.description },
        {
          key: "enumValues",
          label: "枚举选项（每行一项）",
          type: "textarea",
          value: col?.enumValues?.join("\n") ?? "",
        },
        {
          key: "defaultValue",
          label: "默认值（JSON，可留空）",
          value:
            col?.defaultValue === undefined
              ? ""
              : JSON.stringify(col.defaultValue),
          wide: true,
        },
      ],
      (v) => {
        const next: MemoryColumnDefinition = {
          id: v.id,
          name: v.name,
          type: v.type,
          required: v.required,
          description: v.description,
        };
        if (v.enumValues.trim())
          next.enumValues = v.enumValues
            .split("\n")
            .map((x: string) => x.trim())
            .filter(Boolean);
        if (v.defaultValue.trim())
          next.defaultValue = JSON.parse(v.defaultValue);
        if (index === undefined) columns.push(next);
        else columns[index] = next;
        columnsDirty = true;
        render();
      },
    );
  };
  const render = () => {
    host.replaceChildren(
      actions(
        el("h3", "", "字段顺序"),
        button("添加字段", "plus", () => editColumn()),
      ),
      table(
        ["顺序", "表头", "类型", "必填", "操作"],
        columns.map((col, i) => [
          i + 1,
          col.name,
          col.type,
          col.required ? "是" : "否",
          actions(
            tool("编辑字段", "pen", () => editColumn(i)),
            tool("字段上移", "arrow-up", () => {
              columns = move(columns, i, -1);
              columnsDirty = true;
              render();
            }),
            tool("字段下移", "arrow-down", () => {
              columns = move(columns, i, 1);
              columnsDirty = true;
              render();
            }),
            tool(
              "删除字段",
              "trash",
              () => {
                if (confirm("删除字段可能移除已有记录中的该字段，继续？")) {
                  columns.splice(i, 1);
                  columnsDirty = true;
                  render();
                }
              },
              "danger",
            ),
          ),
        ]),
      ),
    );
    host.querySelectorAll<HTMLElement>("tbody tr").forEach((row, i) => {
      row.draggable = true;
      row.addEventListener("dragstart", (event) =>
        (event as DragEvent).dataTransfer?.setData(
          "text/echoes-column",
          String(i),
        ),
      );
      row.addEventListener("dragover", (event) => event.preventDefault());
      row.addEventListener("drop", (event) => {
        event.preventDefault();
        const raw = (event as DragEvent).dataTransfer?.getData(
          "text/echoes-column",
        );
        if (!raw) return;
        const from = Number(raw);
        if (!Number.isInteger(from) || from < 0 || from >= columns.length)
          return;
        columns = move(columns, from, i - from);
        columnsDirty = true;
        render();
      });
    });
  };
  render();
  const body = el("div", "ew-page-content", form.node, host);
  form.node.addEventListener("submit", (e) => e.preventDefault());
  return dialog(
    title,
    body,
    async () => {
      const v = form.values();
      while (true) {
        try {
          await save({ name: v.name, description: v.description, writePrompt: v.writePrompt, columns });
          break;
        } catch (error) {
          if (!(error instanceof MemorySchemaBackfillRequiredError)) throw error;
          const resolved = await new Promise<boolean>((resolve) => {
            const correction = fields(error.missing.flatMap(({ column, count, rowNames }, index): Field[] => [
              { key: `optional_${index}`, label: `${column.name}：暂设为非必填`, type: "checkbox", value: false, wide: true },
              { key: `default_${index}`, label: `${column.name}：默认值（JSON，${column.type}；缺值 ${count} 条：${rowNames.join("、")}${count > rowNames.length ? "等" : ""}）`,
                value: "", wide: true },
            ]));
            const body = el("div", "ew-page-content",
              el("p", "ew-muted", '默认值仅填补缺值记录，同时用于今后的缺值数据。文本请填写 JSON 字符串，如 "待补充"；数字直接填写，布尔值使用 true 或 false。不提供默认值时，可暂设为非必填。'),
              correction.node);
            const modal = dialog("补齐已有记录的新必填字段", body, () => {
              const values = correction.values();
              const next = structuredClone(columns);
              for (const [index, { column }] of error.missing.entries()) {
                const target = next.find((item) => item.id === column.id)!;
                if (values[`optional_${index}`]) { target.required = false; continue; }
                let value: unknown;
                try { value = JSON.parse(values[`default_${index}`]); }
                catch { throw new Error(`“${column.name}”需要有效 JSON 默认值，或选择暂设为非必填。`); }
                validateMemoryValues([{ ...target, defaultValue: undefined }], { [target.id]: value });
                target.defaultValue = value;
              }
              columns = next;
              columnsDirty = true;
              render();
              resolve(true);
            }, correction.dirty);
            modal.addEventListener("close", () => resolve(false), { once: true });
          });
          if (!resolved) throw new Error("已取消补齐，表结构与已有记录均未保存。");
        }
      }
    },
    () => form.dirty() || columnsDirty,
  );
}
