import type { StatusCatalog, StatusState } from "../../shared/domain";
import { renderStatusVariables } from "../../shared/status-variables";
import { renderStatusYaml } from "./status-request";

export function renderStatusInjection(catalog: StatusCatalog, state: StatusState, template = catalog.profile.injection.template): string {
  const yaml = renderStatusYaml(state);
  const status = template.includes("{{status}}") ? template.replaceAll("{{status}}", yaml) : `${template}\n\n${yaml}`;
  const variables = renderStatusVariables(catalog.customVariables ?? []);
  return [status.trim(), variables].filter(Boolean).join("\n\n");
}
