import { checkpointFloor, messageRangeByFloor } from "../chat-message-index";
import { inspectSummaryCoverage } from "../summary/coverage";
import { WorldbookMemoryStore } from "../worldbook/worldbook-memory";
import { actions, badge, button, check, detail, dialog, el, empty, fields, local, section, table, tool, type ViewContext } from "./core";

export async function summaryCoverageView(ctx: ViewContext): Promise<HTMLElement> {
  const state = await ctx.summary.load();
  const range = local(ctx, "summary-coverage-range", () => ({
    start: 0, end: Math.max(0, SillyTavern.getContext().chat.length - 1), instructions: "",
  }));
  const form = fields([
    { key: "start", label: "起始楼层", type: "number", min: 0, max: SillyTavern.getContext().chat.length - 1, value: range.start, required: true },
    { key: "end", label: "结束楼层", type: "number", min: 0, max: SillyTavern.getContext().chat.length - 1, value: range.end, required: true },
    { key: "instructions", label: "定向补全要求", type: "textarea", rows: 4, value: range.instructions },
  ], false);
  form.node.addEventListener("input", () => Object.assign(range, {
    start: Number(form.controls.get("start")!.value), end: Number(form.controls.get("end")!.value),
    instructions: form.controls.get("instructions")!.value,
  }));
  const root = el("div", "ew-page-content");
  const host = el("div");
  const inspect = async () => {
    ctx.guard();
    const values = form.values();
    const { messages } = messageRangeByFloor(values.start, values.end);
    const ids = new Set(messages.map((message) => message.id));
    const latest = await ctx.summary.load();
    const slices = latest.slices.filter((slice) => slice.batch.state !== "stale"
      && slice.batch.source?.kind !== "imported" && slice.batch.messageIds.some((id) => ids.has(id)));
    const memory = await new WorldbookMemoryStore().inspect(state.worldbookName).catch(() => null);
    ctx.guard();
    const report = inspectSummaryCoverage(messages, slices, memory?.rows.map((row) => row.dataName) ?? []);
    let page = 0;
    const regions = el("div");
    const draw = () => {
      const previous = tool("上一页内容区域", "chevron-left", () => { page--; draw(); });
      const next = tool("下一页内容区域", "chevron-right", () => { page++; draw(); });
      previous.disabled = page === 0;
      next.disabled = (page + 1) * 25 >= report.regions.length;
      regions.replaceChildren(table(["楼层 / 字符区间", "词面匹配", "年份线索", "已命名条目", "操作"], report.regions.slice(page * 25, (page + 1) * 25).map((region) => [
        `${checkpointFloor(region.messageId)} / ${region.start}-${region.end}`,
        badge(region.matchedRatio === null ? "不可评估" : `${Math.round(region.matchedRatio * 100)}%`, region.warning ? "warning" : ""),
        region.years.join(" / ") || "-", region.names.join(" / ") || "-",
        actions(tool("查看区域原文", "eye", () => {
          const message = messages.find((item) => item.id === region.messageId)!;
          dialog("原文区域（不是精确证据标注）", el("pre", "ew-code", message.content.slice(region.start, region.end)));
        }), tool("选择此楼层补全", "arrow-up", () => {
          const floor = checkpointFloor(region.messageId);
          form.controls.get("start")!.value = String(floor);
          form.controls.get("end")!.value = String(floor);
          Object.assign(range, { start: floor, end: floor });
        })),
      ])), actions(previous, badge(`${page + 1} / ${Math.max(1, Math.ceil(report.regions.length / 25))}`), next));
    };
    draw();
    host.replaceChildren(
      actions(badge(`输入 ${report.inputMessages} 条 / ${report.inputCharacters} 字符`), badge(`对应批次切片 ${report.outputSlices}`),
        badge(`低匹配区域 ${report.regions.filter((region) => region.warning).length}`, "warning")),
      badge("词面匹配仅作预警，不判定漏记；来源按批次关联，不是切片精确证据", "warning"),
      detail("输出时间分布", report.timestamps), detail("已命名条目覆盖", report.names), regions,
    );
  };
  root.append(section("覆盖检查", form.node, actions(
    button("本地检查", "magnifying-glass", inspect),
    button("预览子请求", "eye", async () => {
      const values = form.values();
      ctx.guard();
      dialog("总结子请求预览", detail("楼层范围、清洗内容与子请求", await ctx.summary.previewManual(values.start, values.end)));
    }),
    button("模型深度检查", "magnifying-glass", async () => {
      const values = form.values();
      ctx.guard();
      const preview = await ctx.summary.previewManual(values.start, values.end);
      ctx.guard();
      if (!confirm(`将额外提交 ${preview.subRequests?.length ?? 1} 个覆盖检查请求，使用总结端点并产生费用。只输出可能遗漏的区域建议，不生成切片或修改检查点。继续？`)) return;
      await ctx.run("模型覆盖检查", () => ctx.summary.checkCoverage(values.start, values.end), () => ctx.summary.stop());
      await ctx.refresh();
    }),
    button("生成补全候选", "plus", async () => {
      const values = form.values();
      ctx.guard();
      const preview = await ctx.summary.previewManual(values.start, values.end);
      ctx.guard();
      if (!confirm(`将提交 ${preview.subRequests?.length ?? 1} 个总结子请求，可能产生生成费用。结果只进入待审核候选，不修改原切片或检查点。继续？`)) return;
      await ctx.run("定向补全", () => ctx.summary.generateSupplement(values.start, values.end, values.instructions), () => ctx.summary.stop());
      await ctx.refresh();
    }, "primary"),
    button("停止总结任务", "stop", () => ctx.summary.stop(), "danger"),
  ), host));
  const review = ctx.summary.coverageReview(state);
  if (review) {
    let reviewPage = 0;
    const reviewList = el("div");
    const drawReview = () => {
      const previous = tool("上一页模型检查建议", "chevron-left", () => { reviewPage--; drawReview(); });
      const next = tool("下一页模型检查建议", "chevron-right", () => { reviewPage++; drawReview(); });
      previous.disabled = reviewPage === 0;
      next.disabled = (reviewPage + 1) * 25 >= review.findings.length;
      reviewList.replaceChildren(table(["楼层 / 清洗后字符区间", "模型检查建议", "操作"],
        review.findings.slice(reviewPage * 25, (reviewPage + 1) * 25).map((finding) => [
          `${checkpointFloor(finding.messageId)} / ${finding.start}-${finding.end}`, finding.reason,
          actions(tool("查看检查时的输入文本", "eye", () => dialog("检查输入快照", el("pre", "ew-code", finding.text))),
            tool("选择建议楼层补全", "arrow-up", () => {
              const floor = checkpointFloor(finding.messageId);
              if (floor < 0) throw new Error("原楼层已不存在，请重新检查。");
              form.controls.get("start")!.value = String(floor);
              form.controls.get("end")!.value = String(floor);
              Object.assign(range, { start: floor, end: floor });
            })),
        ])), actions(previous, badge(`${reviewPage + 1} / ${Math.max(1, Math.ceil(review.findings.length / 25))}`), next));
    };
    drawReview();
    root.append(section("模型检查结果",
      badge(`检查快照 ${new Date(review.checkedAt).toLocaleString()} / 楼层 ${review.startFloor}-${review.endFloor}`),
      badge("仅为可能遗漏的建议；消息或切片变更后需重新检查", "warning"),
      review.findings.length ? reviewList : empty("本次检查未提出遗漏建议，不代表已证明完全覆盖")));
  }
  const draft = ctx.summary.supplementDraft();
  if (!draft) { root.append(empty("本次会话暂无补全候选")); return root; }
  const existing = draft.state.slices.filter((slice) => slice.batch.state !== "stale");
  const selected = new Set(draft.comparisons.filter((item) => !item.duplicate).map((item) => item.index));
  const list = el("div");
  let page = 0;
  const draw = () => {
    const previous = tool("上一页补全候选", "chevron-left", () => { page--; draw(); });
    const next = tool("下一页补全候选", "chevron-right", () => { page++; draw(); });
    previous.disabled = page === 0;
    next.disabled = (page + 1) * 25 >= draft.candidates.length;
    list.replaceChildren(table(["选择", "时间", "候选标题", "对照", "正文"], draft.candidates.slice(page * 25, (page + 1) * 25).map((candidate, offset) => {
      const index = page * 25 + offset;
      const comparison = draft.comparisons[index]!;
      const checkbox = check(`选择补全 ${index + 1}`, selected.has(index), (value) => value ? selected.add(index) : selected.delete(index));
      checkbox.disabled = comparison.duplicate;
      return [checkbox, candidate.timestamp, candidate.title, comparison.duplicate ? badge("完全重复", "warning")
        : comparison.similar.length ? button("查看相近原切片", "copy", () =>
          dialog("相近切片（不自动合并）", detail("已有正文", comparison.similar.map((item) => existing[item.existingIndex])))) : badge("无高词面相似记录"),
      detail("候选正文", candidate.content)];
    })), actions(previous, badge(`${page + 1} / ${Math.ceil(draft.candidates.length / 25)}`), next));
  };
  draw();
  root.append(section("补全候选审核", badge("仅本次会话保留；提交为独立补全批次，不移动检查点，也不自动向量化"),
    list, actions(button("追加选中切片", "floppy-disk", async () => {
      ctx.guard();
      if (!confirm(`追加 ${selected.size} 个选中候选？原切片保持不变，随后将单独调用总结副 API 生成批次总结。`)) return;
      await ctx.run("提交补全切片与批次总结", () => ctx.summary.commitSupplement([...selected]), () => ctx.summary.stop());
      await ctx.refresh();
    }, "primary"), button("丢弃候选", "trash", async () => {
      if (!confirm("丢弃本次补全候选？")) return;
      ctx.summary.discardSupplement();
      await ctx.refresh();
    }, "danger"))));
  return root;
}
