import { randomUuid, sha256Hex } from "../../shared/crypto-compat";
import { memoryLinkSchema, refKey, type MemoryLink, type MemoryReference } from "../../shared/continuity";
import { worldbookWriteCoordinator } from "./worldbook-write-coordinator";
import { sourceMessagesHash } from "../../shared/source-hash";
import type { SummarySlice } from "../../shared/domain";
import { currentChatMessages } from "../summary/summary-request";

export interface MemoryLinksSnapshot { worldbookName: string; chatId: string; fingerprint: string; links: MemoryLink[] }
export async function readMemoryLinks(worldbookName: string): Promise<MemoryLinksSnapshot> {
  const entries = await window.TavernHelper!.getWorldbook(worldbookName);
  const metadata = entries.find((entry) => entry.extra?.echoes?.kind === "memory_links")?.extra?.echoes;
  const links = memoryLinkSchema.array().max(10000).parse(metadata?.links ?? []);
  return { worldbookName, chatId: SillyTavern.getContext().chatId ?? "", fingerprint: await sha256Hex(JSON.stringify(links)), links };
}
export async function saveMemoryLinks(expected: MemoryLinksSnapshot, links: MemoryLink[]): Promise<void> {
  const parsed = memoryLinkSchema.array().max(10000).parse(links);
  await worldbookWriteCoordinator.run(expected.worldbookName, async () => {
    await window.TavernHelper!.updateWorldbookWith(expected.worldbookName, async (entries) => {
      if (SillyTavern.getContext().chatId !== expected.chatId
        || window.TavernHelper!.getChatWorldbookName("current") !== expected.worldbookName) throw new Error("聊天已切换，关联未保存。");
      const old = entries.find((entry) => entry.extra?.echoes?.kind === "memory_links");
      if (await sha256Hex(JSON.stringify(old?.extra?.echoes?.links ?? [])) !== expected.fingerprint) throw new Error("关联已变化，请刷新后重试。");
      const available = new Set(entries.flatMap((entry) => {
        const item = entry.extra?.echoes;
        return item?.kind === "row" ? [`row:${item.rowId}`] : item?.kind === "summary_slice" ? [`summary:${item.summaryId}`] : [];
      }));
      if (new Set(parsed.map((link) => link.id)).size !== parsed.length) throw new Error("关联 ID 重复。");
      for (const link of parsed) {
        if (!available.has(refKey(link.from)) || !available.has(refKey(link.to))) {
          // Existing dangling links may be disabled or removed, never activated or created.
          const previous = expected.links.find((item) => item.id === link.id);
          if (!previous || link.enabled || JSON.stringify(previous.from) !== JSON.stringify(link.from)
            || JSON.stringify(previous.to) !== JSON.stringify(link.to)) throw new Error("关联目标已删除，请移除或禁用该关联。");
        }
        if (refKey(link.from) === refKey(link.to)) throw new Error("不能建立自身关联。");
      }
      const value = { name: "Echoes Memory Links", enabled: false, content: "Echoes memory links. Not injected.",
        strategy: { type: "constant" as const, keys: [] }, extra: { echoes: { kind: "memory_links", version: 1, links: parsed } } };
      if (old) Object.assign(old, value);
      else entries.push(value as unknown as TavernWorldbookEntry);
      return entries;
    }, { render: "debounced" });
  });
}
export function newMemoryLink(from: MemoryReference, to: MemoryReference, relation: string): MemoryLink {
  return { id: randomUuid(), from, to, relation, enabled: true };
}

export async function summaryOriginalSource(slice: SummarySlice, owner: { worldbookName: string; chatId: string }) {
  const check = () => {
    if (SillyTavern.getContext().chatId !== owner.chatId
      || window.TavernHelper!.getChatWorldbookName("current") !== owner.worldbookName)
      throw new Error("请切换到切片所属聊天查看原文。");
  };
  check();
  if (slice.batch.source?.kind === "imported") throw new Error("导入切片没有当前聊天的原文定位，不能将相同楼层当作证据。");
  const messages = currentChatMessages();
  const selected = messages.filter((message) => slice.batch.messageIds.includes(message.id));
  if (selected.map((message) => message.id).join("\0") !== slice.batch.messageIds.join("\0")
    || await sourceMessagesHash(selected) !== slice.batch.sourceHash) throw new Error("源消息已变化或不存在，无法验证该批次原文。");
  check();
  return { scope: "批次原文，不是该切片的精确证据", messages: selected };
}
