import type { RetrievalInjectionConfig } from "../../shared/domain";
import { worldbookWriteCoordinator } from "./worldbook-write-coordinator";

interface RetrievalInjectionMetadata {
  kind: "retrieval_injection";
  version: 1;
  chatId: string;
  namespaceId: string;
  createdAt: string;
  updatedAt: string;
}

const ENTRY_NAME = "[Echoes] Retrieval Injection";
const STALE_MS = 5 * 60_000;

function helper(): TavernHelperApi {
  if (!window.TavernHelper) throw new Error("Echoes requires TavernHelper for recall injection.");
  return window.TavernHelper;
}

function metadata(entry: TavernWorldbookEntry): RetrievalInjectionMetadata | null {
  const value = entry.extra?.echoes as Partial<RetrievalInjectionMetadata> | undefined;
  return value?.kind === "retrieval_injection" && value.version === 1
    ? value as RetrievalInjectionMetadata
    : null;
}

function recallEntry(
  chatId: string,
  namespaceId: string,
  content: string,
  config: RetrievalInjectionConfig,
  createdAt: string,
): Partial<TavernWorldbookEntry> {
  const now = new Date().toISOString();
  return {
    name: ENTRY_NAME,
    enabled: Boolean(content.trim()),
    strategy: { type: "constant", keys: [] },
    position: {
      type: config.position === "before_character"
        ? "before_character_definition"
        : config.position === "after_character"
          ? "after_character_definition"
          : "at_depth",
      role: config.role,
      depth: config.depth,
      order: config.order,
    },
    content,
    probability: 100,
    extra: {
      echoes: {
        kind: "retrieval_injection",
        version: 1,
        chatId,
        namespaceId,
        createdAt,
        updatedAt: now,
      } satisfies RetrievalInjectionMetadata,
    },
  };
}

export class RecallWorldbookStore {
  async write(options: {
    worldbookName: string;
    chatId: string;
    namespaceId: string;
    content: string;
    config: RetrievalInjectionConfig;
    guard?: () => void | Promise<void>;
  }): Promise<void> {
    await worldbookWriteCoordinator.run(options.worldbookName, async () => {
      await options.guard?.();
      const api = helper();
      const entries = await api.getWorldbook(options.worldbookName);
      const existing = entries.find((candidate) => metadata(candidate));
      const createdAt = existing
        ? metadata(existing)!.createdAt
        : new Date().toISOString();
      if (existing) {
        await api.updateWorldbookWith(options.worldbookName, async (current) => {
          await options.guard?.();
          return current.map((candidate) =>
          metadata(candidate)
            ? {
                ...candidate,
                ...recallEntry(
                  options.chatId,
                  options.namespaceId,
                  options.content,
                  options.config,
                  createdAt,
                ),
              }
            : candidate); });
      } else {
        await options.guard?.();
        await api.createWorldbookEntries(options.worldbookName, [
          recallEntry(
            options.chatId,
            options.namespaceId,
            options.content,
            options.config,
            createdAt,
          ),
        ]);
      }
    });
  }

  async clear(worldbookName: string): Promise<void> {
    await worldbookWriteCoordinator.run(worldbookName, async () => {
      await helper().updateWorldbookWith(worldbookName, (entries) => entries.map((candidate) => {
        const item = metadata(candidate);
        if (!item) return candidate;
        return {
          ...candidate,
          enabled: false,
          content: "",
          extra: {
            ...candidate.extra,
            echoes: { ...item, updatedAt: new Date().toISOString() },
          },
        };
      }));
    });
  }

  async cleanupStale(worldbookName: string, now = Date.now()): Promise<void> {
    await worldbookWriteCoordinator.run(worldbookName, async () => {
      await helper().updateWorldbookWith(worldbookName, (entries) => entries.map((candidate) => {
        const item = metadata(candidate);
        if (!item || !candidate.enabled || now - Date.parse(item.updatedAt) <= STALE_MS) {
          return candidate;
        }
        return { ...candidate, enabled: false, content: "" };
      }));
    });
  }
}
