import type { StatusState, StatusValidationRule } from "../../shared/domain";
import { statusCoordinator as coordinator } from "../status/status-coordinator";
import {
  renderStatusYaml,
  prepareStatusRequest,
  currentStatusMessages,
} from "../status/status-request";
import {
  getSettings,
  saveSettings,
  instantiateStatusProfile,
} from "../state/settings";
import {
  el,
  actions,
  button,
  tool,
  table,
  fields,
  saveForm,
  section,
  empty,
  detail,
  badge,
  check,
  editDialog,
  dialog,
  notify,
  now,
  id,
  injectionFields,
  type ViewContext,
} from "./core";
import {
  orderedEditor,
  promptEditor,
  promptDescription,
  ruleEditor,
} from "./editors";
import { fieldDifferences, displayValue } from "./diff";
import { statusVariablesView } from "./status-variables";
import { renderStatusInjection } from "../status/status-injection";

function tree(value: unknown): HTMLElement {
  const host = el("div", "ew-tree");
  if (!value || typeof value !== "object") {
    host.append(el("p", "", String(value ?? "")));
    return host;
  }
  for (const [key, v] of Object.entries(value)) {
    if (v && typeof v === "object") {
      const node = el("details", "", el("summary", "", key), tree(v));
      node.open = true;
      host.append(node);
    } else
      host.append(
        el(
          "div",
          "ew-tree-value",
          el("span", "ew-muted", key),
          el("span", "", String(v ?? "")),
        ),
      );
  }
  return host;
}
export async function statusView(ctx: ViewContext): Promise<HTMLElement> {
  const state = await coordinator.load();
  if (ctx.route === "status/variables") return statusVariablesView(ctx, state);
  const profile = state.catalog.profile;
  const current = coordinator.current(state);
  const page = el("div", "ew-page-content");
  const saveProfile = async (patch: Partial<typeof profile>) => {
    ctx.guard();
    const fresh = await coordinator.load();
    await coordinator.worldbook.saveConfiguration(state.worldbookName, {
      profile: { ...fresh.catalog.profile, ...patch, updatedAt: now() },
    });
  };
  if (ctx.route === "status/current") {
    const editToken = coordinator.manualStateToken(state);
    const value = current?.snapshot.state ?? profile.initialState;
    const host = el("div");
    const form = fields([
      {
        key: "yaml",
        label: "当前状态 YAML",
        type: "textarea",
        value: renderStatusYaml(value),
        rows: 22,
      },
    ]);
    form.controls.get("yaml")!.classList.add("ew-editor");
    const showTree = () => {
      if (form.dirty() && !confirm("放弃未保存的 YAML 修改？")) return;
      form.controls.get("yaml")!.value = renderStatusYaml(value);
      form.clean();
      host.replaceChildren(tree(value));
    };
    const showYaml = () => host.replaceChildren(save);
    const save = saveForm(
      form,
      async (v) => {
        ctx.guard();
        const parsed = coordinator.parseYaml(v.yaml);
        await coordinator.saveManualState(parsed, "manual", editToken);
        await ctx.refresh();
      },
      "校验并保存",
    );
    page.append(
      actions(
        button("字段视图", "list-tree", showTree),
        button("YAML 编辑", "code", showYaml),
      ),
      el(
        "div",
        "ew-status-controls",
        el(
          "label",
          "ew-toggle",
          check("启用状态记忆", state.catalog.enabled, async (enabled) => {
            ctx.guard();
            await coordinator.worldbook.saveConfiguration(state.worldbookName, { enabled });
            await ctx.refresh();
          }),
          el("span", "", "启用状态记忆"),
        ),
        el(
          "label",
          "ew-toggle",
          check("自动更新状态", state.catalog.autoUpdate, async (autoUpdate) => {
            ctx.guard();
            await coordinator.worldbook.saveConfiguration(state.worldbookName, { autoUpdate });
            await ctx.refresh();
          }),
          el("span", "", "自动更新状态"),
        ),
        (() => {
          const select = el("select");
          select.setAttribute("aria-label", "未声明字段");
          select.add(new Option("未声明字段：允许", "allow"));
          select.add(new Option("未声明字段：拒绝", "reject"));
          select.value = profile.validation.unknownFields;
          select.addEventListener("change", async () => {
            try {
              ctx.guard();
              const fresh = await coordinator.load();
              await coordinator.worldbook.saveConfiguration(state.worldbookName, {
                profile: {
                  ...fresh.catalog.profile,
                  validation: {
                    ...fresh.catalog.profile.validation,
                    unknownFields: select.value as "allow" | "reject",
                  },
                  updatedAt: now(),
                },
              });
              await ctx.refresh();
            } catch (error) {
              notify(error instanceof Error ? error.message : String(error), true);
            }
          });
          return select;
        })(),
      ),
      actions(
        button(
          "手动同步",
          "arrows-rotate",
          async () => {
            ctx.guard();
            const snapshot = await ctx.run("状态记忆同步", () => coordinator.synchronize());
            const trace = coordinator.trace;
            if (trace?.outcome === "skipped" || trace?.outcome === "failed") {
              notify(trace.message ?? "状态同步未执行。", true);
            } else if (trace?.outcome === "unchanged") {
              notify(trace.message ?? "当前楼层已有匹配的状态快照，无需更新。");
            } else if (trace?.outcome === "decision_required" || trace?.outcome === "discarded") {
              notify(trace.message ?? "状态结果未写入。", true);
            } else if (!snapshot) {
              notify(trace?.message ?? "本次没有生成新的状态快照。", true);
            } else {
              notify(`状态已同步：快照来源消息 ${snapshot.targetMessageId}。`);
            }
            await ctx.refresh();
          },
          "primary",
        ),
        button("恢复初始值", "rotate-left", async () => {
          if (confirm("将当前状态恢复为模板初始值？")) {
            ctx.guard();
            await coordinator.saveManualState(profile.initialState, "manual", editToken);
            await ctx.refresh();
          }
        }),
      ),
      current
        ? el(
            "p",
            "ew-muted",
            "来源消息：" +
              current.messageId +
              " · " +
              new Date(current.snapshot.updatedAt).toLocaleString(),
          )
        : badge("使用初始状态"),
      host,
    );
    showTree();
    const trace = coordinator.trace;
    page.append(
      section(
        "最近任务诊断",
        trace
          ? actions(
              badge(trace.outcome, trace.outcome === "failed" || trace.outcome === "skipped" ? "warning" : ""),
              el("span", "ew-muted", new Date(trace.completedAt).toLocaleString()),
            )
          : empty("本次会话尚无状态任务"),
        trace?.message ? el("p", "ew-muted", trace.message) : null,
        trace ? detail("任务详情", trace) : null,
      ),
    );
    return page;
  }
  if (ctx.route === "status/history") {
    const history = coordinator.history(state);
    if (!history.length) return empty("暂无状态快照");
    page.append(
      table(
        ["消息", "分支", "记录时间", "来源", "操作"],
        history.map((record, i) => [
          record.messageId,
          record.swipeId,
          new Date(record.snapshot.updatedAt).toLocaleString(),
          record.snapshot.origin,
          actions(
            button("查看快照", "eye", () =>
              dialog(
                "状态快照",
                el(
                  "div",
                  "ew-page-content",
                  tree(record.snapshot.state),
                  detail("快照元数据", record.snapshot),
                ),
              ),
            ),
            button("比较", "code-compare", () => {
              const changes = fieldDifferences(
                record.snapshot.state,
                current?.snapshot.state ?? profile.initialState,
              );
              dialog(
                "选中快照 → 当前状态",
                changes.length
                  ? table(
                      ["字段路径", "选中快照", "当前状态"],
                      changes.map((c) => [
                        c.path.join(" / "),
                        displayValue(c.before),
                        displayValue(c.after),
                      ]),
                    )
                  : empty("两个状态没有差异"),
              );
            }),
            tool("恢复此快照", "rotate-left", async () => {
              if (confirm("恢复选中快照为当前状态？")) {
                ctx.guard();
                await coordinator.restoreSnapshot(record.snapshot);
                await ctx.refresh();
              }
            }),
          ),
        ]),
      ),
    );
    return page;
  }
  if (ctx.route === "status/prompts") {
    page.append(
      section(
        "提示词编排",
        orderedEditor(
          ctx,
          "提示词",
          profile.promptPreset.items,
          promptDescription,
          promptEditor("status"),
          (items) =>
            saveProfile({
              promptPreset: {
                ...profile.promptPreset,
                items,
                updatedAt: now(),
              },
            }),
        ),
      ),
      section(
        "消息清洗",
        orderedEditor(
          ctx,
          "规则",
          profile.preprocessRules,
          (r) => [r.name, r.type],
          ruleEditor,
          (items) =>
            saveProfile({
              preprocessRules: items.map((r, i) => ({ ...r, order: i })),
            }),
        ),
      ),
    );
    return page;
  }
  if (ctx.route === "status/injection") {
    const f = fields([
      {
        key: "enabled",
        label: "状态注入",
        type: "checkbox",
        value: state.catalog.enabled,
      },
      ...injectionFields(profile.injection),
    ]);
    page.append(
      saveForm(f, async (v) => {
        ctx.guard();
        const { enabled, ...injection } = v;
        const fresh = await coordinator.load();
        await coordinator.worldbook.saveConfiguration(state.worldbookName, {
          enabled,
          profile: {
            ...fresh.catalog.profile,
            injection: injection as any,
            updatedAt: now(),
          },
        });
      }),
    );
    page.append(
      button("预览注入内容", "eye", () => {
        const template = String(f.controls.get("template")!.value);
        dialog(
          "状态注入预览",
          detail(
            "注入文本",
            renderStatusInjection(state.catalog, current?.snapshot.state ?? profile.initialState, template),
          ),
        );
      }),
    );
    return page;
  }
  if (ctx.route === "status/rules") {
    const rules = profile.validation.rules.map((r) => ({
      ...r,
      enabled: true,
    }));
    page.append(
      section(
        "声明式校验",
        orderedEditor(
          ctx,
          "校验规则",
          rules,
          (r) => [r.name, r.path.join(".") + " · " + r.type],
          (item, done) =>
            editDialog(
              "校验规则",
              [
                {
                  key: "name",
                  label: "名称",
                  value: item?.name,
                  required: true,
                },
                {
                  key: "path",
                  label: "字段路径（点分隔）",
                  value: item?.path.join("."),
                  required: true,
                },
                {
                  key: "type",
                  label: "类型",
                  type: "select",
                  value: item?.type ?? "string",
                  options: [
                    "string",
                    "number",
                    "boolean",
                    "object",
                    "array",
                    "null",
                  ].map((x) => [x, x]),
                },
                {
                  key: "required",
                  label: "必须存在",
                  type: "checkbox",
                  value: item?.required ?? false,
                },
                {
                  key: "enumValues",
                  label: "枚举值（JSON 数组，可留空）",
                  value: item?.enumValues
                    ? JSON.stringify(item.enumValues)
                    : "",
                },
                ...(["minimum", "maximum", "maxDelta"] as const).map((key) => ({
                  key,
                  label: {
                    minimum: "最小值",
                    maximum: "最大值",
                    maxDelta: "单次最大变化",
                  }[key],
                  value: item?.[key] ?? "",
                })),
              ],
              (v) => {
                const r: any = {
                  id: item?.id ?? id("validation"),
                  name: v.name,
                  path: v.path.split("."),
                  type: v.type,
                  required: v.required,
                  enabled: true,
                };
                for (const k of ["minimum", "maximum", "maxDelta"])
                  if (v[k] !== "") {
                    r[k] = Number(v[k]);
                    if (!Number.isFinite(r[k]))
                      throw new Error("限制值必须是数字。");
                  }
                if (v.enumValues.trim())
                  r.enumValues = JSON.parse(v.enumValues);
                done(r);
              },
            ),
          (items) =>
            saveProfile({
              validation: {
                ...profile.validation,
                rules: items.map(({ enabled, ...r }) => r),
              },
            }),
          false,
        ),
      ),
    );
    return page;
  }
  const initial = fields([
    { key: "name", label: "当前配置名称", value: profile.name, required: true },
    { key: "description", label: "说明", value: profile.description },
    {
      key: "initial",
      label: "初始状态 YAML",
      type: "textarea",
      value: renderStatusYaml(profile.initialState),
      rows: 14,
    },
  ]);
  page.append(
    section(
      "当前聊天配置",
      saveForm(initial, async (v) => {
        await saveProfile({
          name: v.name,
          description: v.description,
          initialState: coordinator.parseYaml(v.initial),
        });
      }),
    ),
  );
  const settings = getSettings();
  page.append(
    section(
      "全局状态模板",
      actions(
        button("保存当前配置为模板", "plus", () =>
          editDialog(
            "新建状态模板",
            [
              {
                key: "name",
                label: "模板名称",
                value: profile.name,
                required: true,
              },
            ],
            (v) => {
              const s = getSettings();
              s.statusTemplates.push({
                id: id("status_template"),
                name: v.name,
                description: profile.description,
                initialState: profile.initialState,
                promptPreset: profile.promptPreset,
                preprocessRules: profile.preprocessRules,
                validation: profile.validation,
                injection: profile.injection,
                builtIn: false,
                version: 1,
                createdAt: now(),
                updatedAt: now(),
              });
              saveSettings(s);
              void ctx.refresh();
            },
          ),
        ),
      ),
      table(
        ["模板", "用途", "来源", "操作"],
        settings.statusTemplates.map((t) => [
          t.name,
          t.description,
          t.builtIn ? "内置" : "自定义",
          actions(
            button("应用", "check", async () => {
              if (confirm("用此模板重建当前聊天配置？当前状态快照保持不变。")) {
                ctx.guard();
                await coordinator.worldbook.saveConfiguration(
                  state.worldbookName,
                  { profile: instantiateStatusProfile(t) },
                );
                await ctx.refresh();
              }
            }),
            ...(!t.builtIn
              ? [
                  tool("以当前配置覆盖模板", "floppy-disk", async () => {
                    if (confirm("覆盖模板 " + t.name + "？")) {
                      const s = getSettings();
                      s.statusTemplates = s.statusTemplates.map((x) =>
                        x.id === t.id
                          ? {
                              ...x,
                              initialState: profile.initialState,
                              promptPreset: profile.promptPreset,
                              preprocessRules: profile.preprocessRules,
                              validation: profile.validation,
                              injection: profile.injection,
                              version: x.version + 1,
                              updatedAt: now(),
                            }
                          : x,
                      );
                      saveSettings(s);
                      await ctx.refresh();
                    }
                  }),
                  tool(
                    "删除模板",
                    "trash",
                    async () => {
                      if (confirm("删除状态模板 " + t.name + "？")) {
                        const s = getSettings();
                        s.statusTemplates = s.statusTemplates.filter(
                          (x) => x.id !== t.id,
                        );
                        saveSettings(s);
                        await ctx.refresh();
                      }
                    },
                    "danger",
                  ),
                ]
              : []),
          ),
        ]),
      ),
    ),
  );
  return page;
}
