function showResult(title: string, result: unknown) {
  const body = detail("完整结果", result);
  body.open = true;
  dialog(title, body);
}
function statusSummary(job: JobListRecord): HTMLElement {
  const r = job.resultSummary;
  return el(
    "div",
    "ew-page-content",
    job.error
      ? el("p", "danger", job.error.message)
      : el("p", "ew-muted", job.message),
    job.usage ? table(["用量项目", "数值"], [
      ["供应商请求数", String(job.usage.providerCalls)],
      ["累计请求字符", String(job.usage.inputCharacters)],
      ["输入 Token 粗估（非账单）", String(job.usage.estimatedInputTokens)],
      ["已上报用量的请求数", String(job.usage.reportedCalls)],
      ["供应商上报输入 / 输出 Token", `${job.usage.inputTokens} / ${job.usage.outputTokens}`],
      ["供应商上报缓存输入 Token", String(job.usage.cachedInputTokens)],
    ]) : null,
    job.budget ? detail("本任务预算", job.budget) : null,
    r
      ? actions(
          badge("已向量化 " + (r.vectorized ?? 0)),
          badge("失败 " + (r.failed ?? 0), r.failed ? "danger" : ""),
          badge("待处理 " + (r.pending ?? 0)),
          badge("待确认 " + (r.ambiguous ?? 0), r.ambiguous ? "warning" : ""),
        )
      : null,
    ...(r?.attempts ?? [])
      .filter((a) => a.message)
      .map((a) =>
        el(
          "p",
          a.outcome === "succeeded" ? "ew-muted" : "danger",
          a.endpointName + " · " + (a.status ?? a.outcome) + " · " + a.message,
        ),
      ),
  );
}
export async function maintenanceView(ctx: ViewContext): Promise<HTMLElement> {
  if (ctx.route === "maintenance/pipeline") {
    return ctx.chatId ? memoryPipelineView(ctx) : empty("请先选择一个聊天");
  }
  if (ctx.route === "maintenance/jobs") {
    const page = el("div", "ew-page-content");
    const ui = local(ctx, "job-filter", () => ({ status: "", query: "" }));
    const host = el("div");
    const f = fields(
      [
        {
          key: "status",
          label: "任务状态",
          type: "select",
          value: ui.status,
          options: [
            ["", "全部"],
            ["running", "运行中"],
            ["queued", "排队中"],
            ["succeeded", "已完成"],
            ["failed", "失败"],
            ["ambiguous", "待确认"],
            ["cancelled", "已取消"],
          ],
        },
      ],
      false,
    );
    let jobs: JobListRecord[] = [];
    const draw = () => {
      const list = jobs.filter((j) =>
        JSON.stringify(j).toLowerCase().includes(ui.query.toLowerCase()),
      );
      host.replaceChildren(
        ...list.map((job) => {
          const entry = el("details", "ew-job-log");
          entry.append(
            el(
              "summary",
              "ew-actions",
              stateBadge(job.status),
              el("strong", "", job.type),
              el("time", "ew-muted", new Date(job.createdAt).toLocaleString()),
              job.resultSummary?.failed
                ? badge("内容失败 " + job.resultSummary.failed, "danger")
                : null,
            ),
            el(
              "div",
              "ew-page-content",
              statusSummary(job),
              detail("任务 JSON", job),
              ["running", "queued"].includes(job.status)
                ? button(
                    "取消此任务",
                    "stop",
                    async () => {
                      const result = await api.cancelJob(job.id);
                      if (!result.cancelled)
                        throw new Error("后台未确认取消，请刷新检查。");
                      await load();
                    },
                    "danger",
                  )
                : null,
            ),
          );
          return entry;
        }),
      );
      if (!list.length) host.append(empty("暂无匹配的任务日志"));
    };
    const load = async () => {
      jobs = (await api.listJobs({ status: ui.status, limit: 200 })).jobs;
      if (!ctx.signal.aborted) draw();
    };
    f.controls.get("status")!.addEventListener("change", () => {
      ui.status = f.controls.get("status")!.value;
      void load().catch((e) => showResult("读取任务日志失败", String(e)));
    });
    page.append(
      el(
        "div",
        "ew-toolbar",
        searchBox(
          ui.query,
          (v) => {
            ui.query = v;
            draw();
          },
          "搜索任务、端点或错误",
          ctx.signal,
        ),
        actions(
          f.node,
          button("刷新日志", "rotate", load),
          button("导出日志", "download", () =>
            download(
              "echoes-tasks.json",
              JSON.stringify(redactLog(jobs), null, 2),
            ),
          ),
        ),
      ),
      host,
    );
    const consoleSection = el(
      "details",
      "ew-detail",
      el("summary", "", "控制台日志"),
      consoleView(ctx),
    );
    page.append(consoleSection);
    await load();
    return page;
  }
  if (ctx.route === "maintenance/console") return consoleView(ctx);
  if (ctx.route === "maintenance/collections") return collectionsView(ctx);
  if (ctx.route === "maintenance/query") return queryView(ctx);
  if (ctx.route === "maintenance/backup") {
    const page = el("div", "ew-page-content");
    const options = fields([
      {
        key: "global",
        label: "包含全局设置（不含密钥）",
        type: "checkbox",
        value: false,
      },
    ]);
    page.append(
      section(
        "备份当前聊天",
        options.node,
        button(
          "导出备份",
          "download",
          async () => {
            ctx.guard();
            const backup = await ctx.run("导出备份", () =>
              backupManager.create(options.values().global),
            );
            download(
              "echoes-backup-" +
                backup.createdAt.replaceAll(":", "-") +
                ".json",
              serializeBackup(backup),
            );
          },
          "primary",
        ),
      ),
    );
    const importOptions = fields([
      {
        key: "mode",
        label: "恢复方式",
        type: "select",
        value: "equivalent_chat",
        options: [
          ["equivalent_chat", "相同聊天：恢复消息关联与记忆"],
          ["seed_memories", "新聊天：仅导入记忆种子"],
        ],
      },
      {
        key: "global",
        label: "同时恢复备份中的全局设置",
        type: "checkbox",
        value: false,
      },
    ]);
    page.append(
      section(
        "恢复备份",
        importOptions.node,
        button("选择备份并预检", "file-import", async () => {
          const file = await readFile();
          if (!file) return;
          ctx.guard();
          const v = importOptions.values();
          const backup = await backupManager.parse(await file.text());
          const plan = await backupManager.plan(backup, v.mode, v.global);
          const body = el(
            "div",
            "ew-page-content",
            el(
              "p",
              "warning",
              "恢复将替换目标聊天已有的 Echoes 数据。检索索引需要重新建立。",
            ),
            table(
              ["项目", "影响"],
              [
                ["目标聊天", plan.targetChatId],
                ["替换记忆条目", plan.echoesEntriesToReplace],
                ["状态快照", plan.statusSnapshotsToReplace],
                ["隐藏标记", plan.compressionMarkersToReplace],
                ["全局设置", plan.restoreGlobalSettings ? "替换" : "保留"],
              ],
            ),
            detail("预检详情", plan),
          );
          const d = dialog("恢复预检", body);
          body.append(
            button(
              "创建安全备份并恢复",
              "rotate-left",
              async () => {
                if (!confirm("确认替换以上数据？恢复前将自动导出安全备份。"))
                  return;
                ctx.guard();
                const result = await ctx.run("恢复备份", () =>
                  backupManager.restore(backup, plan, (safety) =>
                    download(
                      "echoes-safety-" + safety.backupId + ".json",
                      serializeBackup(safety),
                    ),
                  ),
                );
                d.close();
                showResult("恢复完成", result.result);
                await ctx.refresh();
              },
              "danger",
            ),
          );
        }),
      ),
    );
    return page;
  }
  if (ctx.route === "maintenance/diagnostics") return diagnosticsView(ctx);
  const status = await api.systemStatus();
  return el(
    "div",
    "ew-page-content",
    section(
      "版本与连接",
      table(
        ["组件", "状态"],
        [
          ["前端版本", ECHOES_BUILD_INFO.appVersion],
          ["服务端版本", status.build.appVersion],
          ["协议兼容", status.protocolCompatible ? "是" : "否"],
          ["Node.js", status.platform.node],
          ["启动状态", status.bootstrap.state],
          ["凭据服务", status.subsystems.credentials],
          ["任务服务", status.subsystems.jobs],
          ["检索服务", status.subsystems.retrieval],
        ],
      ),
    ),
    detail("系统完整状态", status),
    actions(
      button("导出脱敏配置", "download", () =>
        download(
          "echoes-settings-redacted.json",
          JSON.stringify(redactedSettings(), null, 2),
        ),
      ),
      button("诊断与修复", "screwdriver-wrench", () =>
        ctx.navigate("maintenance/diagnostics"),
      ),
    ),
  );
}
function consoleView(ctx: ViewContext): HTMLElement {
  const page = el("div", "ew-page-content");
  const ui = local(ctx, "console-filter", () => ({
    query: "",
    level: "all",
    paused: false,
  }));
  const host = el("div");
  let snapshot = consoleRecords();
  const f = fields(
    [
      {
        key: "level",
        label: "日志级别",
        type: "select",
        value: ui.level,
        options: [
          ["all", "全部"],
          ["error", "Error"],
          ["warn", "Warning"],
          ["info", "Info"],
          ["log", "Log"],
          ["debug", "Debug"],
        ],
      },
    ],
    false,
  );
  const draw = () => {
    if (!ui.paused) snapshot = consoleRecords();
    const items = snapshot.filter(
      (r) =>
        (ui.level === "all" || ui.level === r.level) &&
        r.text.toLowerCase().includes(ui.query.toLowerCase()),
    );
    if (!items.length) {
      host.replaceChildren(empty("本次页面加载后暂无匹配的 Echoes 浏览器日志"));
      return;
    }
    const grid = table(
      ["时间", "级别", "输出"],
      items
        .slice()
        .reverse()
        .map((r) => [
          new Date(r.time).toLocaleTimeString(),
          badge(
            r.level,
            r.level === "error"
              ? "danger"
              : r.level === "warn"
                ? "warning"
                : "",
          ),
          el("pre", "ew-console-text", r.text),
        ]),
    );
    // The shared table rule shrinks the last column for action buttons; log
    // output needs the remaining width instead.
    grid.classList.add("ew-console-table");
    host.replaceChildren(grid);
  };
  f.controls.get("level")!.addEventListener("change", () => {
    ui.level = f.controls.get("level")!.value;
    draw();
  });
  const pause = button(
    ui.paused ? "继续更新" : "暂停更新",
    ui.paused ? "play" : "pause",
    () => {
      ui.paused = !ui.paused;
      pause.querySelector("span")!.textContent = ui.paused
        ? "继续更新"
        : "暂停更新";
      draw();
    },
  );
  page.append(
    el(
      "div",
      "ew-toolbar",
      searchBox(
        ui.query,
        (v) => {
          ui.query = v;
          draw();
        },
        "搜索控制台输出",
        ctx.signal,
      ),
      actions(
        f.node,
        pause,
        button("清空", "trash", clearConsoleRecords),
        button("导出", "download", () =>
          download("echoes-console.json", JSON.stringify(snapshot, null, 2)),
        ),
      ),
    ),
    el(
      "p",
      "ew-muted",
      "范围：本次页面加载后的 Echoes 浏览器日志；不包含服务器终端输出。",
    ),
    host,
  );
  const unsubscribe = subscribeConsole(draw);
  ctx.signal.addEventListener("abort", unsubscribe, { once: true });
  draw();
  return page;
}
async function collectionsView(ctx: ViewContext): Promise<HTMLElement> {
  const collections = await api.listRetrievalCollections();
  const settings = getSettings();
  const groups = settings.retrieval.embeddingGroups;
  const page = el("div", "ew-page-content");
  const chooseGroup = (collection: RetrievalCollectionStats) =>
    groups.filter(
      (g) =>
        g.embeddingSpaceId === collection.collection.embeddingSpaceId &&
        g.dimensions === collection.collection.dimensions,
    );
  const runIndex = (collection: RetrievalCollectionStats, repair: boolean) => {
    const available = chooseGroup(collection);
    if (!available.length)
      throw new Error("没有与此集合空间和维度匹配的向量端点组。");
    const form = fields([
      {
        key: "group",
        label: "向量端点组",
        type: "select",
        options: available.map((g) => [g.id, g.name]),
        value: available[0]!.id,
      },
    ]);
    const d = dialog(repair ? "修复未就绪向量" : "重建全部向量", form.node);
    form.node.append(
      button(
        "开始处理",
        "play",
        async () => {
          const group = available.find((g) => g.id === form.values().group)!;
          if (
            !confirm(
              (repair ? "仅重试未就绪文档" : "重新向量化全部文档") +
                "将调用模型，继续？",
            )
          )
            return;
          const input = {
            collectionIds: [collection.collection.id],
            embeddingGroup: group,
            failoverPolicy: settings.retrieval.failoverPolicy,
            embeddingBatchSize: settings.summary.embeddingBatchSize,
          };
          let result = await ctx.job("处理检索索引", () =>
            api.rebuildRetrievalIndex(input, repair),
          );
          while (
            result.decisionRequired &&
            confirm(
              result.decisionRequired.message +
                "\n切换端点可能重复计费，继续？",
            )
          ) {
            const resumeAfterEndpointId =
              result.decisionRequired.failedEndpointId;
            result = await ctx.job("继续修复索引", () =>
              api.rebuildRetrievalIndex(
                { ...input, resumeAfterEndpointId },
                true,
              ),
            );
          }
          d.close();
          showResult("索引处理结果", result);
          await ctx.refresh();
        },
        "primary",
      ),
    );
  };
  const importInto = (collection: RetrievalCollectionStats) => {
    const options = chooseGroup(collection);
    const form = fields([
      {
        key: "group",
        label: "向量端点组",
        type: "select",
        options: [
          ["", "只导入文本"],
          ...options.map((g) => [g.id, g.name] as [string, string]),
        ],
        value: options[0]?.id ?? "",
      },
      { key: "text", label: "文档文本", type: "textarea", rows: 12 },
    ]);
    const d = dialog("导入文档 · " + collection.collection.name, form.node);
    const upload = async (documents: RetrievalDocumentInput[]) => {
      const v = form.values();
      const embeddingGroup = options.find((g) => g.id === v.group);
      if (!documents.length) throw new Error("没有可导入的文档。");
      if (
        !confirm(
          "导入 " +
            documents.length +
            " 个文档" +
            (embeddingGroup ? "并调用向量模型" : "") +
            "？",
        )
      )
        return;
      const results: RetrievalUpsertResult[] = [];
      for (let offset = 0; offset < documents.length; offset += 100) {
        ctx.guard();
        const batch = documents.slice(offset, offset + 100);
        const input = {
          documents: batch,
          embeddingGroup,
          failoverPolicy: settings.retrieval.failoverPolicy,
          embeddingBatchSize: settings.summary.embeddingBatchSize,
        };
        let result = await ctx.job(
          "导入文档 " +
            (offset + 1) +
            "–" +
            Math.min(documents.length, offset + 100),
          () => api.upsertRetrievalDocuments(input),
        );
        while (
          result.decisionRequired &&
          confirm(
            result.decisionRequired.message + "\n切换端点可能重复计费，继续？",
          )
        ) {
          const resumeAfterEndpointId =
            result.decisionRequired.failedEndpointId;
          result = await ctx.job("继续向量化文档", () =>
            api.upsertRetrievalDocuments({ ...input, resumeAfterEndpointId }),
          );
        }
        results.push(result);
        if (result.failed || result.ambiguous || result.decisionRequired) break;
      }
      d.close();
      showResult("文档导入结果", results);
      await ctx.refresh();
    };
    form.node.append(
      actions(
        button(
          "导入文本",
          "file-import",
          () => {
            const text = form.values().text.trim();
            if (!text) throw new Error("请填写文档文本。");
            return upload([
              {
                collectionId: collection.collection.id,
                sourceType: "manual",
                sourceId: id("source"),
                text,
                tags: [],
                metadata: {},
              },
            ]);
          },
          "primary",
        ),
        button("导入 JSONL 文件", "upload", async () => {
          const file = await readFile(".jsonl,.ndjson");
          if (!file) return;
          if (file.size > 20 * 1024 * 1024)
            throw new Error("单次导入文件不能超过 20 MB。");
          const lines = (await file.text())
            .split(/\r?\n/)
            .filter((l) => l.trim());
          const documents = lines.map((line, i) => {
            try {
              const v = JSON.parse(line);
              return retrievalDocumentInputSchema.parse({
                ...v,
                collectionId: collection.collection.id,
                sourceType: v.sourceType ?? "imported",
                sourceId: v.sourceId ?? id("source"),
                tags: v.tags ?? [],
                metadata: v.metadata ?? {},
              });
            } catch (error) {
              throw new Error("第 " + (i + 1) + " 行无效：" + String(error));
            }
          });
          await upload(documents);
        }),
      ),
    );
  };
  page.append(
    actions(
      button(
        "新建集合",
        "plus",
        () => {
          if (!groups.length) throw new Error("请先配置向量端点组。");
          editDialog(
            "新建检索集合",
            [
              { key: "name", label: "名称", required: true },
              { key: "description", label: "说明" },
              {
                key: "group",
                label: "向量空间",
                type: "select",
                options: groups.map((g) => [
                  g.id,
                  g.name + " · " + g.dimensions + " 维",
                ]),
              },
            ],
            async (v) => {
              const g = groups.find((g) => g.id === v.group)!;
              await api.createRetrievalCollection({
                id: id("collection"),
                name: v.name,
                description: v.description,
                embeddingSpaceId: g.embeddingSpaceId,
                dimensions: g.dimensions,
              });
              await ctx.refresh();
            },
          );
        },
        "primary",
      ),
    ),
    collections.length
      ? table(
          ["集合", "文档", "就绪", "待处理", "失败 / 待确认", "维度", "操作"],
          collections.map((c) => [
            el(
              "div",
              "",
              el("strong", "", c.collection.name),
              el("p", "ew-muted", c.collection.id),
            ),
            c.documents,
            c.ready,
            c.pending,
            actions(
              badge(String(c.failed), c.failed ? "danger" : ""),
              badge(String(c.ambiguous), c.ambiguous ? "warning" : ""),
            ),
            c.dimensions,
            actions(
              tool("导入文档", "file-import", () => importInto(c)),
              tool("修复未就绪向量", "screwdriver-wrench", () =>
                runIndex(c, true),
              ),
              tool("重建全部向量", "rotate", () => runIndex(c, false)),
              tool("集合详情", "circle-info", () =>
                showResult(c.collection.name, c),
              ),
              tool(
                "删除集合",
                "trash",
                async () => {
                  if (
                    !confirm(
                      "删除集合 " +
                        c.collection.name +
                        " 及其中全部检索文档？总结原文不会删除。",
                    )
                  )
                    return;
                  await ctx.job("删除检索集合", () =>
                    api.deleteRetrievalCollection(c.collection.id),
                  );
                  await ctx.refresh();
                },
                "danger",
              ),
            ),
          ]),
        )
      : empty("暂无检索集合"),
  );
  return page;
}
async function queryView(ctx: ViewContext): Promise<HTMLElement> {
  const collections = await api.listRetrievalCollections();
  const s = getSettings();
  const r = s.retrieval.recall;
  const chosen = new Set<string>();
  const page = el("div", "ew-page-content");
  const f = fields([
    {
      key: "query",
      label: "查询文本",
      type: "textarea",
      required: true,
      rows: 4,
    },
    {
      key: "embedding",
      label: "向量端点组",
      type: "select",
      options: [
        ["", "不选择"],
        ...s.retrieval.embeddingGroups.map(
          (g) => [g.id, g.name] as [string, string],
        ),
      ],
    },
    {
      key: "rerank",
      label: "重排序端点组",
      type: "select",
      options: [
        ["", "不选择"],
        ...s.retrieval.rerankSets.map(
          (g) => [g.id, g.name] as [string, string],
        ),
      ],
    },
    { key: "vector", label: "向量检索", type: "checkbox", value: false },
    { key: "bm25", label: "BM25 检索", type: "checkbox", value: true },
    {
      key: "topK",
      label: "最终结果数",
      type: "number",
      value: r.finalTopK,
      min: 1,
      max: 100,
    },
  ]);
  const resultHost = el("div");
  page.append(
    section(
      "目标集合",
      el(
        "div",
        "ew-list",
        ...collections.map((c) =>
          el(
            "label",
            "ew-toggle",
            check(c.collection.name, false, (v) =>
              v ? chosen.add(c.collection.id) : chosen.delete(c.collection.id),
            ),
            c.collection.name + " · " + c.documents + " 条",
          ),
        ),
      ),
    ),
    f.node,
    button(
      "执行检索",
      "magnifying-glass",
      async () => {
        const v = f.values();
        if (!chosen.size) throw new Error("至少选择一个集合。");
        if (!v.vector && !v.bm25) throw new Error("至少启用一种检索方式。");
        const embeddingGroup = s.retrieval.embeddingGroups.find(
          (g) => g.id === v.embedding,
        );
        const rerankSet = s.retrieval.rerankSets.find((g) => g.id === v.rerank);
        if (v.vector && !embeddingGroup) throw new Error("请选择向量端点组。");
        const compatible = collections
          .filter(
            (c) =>
              chosen.has(c.collection.id) &&
              c.collection.embeddingSpaceId ===
                embeddingGroup?.embeddingSpaceId &&
              c.dimensions === embeddingGroup?.dimensions,
          )
          .map((c) => c.collection.id);
        if (v.vector && compatible.length !== chosen.size)
          throw new Error("选中集合与向量端点组的空间或维度不一致。");
        let result = await ctx.job("检索实验", () =>
          api.queryRetrieval({
            collectionIds: [...chosen],
            query: v.query,
            vectorEnabled: v.vector,
            bm25Enabled: v.bm25,
            rerankEnabled: !!rerankSet,
            vectorTopK: r.vectorTopK,
            bm25TopK: r.bm25TopK,
            rerankTopK: r.rerankTopK,
            finalTopK: v.topK,
            failoverPolicy: s.retrieval.failoverPolicy,
            embeddingGroup,
            rerankSet,
          }),
        );
        while (
          result.decisionRequired &&
          result.continuation &&
          confirm(
            result.decisionRequired.message +
              "\n继续可能调用其他端点，是否继续？",
          )
        ) {
          const token = result.continuation.token;
          result = await ctx.job("继续检索", () =>
            api.continueRetrievalQuery({
              token,
              failoverPolicy: s.retrieval.failoverPolicy,
              embeddingGroup,
              rerankSet,
            }),
          );
        }
        if (ctx.signal.aborted) return;
        resultHost.replaceChildren(
          detail("检索分支与错误", result.branches),
          result.hits.length
            ? table(
                ["排名", "内容与来源"],
                result.hits.map((h, i) => [
                  i + 1,
                  detail("命中 " + (i + 1), h),
                ]),
              )
            : empty("没有命中结果"),
        );
      },
      "primary",
    ),
    resultHost,
  );
  return page;
}
async function diagnosticsView(ctx: ViewContext): Promise<HTMLElement> {
  const page = el("div", "ew-page-content");
  const host = el("div");
  let checks: DiagnosticCheck[] = [];
  const selected = new Set<RepairKind>();
  const run = async () => {
    ctx.guard();
    const inspected = await inspectWorldbookDiagnostics();
    ctx.guard();
    const helper = window.TavernHelper;
    const settings = getSettings();
    const endpoints = [
      ...settings.generationGroups.flatMap((g) => g.endpoints),
      ...settings.retrieval.embeddingGroups.flatMap((g) => g.endpoints),
      ...settings.retrieval.rerankSets.flatMap((g) => g.endpoints),
    ];
    const result = await ctx.job("运行系统诊断", () =>
      api.startDiagnostics({
        clientProtocol: ECHOES_BUILD_INFO.apiProtocolVersion,
        clientVersion: ECHOES_BUILD_INFO.appVersion,
        settingsFormatVersion: storedSettingsFormatVersion(),
        worldbook: inspected.worldbook,
        tavernHelper: Object.fromEntries(
          [
            "getWorldbook",
            "updateWorldbookWith",
            "getChatMessages",
            "setChatMessages",
          ].map((k) => [k, typeof (helper as any)?.[k] === "function"]),
        ),
        credentialIds: [
          ...new Set(
            endpoints.flatMap((e) => (e.credentialId ? [e.credentialId] : [])),
          ),
        ],
      }),
    );
    checks = result.checks;
    selected.clear();
    host.replaceChildren(
      ...inspected.errors.map((message) => el("p", "warning", message)),
      table(
        ["选择", "检查项", "状态", "详情"],
        checks.map((c) => [
          c.repairKind
            ? check("修复 " + c.title, false, (v) =>
                v
                  ? selected.add(c.repairKind!)
                  : selected.delete(c.repairKind!),
              )
            : "",
          c.title,
          stateBadge(c.state),
          el(
            "div",
            "",
            el("p", "", c.message),
            c.details ? detail("诊断详情", c.details) : null,
          ),
        ]),
      ),
      button("导出诊断报告", "download", () =>
        download(
          "echoes-diagnostics.json",
          JSON.stringify(redactLog(result), null, 2),
        ),
      ),
    );
  };
  page.append(
    actions(
      button("运行诊断", "stethoscope", run, "primary"),
      button("修复选中问题", "screwdriver-wrench", async () => {
        if (!selected.size) throw new Error("请先运行诊断并选择修复项。");
        if (
          !confirm(
            "执行 " + [...selected].join("、") + "？建议先在备份页面导出备份。",
          )
        )
          return;
        ctx.guard();
        const frontend = new Set([
          "settings_format",
          "summary_format",
          "temporary_injections",
          "retrieval_index",
        ]);
        if (selected.has("settings_format")) saveSettings(getSettings());
        if (selected.has("summary_format")) await ctx.summary.checkIntegrity();
        if (selected.has("retrieval_index")) {
          await ctx.run("修复总结索引", () => ctx.summary.repairIndex(), () => ctx.summary.stop());
          const verified = await inspectWorldbookDiagnostics();
          if (verified.worldbook.summaryIndexMismatches !== 0) {
            await run();
            throw new Error(verified.errors.join("；") || "总结索引仍有不一致项，请查看任务日志中的失败原因。");
          }
        }
        if (selected.has("temporary_injections")) {
          await recallCoordinator.clear();
          await statusCoordinator.clearInjection();
        }
        const backend = [...selected].filter((k) => !frontend.has(k));
        if (backend.length)
          showResult(
            "修复结果",
            await ctx.job("系统修复", () =>
              api.startRepair({ kinds: backend, confirmed: true }),
            ),
          );
        await run();
      }),
    ),
    host,
  );
  return page;
}
