import type {
  ChatMessageInput,
  ExtractionRequest,
  MemoryRow,
  MemoryTypeDefinition,
  PromptMessageInput,
  PromptRole,
  StructuredExtractionBatch,
  StructuredExtractionMode,
} from "../../shared/domain";
import {
  structuredExtractionContextHash,
  structuredExtractionMessageHash,
} from "../../shared/extraction-core";
import type { EchoesSettings } from "../state/settings";
import { EXTRACTION_ROW_REFERENCE_GUIDE, extractionRuntimeInput } from "../../shared/extraction-references";
import type { WorldbookMemoryState } from "../worldbook/worldbook-memory";
import { indexedChatMessages, messageRangeByFloor } from "../chat-message-index";
import { extractionBackground } from "../worldbook/context-background";

export interface ResolvedPromptBlock {
  id: string;
  title: string;
  role: PromptRole;
  content: string;
}

export interface PreparedExtraction {
  request: ExtractionRequest;
  batch: StructuredExtractionBatch;
  lastMessageId: string;
  promptBlocks: ResolvedPromptBlock[];
  runtimePreview: string;
  expectedCheckpoint: string | null;
}

export interface ExtractionBatchSelection {
  batch: StructuredExtractionBatch;
  messages: ChatMessageInput[];
  expectedCheckpoint: string | null;
}

export class ExtractionCheckpointMissingError extends Error {
  readonly code = "EXTRACTION_CHECKPOINT_MISSING";

  constructor(readonly checkpoint: string) {
    super(`结构化记忆检查点消息 ${checkpoint} 已不存在，自动提取已暂停。`);
    this.name = "ExtractionCheckpointMissingError";
  }
}

export class ExtractionBatchUnavailableError extends Error {
  readonly code = "EXTRACTION_BATCH_UNAVAILABLE";

  constructor(
    readonly mode: StructuredExtractionMode,
    message: string,
  ) {
    super(message);
    this.name = "ExtractionBatchUnavailableError";
  }
}

export function currentExtractionMessages(): ChatMessageInput[] {
  return indexedChatMessages().map((entry) => entry.message);
}

export interface ExtractionCleaningOptions {
  startFloor: number;
  endFloor: number;
  instructions: string;
}

export async function prepareCleaningExtraction(
  state: WorldbookMemoryState,
  settings: EchoesSettings,
  options: ExtractionCleaningOptions,
): Promise<PreparedExtraction> {
  if (options.instructions.length > 20_000) throw new Error("补充要求最多 20000 字符。");
  const { messages } = messageRangeByFloor(options.startFloor, options.endFloor);
  const selection = await buildSelection(state, "cleaning", messages);
  const prepared = prepareSelectedExtraction(state, settings, selection);
  prepared.request.promptMessages = [...await extractionBackground(selection.messages, state.worldbookName), ...prepared.request.promptMessages];
  prepared.request.additionalInstructions = options.instructions.trim();
  return prepared;
}

function checkpointStart(
  state: WorldbookMemoryState,
  messages: ChatMessageInput[],
): number {
  const checkpoint = state.catalog.lastProcessedMessageId;
  if (!checkpoint) return 0;
  const index = messages.findIndex((message) => message.id === checkpoint);
  if (index < 0) throw new ExtractionCheckpointMissingError(checkpoint);
  return index + 1;
}

export function extractionPendingMessageCount(
  state: WorldbookMemoryState,
  messages = currentExtractionMessages(),
): number {
  return Math.max(0, messages.length - checkpointStart(state, messages));
}

export function incrementalMessages(
  state: WorldbookMemoryState,
  limit: number,
): ChatMessageInput[] {
  const messages = currentExtractionMessages();
  const start = checkpointStart(state, messages);
  return messages.slice(start, start + Math.max(2, Math.min(500, Math.floor(limit))));
}

function extractionContext(state: WorldbookMemoryState): {
  types: MemoryTypeDefinition[];
  rows: MemoryRow[];
} {
  const types = state.catalog.types.filter((type) => type.enabled);
  const typeIds = new Set(types.map((type) => type.id));
  return {
    types,
    rows: state.rows.filter((row) => typeIds.has(row.typeId)),
  };
}

async function buildSelection(
  state: WorldbookMemoryState,
  mode: StructuredExtractionMode,
  messages: ChatMessageInput[],
): Promise<ExtractionBatchSelection> {
  const { types, rows } = extractionContext(state);
  const sourceHash = await structuredExtractionMessageHash(messages);
  const contextHash = await structuredExtractionContextHash(types, rows);
  const batch: StructuredExtractionBatch = {
    id: `extraction_${sourceHash.slice(0, 48)}`,
    mode,
    startMessageId: messages[0]!.id,
    endMessageId: messages.at(-1)!.id,
    messageIds: messages.map((message) => message.id),
    sourceHash,
    contextHash,
  };
  return {
    batch,
    messages,
    expectedCheckpoint: state.catalog.lastProcessedMessageId ?? null,
  };
}

export async function automaticExtractionBatch(
  state: WorldbookMemoryState,
  limit: number,
  messages = currentExtractionMessages(),
): Promise<ExtractionBatchSelection | null> {
  const start = checkpointStart(state, messages);
  const threshold = Math.max(2, Math.min(500, Math.floor(limit)));
  if (messages.length - start < threshold) return null;
  const boundary = Math.min(messages.length - 1, start + threshold - 1);
  let end = -1;
  for (let index = boundary; index >= start; index -= 1) {
    if (messages[index]?.role !== "assistant") continue;
    if (!messages.slice(index + 1).some((message) => message.role === "user")) continue;
    end = index;
    break;
  }
  if (end < start) return null;
  return buildSelection(state, "auto", messages.slice(start, end + 1));
}

export async function manualExtractionBatch(
  state: WorldbookMemoryState,
  limit: number,
  messages = currentExtractionMessages(),
): Promise<ExtractionBatchSelection | null> {
  const start = checkpointStart(state, messages);
  const maximum = Math.max(2, Math.min(500, Math.floor(limit)));
  const window = messages.slice(start, start + maximum);
  let end = -1;
  for (let index = window.length - 1; index >= 0; index -= 1) {
    if (window[index]?.role === "user") {
      end = index;
      break;
    }
  }
  if (end < 0) return null;
  return buildSelection(state, "manual", window.slice(0, end + 1));
}

export function resolvePromptBlocks(
  state: WorldbookMemoryState,
): ResolvedPromptBlock[] {
  const typeById = new Map(state.catalog.types.map((type) => [type.id, type]));
  return state.catalog.promptPreset.items.flatMap((item) => {
    if (!item.enabled) return [];
    if (item.kind === "type_writer") {
      const type = typeById.get(item.typeId);
      if (!type?.enabled) return [];
      return [{
        id: item.id,
        title: item.title,
        role: item.role,
        content: type.writePrompt,
      }];
    }
    if (!item.content.trim()) return [];
    return [{
      id: item.id,
      title: item.title,
      role: item.role,
      content: item.content,
    }];
  });
}

export function prepareSelectedExtraction(
  state: WorldbookMemoryState,
  settings: EchoesSettings,
  selection: ExtractionBatchSelection,
  resumeAfterEndpointId?: string,
): PreparedExtraction {
  const { types, rows } = extractionContext(state);
  if (types.length === 0) throw new Error("当前对话没有激活的记忆类型。");
  const promptBlocks = resolvePromptBlocks(state);
  const promptMessages: PromptMessageInput[] = promptBlocks.map(({ role, content }) => ({ role, content }));
  const workflow = settings.generationWorkflows.extraction;
  const generationGroup = settings.generationGroups.find((group) => group.id === workflow.groupId);
  if (!generationGroup) throw new Error("请先为结构化记忆配置生成端点组。");
  const runtimePreview = JSON.stringify({
    batch: selection.batch,
    rowReferenceGuide: EXTRACTION_ROW_REFERENCE_GUIDE,
    ...extractionRuntimeInput({ types, rows, messages: selection.messages, contextPolicy: settings.extractionContext }),
  }, null, 2);
  return {
    request: {
      extractAttributes: settings.continuity?.extractAttributes ?? false,
      ...(settings.extractionContext ? { contextPolicy: settings.extractionContext } : {}),
      chatId: state.catalog.chatId,
      batch: selection.batch,
      types,
      rows,
      promptMessages,
      messages: selection.messages,
      generationGroup,
      failoverPolicy: workflow.failoverPolicy,
      ...(resumeAfterEndpointId ? { resumeAfterEndpointId } : {}),
    },
    batch: selection.batch,
    lastMessageId: selection.batch.endMessageId,
    promptBlocks,
    runtimePreview,
    expectedCheckpoint: selection.expectedCheckpoint,
  };
}

export async function prepareExtraction(
  state: WorldbookMemoryState,
  settings: EchoesSettings,
  mode: StructuredExtractionMode = "manual",
  resumeAfterEndpointId?: string,
): Promise<PreparedExtraction> {
  const selection = mode === "auto"
    ? await automaticExtractionBatch(state, settings.extractionMessageCount)
    : await manualExtractionBatch(state, settings.extractionMessageCount);
  if (!selection) {
    throw new ExtractionBatchUnavailableError(
      mode,
      mode === "auto"
        ? "尚未达到自动提取阈值或没有已确认的助手回复。"
        : "下一批中没有可提交的用户消息。",
    );
  }
  const prepared = prepareSelectedExtraction(state, settings, selection, resumeAfterEndpointId);
  prepared.request.promptMessages = [...await extractionBackground(selection.messages, state.worldbookName), ...prepared.request.promptMessages];
  return prepared;
}
