import type { MemoryRow, MemoryTypeDefinition } from "../../shared/domain";
import { continuityExtractionSettings, editContinuity, memoryHistoryView, memoryLinksView } from "./continuity";
import { WorldbookMemoryStore } from "../worldbook/worldbook-memory";
import { checkpointFloor } from "../chat-message-index";
import { extractionProviderMessages } from "../../shared/extraction-references";
import {
  getSettings,
  saveSettings,
  saveTypeTemplate,
  deleteTypeTemplate,
  instantiateType,
} from "../state/settings";
import { extractionCoordinator as extraction } from "../memory/extraction-coordinator";
import {
  prepareExtraction,
  currentExtractionMessages,
} from "../memory/extraction-request";
import {
  el,
  actions,
  button,
  tool,
  table,
  fields,
  saveForm,
  section,
  empty,
  detail,
  badge,
  stateBadge,
  check,
  searchBox,
  editDialog,
  dialog,
  local,
  now,
  type ViewContext,
  type Field,
} from "./core";
import {
  typeEditor,
  orderedEditor,
  promptEditor,
  promptDescription,
} from "./editors";

const store = new WorldbookMemoryStore();
export async function memoryView(ctx: ViewContext): Promise<HTMLElement> {
  const state = await store.load();
  if (ctx.signal.aborted) return el("div");
  if (ctx.route === "memory/links") return memoryLinksView(ctx, state);
  if (ctx.route === "memory/history") return memoryHistoryView(ctx, state);
  const page = el("div", "ew-page-content");
  const saveType = (type: MemoryTypeDefinition) =>
    typeEditor(type, async (v) => {
      ctx.guard();
      await store.saveType(
        { ...v, templateId: type.templateId, enabled: type.enabled },
        type.id,
      );
      await ctx.refresh();
    });
  const addType = () =>
    editDialog(
      "新建记忆表",
      [
        {
          key: "template",
          label: "基于模板",
          type: "select",
          options: getSettings().typeTemplates.map((t) => [t.id, t.name]),
        },
        { key: "name", label: "表名称", required: true },
      ],
      async (v) => {
        ctx.guard();
        const template = getSettings().typeTemplates.find(
          (t) => t.id === v.template,
        )!;
        const type = instantiateType(template, v.name);
        await store.saveType(type);
        await ctx.refresh();
      },
    );
  if (ctx.route === "memory/templates") {
    page.append(
      actions(
        button("新建模板", "plus", () =>
          typeEditor(
            {
              name: "",
              description: "",
              columns: [
                {
                  id: "content",
                  name: "内容",
                  type: "long_text",
                  required: true,
                },
              ],
              writePrompt:
                "Write reusable, source-supported information in Chinese according to this table's columns.",
            },
            async (v) => {
              saveTypeTemplate(v);
              await ctx.refresh();
            },
            "新建类型模板",
          ),
        ),
      ),
      table(
        ["模板", "用途", "字段数", "来源", "操作"],
        getSettings().typeTemplates.map((t) => [
          t.name,
          t.description,
          t.columns.length,
          t.builtIn ? "内置" : "自定义",
          actions(
            tool("编辑副本", "copy", () =>
              typeEditor(
                { ...t, name: t.name + " 副本" },
                async (v) => {
                  saveTypeTemplate(v);
                  await ctx.refresh();
                },
                "复制模板",
              ),
            ),
            ...(!t.builtIn
              ? [
                  tool("编辑模板", "pen", () =>
                    typeEditor(t, async (v) => {
                      saveTypeTemplate({ ...v, id: t.id }, t);
                      await ctx.refresh();
                    }),
                  ),
                  tool(
                    "删除模板",
                    "trash",
                    async () => {
                      if (confirm("删除模板 " + t.name + "？")) {
                        deleteTypeTemplate(t.id);
                        await ctx.refresh();
                      }
                    },
                    "danger",
                  ),
                ]
              : []),
          ),
        ]),
      ),
    );
    return page;
  }
  if (ctx.route === "memory/schema") {
    page.append(
      actions(
        button("新建表", "plus", addType, "primary"),
        button("从其他聊天迁移", "file-import", async () => {
          const choose = fields([
            {
              key: "source",
              label: "来源世界书",
              type: "select",
              required: true,
              options: store
                .listWorldbooks()
                .filter((x) => x !== state.worldbookName)
                .map((x) => [x, x]),
            },
            {
              key: "policy",
              label: "已有同 ID 类型",
              type: "select",
              options: [
                ["copy", "创建副本"],
                ["skip", "跳过"],
                ["overwrite", "覆盖"],
              ],
            },
          ]);
          let source: Awaited<ReturnType<typeof store.inspect>> | undefined;
          let loadedName = "";
          let request = 0;
          const chosen = new Set<string>();
          const host = el("div", "ew-list");
          const draw = () =>
            host.replaceChildren(
              ...(source?.catalog.types ?? []).map((t) =>
                el(
                  "label",
                  "ew-toggle",
                  check(t.name, chosen.has(t.id), (v) =>
                    v ? chosen.add(t.id) : chosen.delete(t.id),
                  ),
                  t.name,
                ),
              ),
            );
          const modal = dialog(
            "迁移记忆类型",
            el("div", "ew-page-content", choose.node, host),
            async () => {
              ctx.guard();
              const v = choose.values();
              if (loadedName !== v.source) throw new Error("请等待来源世界书读取完成。");
              if (!chosen.size) throw new Error("至少选择一个类型。");
              if (
                v.policy === "overwrite" &&
                !confirm("覆盖会替换目标表已有记录，继续？")
              )
                return;
              await store.migrateFrom(v.source, [...chosen], v.policy);
              await ctx.refresh();
            },
          );
          const submit = modal.querySelector<HTMLButtonElement>("footer button.primary")!;
          const loadSource = async () => {
            const sequence = ++request;
            const name = choose.controls.get("source")!.value;
            loadedName = "";
            chosen.clear();
            submit.disabled = true;
            host.replaceChildren(empty(name ? "正在读取来源世界书…" : "没有可迁移的其他世界书"));
            if (!name) return;
            try {
              const result = await store.inspect(name);
              if (sequence !== request || !modal.isConnected || ctx.signal.aborted) return;
              source = result;
              loadedName = name;
              result.catalog.types.forEach((t) => chosen.add(t.id));
              draw();
              submit.disabled = result.catalog.types.length === 0;
            } catch (error) {
              if (sequence !== request || !modal.isConnected) return;
              host.replaceChildren(empty(error instanceof Error ? error.message : String(error)));
            }
          };
          choose.controls.get("source")!.addEventListener("change", () => void loadSource());
          void loadSource();
        }),
      ),
      table(
        ["表名称", "用途", "字段", "启用", "操作"],
        state.catalog.types.map((t) => [
          t.name,
          t.description,
          t.columns.length,
          check("启用 " + t.name, t.enabled, async (v) => {
            ctx.guard();
            await store.setTypeEnabled(t.id, v);
            await ctx.refresh();
          }),
          actions(
            tool("编辑表结构", "table-columns", () => saveType(t)),
            tool(
              "删除表及记录",
              "trash",
              async () => {
                if (confirm("删除 " + t.name + " 及其中所有记录？")) {
                  ctx.guard();
                  await store.deleteType(t.id);
                  await ctx.refresh();
                }
              },
              "danger",
            ),
          ),
        ]),
      ),
    );
    return page;
  }
  if (ctx.route === "memory/prompts") {
    page.append(
      orderedEditor(
        ctx,
        "提示词",
        state.catalog.promptPreset.items,
        promptDescription,
        promptEditor("structured", state.catalog.types),
        async (items) => {
          ctx.guard();
          await store.savePromptPreset({
            ...state.catalog.promptPreset,
            items,
            updatedAt: now(),
          });
        },
      ),
      button("预览最终请求", "eye", async () => {
        const prepared = await prepareExtraction(
          await store.load(),
          getSettings(),
          "manual",
        );
        dialog(
          "结构化提取请求",
          detail("完整请求消息", extractionProviderMessages(prepared.request)),
        );
      }),
    );
    return page;
  }
  if (ctx.route === "memory/rules") {
    const settings = getSettings();
    const form = fields([
      {
        key: "count",
        label: "单批消息数量",
        type: "number",
        min: 2,
        max: 500,
        value: settings.extractionMessageCount,
      },
      {
        key: "enabled",
        label: "自动提取",
        type: "checkbox",
        value: state.catalog.automation.enabled,
      },
    ]);
    page.append(
      saveForm(form, async (v) => {
        ctx.guard();
        const s = getSettings();
        s.extractionMessageCount = v.count;
        saveSettings(s);
        await extraction.setAutomationEnabled(v.enabled);
      }),
    );
    const policy = settings.extractionContext ?? { enabled: true, maxRows: 40, maxCharacters: 60000, relatedRows: 8 };
    const contextForm = fields([
      { key: "enabled", label: "按需提供写表详情", type: "checkbox", value: policy.enabled },
      { key: "maxRows", label: "最多完整条目数", type: "number", min: 1, max: 1000, value: policy.maxRows, required: true },
      { key: "maxCharacters", label: "完整条目字符预算", type: "number", min: 2000, max: 500000, value: policy.maxCharacters, required: true },
      { key: "relatedRows", label: "最多直接关联条目数", type: "number", min: 0, max: 100, value: policy.relatedRows, required: true },
    ]);
    page.append(section("写表上下文", saveForm(contextForm, (values) => {
      const s = getSettings();
      s.extractionContext = { enabled: values.enabled, maxRows: values.maxRows, maxCharacters: values.maxCharacters, relatedRows: values.relatedRows };
      saveSettings(s);
    }), badge("全局名称目录、世界书背景与完整版本校验保留")));
    page.append(continuityExtractionSettings(ctx));
    return page;
  }
  if (ctx.route === "memory/tasks") {
    const trace = extraction.trace();
    page.append(
      actions(
        button(
          "处理下一批",
          "play",
          () =>
            ctx
              .run(
                "结构化记忆提取",
                () => extraction.runManual(),
                () => extraction.stopCurrent(),
              )
              .then(() => ctx.refresh()),
          "primary",
        ),
        button("停止提取", "stop", () => extraction.stopCurrent(), "danger"),
        button("重试", "rotate", () =>
          ctx
            .run(
              "重试结构化提取",
              () => extraction.retryCurrent(),
              () => extraction.stopCurrent(),
            )
            .then(() => ctx.refresh()),
        ),
      ),
      section(
        "处理进度",
        el(
          "p",
          "",
          extraction.isRunning()
            ? "正在提取"
            : (extraction.pauseReason() ?? "等待处理"),
        ),
        el(
          "p",
          "ew-muted",
          "检查点：" + (state.catalog.lastProcessedMessageId
            ? checkpointFloor(state.catalog.lastProcessedMessageId) < 0 ? "原消息已不存在" : `第 ${checkpointFloor(state.catalog.lastProcessedMessageId)} 楼`
            : "尚未处理"),
        ),
        trace ? detail("最近一次提取", trace) : empty("暂无提取任务"),
      ),
      section(
        "检查点",
        actions(
          button("修改检查点", "pen", () => editDialog("修改结构化记忆检查点", [
            { key: "floor", label: "已处理至楼层（-1：尚未处理）", type: "number", min: -1,
              max: SillyTavern.getContext().chat.length - 1, required: true,
              value: checkpointFloor(state.catalog.lastProcessedMessageId) },
          ], async (v) => {
            ctx.guard();
            if (!confirm("修改检查点会关闭自动提取，保留已有记忆并清除待审核结果。下一次从所选楼层之后开始，继续？")) return;
            await extraction.relocateCheckpointToFloor(v.floor);
            await ctx.refresh();
          })),
          button("移至最新消息", "forward", async () => {
            if (confirm("关闭自动提取并跳过尚未处理的消息，将检查点移到最新？已有记忆保留。")) {
              ctx.guard();
              await extraction.relocateCheckpoint(
                currentExtractionMessages().at(-1)?.id ?? null,
              );
              await ctx.refresh();
            }
          }),
          button("从头开始", "rotate-left", async () => {
            if (
              confirm("关闭自动提取并清除检查点，下次将从开头重新提取，已有记忆不会删除。继续？")
            ) {
              ctx.guard();
              await extraction.relocateCheckpoint(null);
              await ctx.refresh();
            }
          }),
        ),
      ),
    );
    return page;
  }
  if (ctx.route === "memory/cleaning") {
    const draft = local(ctx, "extraction-cleaning", () => ({ start: 0,
      end: Math.max(0, SillyTavern.getContext().chat.length - 1), instructions: "" }));
    const form = fields([
      { key: "start", label: "起始楼层", type: "number", min: 0,
        max: SillyTavern.getContext().chat.length - 1, value: draft.start, required: true },
      { key: "end", label: "结束楼层", type: "number", min: 0,
        max: SillyTavern.getContext().chat.length - 1, value: draft.end, required: true },
      { key: "instructions", label: "补充要求", type: "textarea", rows: 8, value: draft.instructions },
    ], false);
    const options = () => {
      const values = form.values();
      Object.assign(draft, values);
      return { startFloor: values.start, endFloor: values.end, instructions: values.instructions };
    };
    form.node.addEventListener("input", () => {
      draft.instructions = form.controls.get("instructions")!.value;
      for (const key of ["start", "end"] as const) {
        const value = form.controls.get(key)!.value;
        if (value !== "" && Number.isFinite(Number(value))) draft[key] = Number(value);
      }
    });
    page.append(form.node, actions(
      button("预览清洗请求", "eye", async () => {
        ctx.guard();
        const prepared = await extraction.previewCleaning(options());
        ctx.guard();
        dialog("记忆清洗请求", detail("最终提示词与所选消息", extractionProviderMessages(prepared.request)));
      }),
      button("开始清洗", "play", async () => {
        ctx.guard();
        await ctx.run("结构化记忆清洗", () => extraction.runCleaning(options()), () => extraction.stopCurrent());
        await ctx.refresh();
      }, "primary"),
      button("停止清洗", "stop", () => extraction.stopCurrent(), "danger"),
      button("查看审核结果", "check", () => ctx.navigate("memory/review")),
    ));
    const trace = extraction.trace();
    if (trace) page.append(detail("最近一次任务", trace));
    return page;
  }
  if (ctx.route === "memory/review") {
    const review = extraction.review();
    if (!review) return empty("没有待审核操作");
    const selected = new Set(review.selectedIndexes);
    const rows = review.result.reviewItems.map((item) => {
      const op = item.operation as any;
      const valid = item.state === "valid";
      const c = check(
        "选择操作 " + (item.index + 1),
        selected.has(item.index),
        (v) => (v ? selected.add(item.index) : selected.delete(item.index)),
      );
      c.disabled = !valid;
      const previous =
        valid && op.rowId
          ? state.rows.find((r) => r.id === op.rowId)
          : undefined;
      return [
        c,
        item.index + 1,
        valid ? String(op.action) : badge("无效操作", "danger"),
        valid
          ? (op.dataName ?? previous?.dataName ?? op.rowId ?? "")
          : item.reason,
        button("查看变更", "code-compare", () =>
          dialog(
            "操作 " + (item.index + 1),
            el(
              "div",
              "ew-page-content",
              item.reason ? el("p", "danger", item.reason) : null,
              previous ? detail("修改前", previous) : null,
              detail("提议内容", item.operation),
            ),
          ),
        ),
      ];
    });
    page.append(
      actions(
        badge(
          "有效操作 " +
            review.result.reviewItems.filter((i) => i.state === "valid").length,
        ),
        button(
          "提交选中操作",
          "check",
          async () => {
            ctx.guard();
            await extraction.submitReview([...selected]);
            await ctx.refresh();
          },
          "primary",
        ),
      ),
      table(["选择", "序号", "操作", "对象 / 原因", "详情"], rows),
    );
    return page;
  }
  const ui = local(ctx, "memory-filter", () => ({
    typeId: state.catalog.types[0]?.id ?? "",
    query: "",
    status: "all",
    page: 0,
    selected: new Set<string>(),
  }));
  if (!(ui.selected instanceof Set)) ui.selected = new Set<string>();
  if (!state.catalog.types.some((t) => t.id === ui.typeId))
    ui.typeId = state.catalog.types[0]?.id ?? "";
  const selectedRows = () =>
    state.rows.filter((row) => row.typeId === ui.typeId && ui.selected.has(row.id));
  const selectionBar = el("div", "ew-selection");
  const drawSelection = () => {
    const selected = selectedRows();
    selectionBar.hidden = selected.length === 0;
    if (!selected.length) {
      selectionBar.replaceChildren();
      return;
    }
    selectionBar.replaceChildren(
      el("strong", "", `已选 ${selected.length} 条`),
      actions(
        button(
          "删除选中条目",
          "trash",
          async () => {
            ctx.guard();
            const targets = selectedRows();
            if (!targets.length) return;
            if (!confirm(`删除选中的 ${targets.length} 条结构化记忆？条目会从世界书移除，仍可在“历史变化”中查看修改记录；指向这些条目的记忆关联会显示为已删除。`)) return;
            await ctx.run("批量删除结构化记忆", () => store.deleteRows(targets.map((row) => row.id)));
            ui.selected.clear();
            await ctx.refresh();
          },
          "danger",
        ),
        tool("取消选择", "xmark", () => {
          ui.selected.clear();
          draw();
        }),
      ),
    );
  };
  const nav = el("aside", "ew-list");
  const host = el("div", "ew-page-content");
  const split = el("div", "ew-split ew-memory-split", nav, host);
  const select = document.createElement("select");
  select.setAttribute("aria-label", "激活方式筛选");
  [
    ["all", "全部激活方式"],
    ["permanent", "常驻"],
    ["keyword", "关键词"],
    ["vectorized", "向量"],
  ].forEach(([v, l]) => select.add(new Option(l!, v)));
  select.value = ui.status;
  const grid = el("div");
  const searchText = new Map<string, string>();
  const editRow = (type: MemoryTypeDefinition, row?: MemoryRow) => {
    const spec: Field[] = [
      {
        key: "dataName",
        label: "条目名称",
        value: row?.dataName,
        required: true,
      },
      {
        key: "status",
        label: "激活方式",
        type: "select",
        value: row?.status ?? "keyword",
        options: [
          ["keyword", "关键词"],
          ["vectorized", "向量"],
          ["permanent", "常驻"],
        ],
      },
      {
        key: "keywords",
        label: "关键词（每行一项）",
        type: "textarea",
        value: row?.keywords.join("\n"),
        rows: 3,
      },
      { key: "aliases", label: "实体别名（每行一项）", type: "textarea", value: row?.aliases?.join("\n") ?? "", rows: 3 },
      ...type.columns.map(
        (col): Field => ({
          key: "value:" + col.id,
          label: col.name,
          type:
            col.type === "number"
              ? "number"
              : col.type === "boolean" || col.type === "enum"
                ? "select"
                : col.type === "json"
                  ? "json"
                  : col.type === "long_text"
                    ? "textarea"
                    : "text",
          value: row?.values[col.id] ?? col.defaultValue,
          required: col.required,
          options:
            col.type === "boolean"
              ? [
                  ["", "未设置"],
                  ["true", "是"],
                  ["false", "否"],
                ]
              : col.enumValues?.map((x) => [x, x]),
          step: col.type === "number" ? 0.01 : undefined,
        }),
      ),
    ];
    editDialog(row ? "编辑 " + row.dataName : "新增档案", spec, async (v) => {
      ctx.guard();
      const values: Record<string, unknown> = {};
      for (const col of type.columns) {
        const value = v["value:" + col.id];
        if (value !== "" && value !== undefined)
          values[col.id] = col.type === "boolean" ? value === "true" : value;
      }
      await store.saveRow(
        type.id,
        {
          dataName: v.dataName,
          aliases: v.aliases.split("\n").map((name: string) => name.trim()).filter(Boolean),
          status: v.status,
          keywords: v.keywords
            .split("\n")
            .map((x: string) => x.trim())
            .filter(Boolean),
          values,
        },
        row?.id,
        row?.revision,
      );
      await ctx.refresh();
    });
  };
  const draw = () => {
    const type = state.catalog.types.find((t) => t.id === ui.typeId);
    if (!type) {
      host.replaceChildren(
        empty("尚未创建记忆表", button("新建表", "plus", addType)),
      );
      return;
    }
    const query = ui.query.toLocaleLowerCase();
    const rows = state.rows.filter(
      (r) =>
        r.typeId === type.id &&
        (ui.status === "all" || r.status === ui.status) &&
        (!query || (() => {
          let text = searchText.get(r.id);
          if (text === undefined) {
            text = JSON.stringify(r).toLocaleLowerCase();
            searchText.set(r.id, text);
          }
          return text.includes(query);
        })()),
    );
    const pageSize = 50;
    const totalPages = Math.max(1, Math.ceil(rows.length / pageSize));
    ui.page = Math.max(0, Math.min(ui.page, totalPages - 1));
    const visibleRows = rows.slice(ui.page * pageSize, (ui.page + 1) * pageSize);
    // Selections may outlive filters or a table switch; drop ids that no longer
    // resolve to a row in the current table.
    const liveIds = new Set(state.rows.filter((row) => row.typeId === type.id).map((row) => row.id));
    for (const id of ui.selected) if (!liveIds.has(id)) ui.selected.delete(id);
    drawSelection();
    grid.replaceChildren(
      rows.length
        ? table(
            [
              "选择",
              "条目名称",
              ...type.columns.slice(0, 3).map((c) => c.name),
              "激活方式",
              "操作",
            ],
            visibleRows.map((row) => [
              check("选择 " + row.dataName, ui.selected.has(row.id), (v) => {
                v ? ui.selected.add(row.id) : ui.selected.delete(row.id);
                drawSelection();
              }),
              el("strong", "", row.dataName),
              ...type.columns
                .slice(0, 3)
                .map((c) =>
                  el(
                    "span",
                    "ew-cell-summary",
                    typeof row.values[c.id] === "object"
                      ? JSON.stringify(row.values[c.id])
                      : String(row.values[c.id] ?? ""),
                  ),
                ),
              stateBadge(row.status),
              actions(
                tool("编辑 " + row.dataName, "pen", () => editRow(type, row)),
                tool("时间与认知属性", "clock", () => editContinuity(row.dataName + " · 时间与认知", row.continuity, async (continuity) => {
                  ctx.guard();
                  await store.saveRow(type.id, { ...row, continuity }, row.id, row.revision);
                  await ctx.refresh();
                })),
                tool(
                  "删除 " + row.dataName,
                  "trash",
                  async () => {
                    if (confirm("删除条目 " + row.dataName + "？")) {
                      ctx.guard();
                      await store.deleteRow(row.id);
                      await ctx.refresh();
                    }
                  },
                  "danger",
                ),
              ),
            ]),
            "ew-records-table",
          )
        : empty("没有匹配的记录"),
    );
    if (rows.length > pageSize) {
      const previous = tool("上一页档案", "chevron-left", () => {
        ui.page -= 1;
        draw();
      });
      const next = tool("下一页档案", "chevron-right", () => {
        ui.page += 1;
        draw();
      });
      previous.disabled = ui.page === 0;
      next.disabled = ui.page === totalPages - 1;
      grid.append(actions(previous,
        el("span", "ew-muted", `${ui.page + 1} / ${totalPages} 页`), next));
    }
    nav.replaceChildren(
      ...state.catalog.types.map((t) =>
        button(
          t.name,
          "table-cells",
          () => {
            ui.typeId = t.id;
            ui.page = 0;
            draw();
          },
          t.id === ui.typeId ? "is-selected" : "",
        ),
      ),
    );
    host.replaceChildren(
      actions(
        el("h2", "", type.name),
        badge(String(rows.length) + " 条"),
        button("新增档案", "plus", () => editRow(type), "primary"),
      ),
      el(
        "div",
        "ew-toolbar",
        searchBox(
          ui.query,
          (v) => {
            ui.query = v;
            ui.page = 0;
            drawGrid();
          },
          "搜索名称或内容",
          ctx.signal,
        ),
        select,
      ),
      actions(
        button("选择筛选结果", "check-double", () => {
          rows.forEach((row) => ui.selected.add(row.id));
          draw();
        }),
        el("span", "ew-muted", `筛选结果 ${rows.length} 条`),
      ),
      selectionBar,
      grid,
    );
  };
  const drawGrid = () => {
    const focused = host.querySelector<HTMLInputElement>(".ew-search");
    const caret = focused?.selectionStart;
    draw();
    const next = host.querySelector<HTMLInputElement>(".ew-search");
    next?.focus();
    if (next && caret !== null && caret !== undefined)
      try {
        next.setSelectionRange(caret, caret);
      } catch {}
  };
  select.addEventListener("change", () => {
    ui.status = select.value;
    ui.page = 0;
    draw();
  });
  draw();
  page.append(split);
  if (state.issues.length)
    page.prepend(
      detail(
        "有 " + state.issues.length + " 个世界书条目无法解析",
        state.issues,
      ),
    );
  return page;
}
