import { randomUuid } from "../../shared/crypto-compat";
import type { RecallFlagRule, SummarySlice } from "../../shared/domain";
import type { SummaryWorldbookState } from "../worldbook/summary-worldbook";
import { getSettings, saveSettings } from "../state/settings";
import { actions, button, check, dialog, editDialog, el, empty, fields, saveForm, section,
  table, tool, notify, type Field, type ViewContext } from "./core";

function weightFields(addWeight = 0, multiplyWeight = 0): Field[] {
  return [
    { key: "addWeight", label: "加权重", type: "number", min: -1, max: 1, step: 0.01, value: addWeight },
    { key: "multiplyWeight", label: "乘权重（0：不启用）", type: "number", min: 0, max: 10,
      step: 0.01, value: multiplyWeight },
  ];
}

export function assignRecallFlags(ctx: ViewContext, state: SummaryWorldbookState, slices: SummarySlice[]): void {
  const rules = getSettings().retrieval.recall.flagRules ?? [];
  if (!rules.length) {
    const modal = dialog("设置标志", empty("尚未创建人工标志", button("管理标志", "flag", () => {
      modal.close();
      ctx.state.set("recall-section", "enhancements");
      ctx.state.set("recall-focus", "flags");
      ctx.navigate("summary/recall");
    })));
    return;
  }
  const single = slices.length === 1;
  const form = fields([
    ...(!single ? [{ key: "mode", label: "批量处理方式", type: "select" as const, value: "add",
      options: [["add", "添加选中标志"], ["remove", "移除选中标志"], ["replace", "替换全部标志"]] as Array<[string, string]> }] : []),
    ...rules.map((flag) => ({ key: flag.id, label: flag.name, type: "checkbox" as const,
      value: single && (slices[0]?.recallFlags ?? []).includes(flag.id) })),
  ]);
  dialog(single ? "设置切片标志" : `批量设置标志 · ${slices.length} 个切片`, form.node, async () => {
    const values = form.values();
    ctx.guard();
    const activeIds = new Set((getSettings().retrieval.recall.flagRules ?? []).map((flag) => flag.id));
    const flags = rules.filter((flag) => values[flag.id] && activeIds.has(flag.id)).map((flag) => flag.id);
    await ctx.summary.store.saveSliceFlags(state.worldbookName, slices.map((slice) => slice.id), flags,
      single ? "replace" : values.mode);
    await ctx.refresh();
  }, form.dirty);
}

export function recallEnhancements(ctx: ViewContext, state: SummaryWorldbookState): HTMLElement {
  const host = section("召回增强策略");
  let sources = [
    { chatId: state.catalog.chatId, namespaceId: state.catalog.namespaceId, worldbookName: state.worldbookName,
      enabled: true, weight: state.catalog.recallSourceWeight, addWeight: state.catalog.recallSourceAddWeight ?? 0,
      order: state.catalog.recallSourceOrder },
    ...structuredClone(state.catalog.attachedRecallSources).map((s) => ({ ...s, addWeight: s.addWeight ?? 0 })),
  ].sort((a, b) => a.order - b.order);
  const sourceHost = el("div");
  const dirty = () => { sourceHost.dataset.dirty = "true"; };
  const moveSource = (index: number, offset: number) => {
    const target = index + offset;
    if (target < 0 || target >= sources.length) return;
    [sources[index], sources[target]] = [sources[target]!, sources[index]!];
    dirty(); drawSources();
  };
  const drawSources = () => {
    sourceHost.replaceChildren(table(["来源聊天", "加权重", "乘权重", "启用", "操作"], sources.map((s, i) => [
      s.namespaceId === state.catalog.namespaceId ? `${s.chatId}（当前）` : s.chatId,
      s.addWeight.toFixed(2), s.weight.toFixed(2),
      s.namespaceId === state.catalog.namespaceId ? "当前聊天" : check(`启用 ${s.chatId}`, s.enabled, (value) => { s.enabled = value; dirty(); }),
      actions(
        tool("设置来源权重", "sliders", () => editDialog("来源权重", weightFields(s.addWeight, s.weight), (v) => {
          s.addWeight = v.addWeight; s.weight = v.multiplyWeight; dirty(); drawSources();
        })),
        tool("上移来源", "arrow-up", () => moveSource(i, -1)),
        tool("下移来源", "arrow-down", () => moveSource(i, 1)),
        ...(s.namespaceId === state.catalog.namespaceId ? [] : [tool("移除来源", "trash", () => {
          sources.splice(i, 1); dirty(); drawSources();
        }, "danger")]),
      ),
    ])));
  };
  drawSources();
  host.append(el("h3", "", "来源排序与权重"), sourceHost, actions(
    button("附加聊天", "plus", async () => {
      const available = (await ctx.summary.store.listAvailableSources()).filter((s) =>
        !sources.some((item) => item.namespaceId === s.catalog.namespaceId));
      if (!available.length) throw new Error("没有可附加的其他聊天总结。");
      editDialog("附加召回来源", [{ key: "source", label: "聊天", type: "select",
        options: available.map((s) => [s.catalog.namespaceId, s.catalog.chatId]) }], (v) => {
        const s = available.find((item) => item.catalog.namespaceId === v.source)!;
        sources.push({ chatId: s.catalog.chatId, namespaceId: s.catalog.namespaceId, worldbookName: s.worldbookName,
          enabled: true, weight: 0, addWeight: 0, order: sources.length });
        dirty(); drawSources();
      });
    }),
    button("保存来源", "floppy-disk", async () => {
      ctx.guard();
      const fresh = await ctx.summary.load();
      sources = sources.map((s, order) => ({ ...s, order }));
      const current = sources.find((s) => s.namespaceId === state.catalog.namespaceId)!;
      await ctx.summary.store.saveRecallConfiguration(fresh.worldbookName, {
        enabled: fresh.catalog.recallEnabled, weight: current.weight, addWeight: current.addWeight, order: current.order,
        attachedSources: sources.filter((s) => s.namespaceId !== current.namespaceId),
      });
      delete sourceHost.dataset.dirty;
      notify("来源配置已保存");
    }, "primary"),
  ));
  const flagsHost = el("div");
  const editFlag = (flag?: RecallFlagRule) => editDialog(flag ? "编辑标志" : "新增标志", [
    { key: "name", label: "标志名称", value: flag?.name ?? "", required: true },
    ...weightFields(flag?.addWeight, flag?.multiplyWeight),
    { key: "retentionTurns", label: "额外滞留回合数", type: "number", min: 0, max: 100,
      value: flag?.retentionTurns ?? 0 },
  ], (v) => {
    ctx.guard();
    const settings = getSettings();
    const next: RecallFlagRule = { id: flag?.id ?? `flag_${randomUuid().replaceAll("-", "")}`,
      name: String(v.name).trim(), addWeight: v.addWeight, multiplyWeight: v.multiplyWeight, retentionTurns: v.retentionTurns };
    const rules = settings.retrieval.recall.flagRules ?? [];
    settings.retrieval.recall.flagRules = flag ? rules.map((item) => item.id === flag.id ? next : item) : [...rules, next];
    saveSettings(settings); drawFlags();
  });
  const drawFlags = () => {
    const rules = getSettings().retrieval.recall.flagRules ?? [];
    flagsHost.replaceChildren(rules.length ? table(["标志", "加权重", "乘权重", "额外滞留回合", "操作"], rules.map((flag) => [
      flag.name, flag.addWeight.toFixed(2), flag.multiplyWeight.toFixed(2), flag.retentionTurns,
      actions(tool("编辑标志", "pen", () => editFlag(flag)), tool("删除标志", "trash", () => {
        if (!confirm(`删除标志“${flag.name}”及其召回效果？`)) return;
        ctx.guard();
        const settings = getSettings();
        settings.retrieval.recall.flagRules = (settings.retrieval.recall.flagRules ?? []).filter((item) => item.id !== flag.id);
        saveSettings(settings); drawFlags();
      }, "danger")),
    ])) : empty("尚未创建人工标志"));
  };
  drawFlags();
  const pool = fields([{ key: "maximum", label: "额外召回池最大切片数（0：关闭）", type: "number",
    min: 0, max: 1000, value: getSettings().retrieval.recall.retentionMaxSlices ?? 20 }]);
  const poolHost = el("div", "ew-recall-pool");
  const drawPool = (snapshot: SummaryWorldbookState) => {
    poolHost.replaceChildren(table(["切片", "来源", "剩余回合"], (snapshot.catalog.recallPool?.entries ?? []).map((entry) => [
      snapshot.slices.find((slice) => slice.id === entry.sliceId)?.title ?? entry.sliceId,
      sources.find((source) => source.namespaceId === entry.namespaceId)?.chatId ?? entry.namespaceId, entry.remaining,
    ])));
  };
  const refreshPool = async () => {
    const fresh = await ctx.summary.load();
    ctx.guard();
    if (!ctx.signal.aborted) drawPool(fresh);
  };
  drawPool(state);
  const flagsHeading = el("h3", "", "标志权重");
  flagsHeading.dataset.recallAnchor = "flags";
  flagsHeading.tabIndex = -1;
  host.append(flagsHeading, flagsHost, actions(button("新增标志", "plus", () => editFlag())),
    el("h3", "", "额外召回池"), saveForm(pool, async (v) => {
      ctx.guard();
      const settings = getSettings(); settings.retrieval.recall.retentionMaxSlices = v.maximum; saveSettings(settings);
      const fresh = await ctx.summary.load();
      const saved = fresh.catalog.recallPool;
      if (saved) {
        const evicted = new Set<string>();
        while (saved.entries.length > v.maximum) {
          const remaining = Math.min(...saved.entries.map((item) => item.remaining));
          const entry = saved.entries.splice(saved.entries.findIndex((item) => item.remaining === remaining), 1)[0]!;
          evicted.add(`${entry.namespaceId}:${entry.sliceId}`);
        }
        saved.replay = saved.replay.filter((item) => !evicted.has(`${item.namespaceId}:${item.sliceId}`)).slice(0, v.maximum);
        await ctx.summary.store.saveRecallPool(fresh.worldbookName, saved, ctx.guard);
      }
      await refreshPool();
    }, "保存召回池设置"),
    poolHost,
    actions(button("清空额外召回池", "trash", async () => {
      ctx.guard();
      await ctx.summary.store.saveRecallPool(state.worldbookName, { floorKey: "", entries: [], replay: [] }, ctx.guard);
      await refreshPool();
    }, "danger")),
  );
  return host;
}
