import { randomUuid } from "../../shared/crypto-compat";
import { z } from "zod";

export interface MemoryHistoryRecord {
  id: string;
  rowId: string;
  typeId: string;
  recordedAt: string;
  kind: string;
  before: { name: string; content: string; metadata: Record<string, any> } | null;
  after: { name: string; content: string; metadata: Record<string, any> } | null;
}
const snapshotSchema = z.object({ name: z.string(), content: z.string(), metadata: z.record(z.string(), z.unknown()) }).nullable();
export const memoryHistorySchema = z.object({
  id: z.string().min(1), rowId: z.string().min(1), typeId: z.string().min(1), recordedAt: z.string().datetime(),
  kind: z.string(), before: snapshotSchema, after: snapshotSchema,
});

export function appendMemoryHistory(before: TavernWorldbookEntry[], after: TavernWorldbookEntry[]): void {
  const old = new Map(before.filter((entry) => entry.extra?.echoes?.kind === "row").map((entry) => [entry.extra!.echoes.rowId, entry]));
  const next = new Map(after.filter((entry) => entry.extra?.echoes?.kind === "row").map((entry) => [entry.extra!.echoes.rowId, entry]));
  const snapshot = (entry?: TavernWorldbookEntry) => entry ? {
    name: entry.name, content: entry.content, metadata: structuredClone(entry.extra!.echoes),
  } : null;
  for (const id of new Set([...old.keys(), ...next.keys()])) {
    const previous = old.get(id), current = next.get(id);
    if (!previous) continue;
    if (current && JSON.stringify([previous.content, previous.extra?.echoes, previous.strategy, previous.enabled])
      === JSON.stringify([current.content, current.extra?.echoes, current.strategy, current.enabled])) continue;
    const record: MemoryHistoryRecord = {
      id: randomUuid(), rowId: String(id), typeId: previous.extra!.echoes.typeId,
      recordedAt: new Date().toISOString(),
      kind: !current ? "deleted" : JSON.stringify(previous.extra?.echoes.continuity) === JSON.stringify(current.extra?.echoes.continuity)
        ? "unclassified" : current.extra?.echoes.continuity?.changeKind ?? "unclassified",
      before: snapshot(previous), after: snapshot(current),
    };
    after.push({
      name: `Echoes History ${record.rowId}`, enabled: false, content: "Echoes history. Not current world knowledge.",
      strategy: { type: "constant", keys: [] },
      extra: { echoes: { kind: "memory_history", version: 1, record } },
    } as unknown as TavernWorldbookEntry);
  }
}

export async function readMemoryHistory(worldbookName: string): Promise<MemoryHistoryRecord[]> {
  const entries = await window.TavernHelper!.getWorldbook(worldbookName);
  return entries.filter((entry) => entry.extra?.echoes?.kind === "memory_history")
    .map((entry) => memoryHistorySchema.parse(entry.extra!.echoes.record) as MemoryHistoryRecord)
    .sort((a, b) => b.recordedAt.localeCompare(a.recordedAt));
}
