import type {
  ExtractionResult,
  ExtractionReviewItem,
  ExtractionTrace,
  JobRecord,
  MemoryExtractionOperation,
  ProviderAttempt,
  StructuredExtractionMode,
} from "../../shared/domain";
import { structuredExtractionMessageHash } from "../../shared/extraction-core";
import { echoesApi } from "../api/client";
import { getSettings } from "../state/settings";
import {
  WorldbookMemoryStore,
  type ApplySummary,
  type WorldbookMemoryState,
} from "../worldbook/worldbook-memory";
import {
  currentExtractionMessages,
  ExtractionBatchUnavailableError,
  ExtractionCheckpointMissingError,
  prepareExtraction,
  prepareCleaningExtraction,
  type ExtractionCleaningOptions,
  type PreparedExtraction,
} from "./extraction-request";
import { checkpointMessageAtFloor } from "../chat-message-index";

const TERMINAL_STATES = new Set(["succeeded", "failed", "cancelled", "ambiguous"]);

function sleep(durationMs: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, durationMs));
}

function abortable<T>(promise: Promise<T>, signal: AbortSignal): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    const abort = () => reject(signal.reason ?? new DOMException("Extraction stopped.", "AbortError"));
    signal.addEventListener("abort", abort, { once: true });
    void promise.then(resolve, reject).finally(() => signal.removeEventListener("abort", abort));
    if (signal.aborted) abort();
  });
}

async function waitForJob(
  initial: JobRecord<ExtractionResult>,
  onUpdate: (job: JobRecord<ExtractionResult>) => void,
  signal: AbortSignal,
): Promise<JobRecord<ExtractionResult>> {
  const deadline = Date.now() + 2 * 60 * 60_000;
  let job = initial;
  onUpdate(job);
  while (!TERMINAL_STATES.has(job.status) && Date.now() < deadline) {
    signal.throwIfAborted();
    await abortable(sleep(600), signal);
    job = await abortable(echoesApi.getJob<ExtractionResult>(job.id), signal);
    onUpdate(job);
  }
  if (!TERMINAL_STATES.has(job.status)) throw new Error("等待结构化记忆任务超时。");
  if (job.status !== "succeeded" || !job.result) {
    throw new Error(job.error?.message ?? job.message);
  }
  return job;
}

function currentBatchMessages(prepared: PreparedExtraction): Array<{
  id: string;
  role: "system" | "assistant" | "user";
  content: string;
}> | null {
  if (SillyTavern.getContext().chatId !== prepared.request.chatId) return null;
  const byId = new Map(currentExtractionMessages().map((message) => [message.id, message]));
  const messages = prepared.batch.messageIds.map((id) => byId.get(id));
  if (messages.some((message) => !message)) return [];
  return messages as Array<{
    id: string;
    role: "system" | "assistant" | "user";
    content: string;
  }>;
}

export interface PendingExtractionReview {
  chatId: string;
  worldbookName: string;
  prepared: PreparedExtraction;
  result: ExtractionResult;
  jobId: string;
  selectedIndexes: number[];
  createdAt: string;
}

type Listener = () => void;

export class ExtractionCoordinator {
  readonly store = new WorldbookMemoryStore();
  private readonly active = new Map<string, Promise<void>>();
  private readonly activeJobIds = new Map<string, string>();
  private readonly controls = new Map<string, AbortController>();
  private readonly activeModes = new Map<string, StructuredExtractionMode>();
  private readonly reviews = new Map<string, PendingExtractionReview>();
  private readonly pauses = new Map<string, string>();
  private readonly traces = new Map<string, ExtractionTrace>();
  private readonly listeners = new Set<Listener>();
  private readonly rerunAutomatic = new Set<string>();
  private readonly cleaningOptions = new Map<string, ExtractionCleaningOptions>();
  private readonly checkpointUpdates = new Set<string>();

  subscribe(listener: Listener): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  review(chatId = SillyTavern.getContext().chatId ?? ""): PendingExtractionReview | null {
    const review = this.reviews.get(chatId);
    return review ? structuredClone(review) : null;
  }

  trace(chatId = SillyTavern.getContext().chatId ?? ""): ExtractionTrace | null {
    const trace = this.traces.get(chatId);
    return trace ? structuredClone(trace) : null;
  }

  pauseReason(chatId = SillyTavern.getContext().chatId ?? ""): string | null {
    return this.pauses.get(chatId) ?? null;
  }

  isRunning(chatId = SillyTavern.getContext().chatId ?? ""): boolean {
    return this.active.has(chatId) || this.checkpointUpdates.has(chatId);
  }

  runAutomatic(): Promise<void> {
    return this.start("auto");
  }

  runManual(): Promise<void> {
    const chatId = SillyTavern.getContext().chatId ?? "";
    if (chatId) this.pauses.delete(chatId);
    return this.start("manual", true);
  }

  runCleaning(options: ExtractionCleaningOptions): Promise<void> {
    const chatId = SillyTavern.getContext().chatId;
    if (!chatId) return Promise.reject(new Error("请先选择聊天。"));
    if (this.isRunning()) return Promise.reject(new Error("请先停止正在运行的结构化任务。"));
    if (this.reviews.has(chatId)) return Promise.reject(new Error("请先提交或重试当前待审核批次。"));
    this.cleaningOptions.set(chatId, structuredClone(options));
    this.pauses.delete(chatId);
    return this.start("cleaning", true);
  }

  async previewCleaning(options: ExtractionCleaningOptions): Promise<PreparedExtraction> {
    return prepareCleaningExtraction(await this.store.load(), getSettings(), options);
  }

  relocateCheckpointToFloor(floor: number): Promise<void> {
    return this.relocateCheckpoint(checkpointMessageAtFloor(floor));
  }

  async retryCurrent(): Promise<void> {
    const chatId = SillyTavern.getContext().chatId;
    if (!chatId) return;
    const mode = this.reviews.get(chatId)?.prepared.batch.mode
      ?? this.traces.get(chatId)?.batch?.mode
      ?? "manual";
    this.reviews.delete(chatId);
    this.pauses.delete(chatId);
    this.emit();
    await this.start(mode, true);
  }

  async stopCurrent(): Promise<void> {
    const chatId = SillyTavern.getContext().chatId;
    if (!chatId) return;
    let reason = "用户停止了结构化记忆任务；本页面会话内不会自动重试。";
    const updateStoppedState = () => {
      this.pauses.set(chatId, reason);
      const trace = this.traces.get(chatId);
      if (trace) {
        this.traces.set(chatId, {
          ...trace,
          state: "paused",
          completedAt: new Date().toISOString(),
          message: reason,
        });
      }
      this.emit();
    };
    this.rerunAutomatic.delete(chatId);
    const jobId = this.activeJobIds.get(chatId);
    this.controls.get(chatId)?.abort(new DOMException("Extraction stopped.", "AbortError"));
    updateStoppedState();
    if (!jobId) return;
    try {
      const result = await echoesApi.cancelJob(jobId);
      if (!result.cancelled) reason = "用户停止了本地结构化记忆流程，但后台任务未确认取消；不会提交迟到结果或自动重试。";
    } catch (error) {
      reason = "用户停止了本地结构化记忆流程，但后台取消请求失败；不会提交迟到结果或自动重试。";
      console.error("[Echoes] Failed to cancel structured-memory job.", error);
    }
    updateStoppedState();
  }

  async submitReview(selectedIndexes: number[]): Promise<ApplySummary> {
    const chatId = SillyTavern.getContext().chatId;
    const review = chatId ? this.reviews.get(chatId) : undefined;
    if (!chatId || !review) throw new Error("当前聊天没有待审核的结构化记忆批次。");
    const allowed = new Set(
      review.result.reviewItems.filter((item) => item.state === "valid").map((item) => item.index),
    );
    if (selectedIndexes.some((index) => !allowed.has(index))) {
      throw new Error("审核选择包含无效或不存在的操作。");
    }
    await this.verifyCurrentMessages(review.prepared);
    const operations = review.result.reviewItems
      .filter((item) => selectedIndexes.includes(item.index) && item.state === "valid")
      .sort((left, right) => left.index - right.index)
      .map((item) => item.operation as MemoryExtractionOperation);
    const summary = await this.store.commitExtractionBatch({
      worldbookName: review.worldbookName,
      chatId,
      batch: review.prepared.batch,
      expectedCheckpoint: review.prepared.expectedCheckpoint,
      operations,
      jobId: review.jobId,
    });
    this.reviews.delete(chatId);
    this.pauses.delete(chatId);
    this.traces.set(chatId, {
      chatId,
      worldbookName: review.worldbookName,
      state: "completed",
      batch: review.prepared.batch,
      startedAt: this.traces.get(chatId)?.startedAt ?? review.createdAt,
      completedAt: new Date().toISOString(),
      applied: operations.length,
      rejected: review.result.reviewItems.length - operations.length,
      attempts: review.result.attempts,
      message: "人工审核已提交，未选择及无效操作已明确跳过。",
    });
    this.emit();
    if (review.prepared.batch.mode === "auto") void this.runAutomatic();
    return summary;
  }

  async setAutomationEnabled(enabled: boolean): Promise<void> {
    const chatId = SillyTavern.getContext().chatId;
    const stopping = !enabled && chatId && this.activeModes.get(chatId) === "auto"
      ? this.stopCurrent() : undefined;
    await this.store.setAutomationEnabled(enabled);
    await stopping;
    if (enabled && chatId) {
      this.pauses.delete(chatId);
      void this.runAutomatic();
    }
    this.emit();
  }

  async relocateCheckpoint(messageId: string | null): Promise<void> {
    const chatId = SillyTavern.getContext().chatId;
    if (!chatId) return;
    if (this.isRunning(chatId)) throw new Error("请先停止正在运行的结构化任务，再修改检查点。");
    if (messageId !== null && !currentExtractionMessages().some((message) => message.id === messageId)) {
      throw new Error("检查点消息不存在于当前聊天。");
    }
    this.rerunAutomatic.delete(chatId);
    this.checkpointUpdates.add(chatId);
    try {
      await this.store.relocateCheckpoint(messageId);
      this.reviews.delete(chatId);
      this.pauses.delete(chatId);
      this.traces.delete(chatId);
      this.cleaningOptions.delete(chatId);
    } finally {
      this.checkpointUpdates.delete(chatId);
      this.emit();
    }
  }

  private start(mode: StructuredExtractionMode, userInitiated = false): Promise<void> {
    const chatId = SillyTavern.getContext().chatId;
    if (!chatId) return Promise.resolve();
    if (this.checkpointUpdates.has(chatId)) {
      return userInitiated ? Promise.reject(new Error("正在修改检查点，请稍后再试。")) : Promise.resolve();
    }
    const existing = this.active.get(chatId);
    if (existing) {
      if (mode === "auto" && !userInitiated) this.rerunAutomatic.add(chatId);
      return existing;
    }
    if (!userInitiated && (this.pauses.has(chatId) || this.reviews.has(chatId))) {
      return Promise.resolve();
    }
    const control = new AbortController();
    this.controls.set(chatId, control);
    this.activeModes.set(chatId, mode);
    const operation = this.run(mode, userInitiated, control.signal).finally(() => {
      if (this.active.get(chatId) === operation) this.active.delete(chatId);
      const shouldRerun = this.rerunAutomatic.delete(chatId);
      this.activeJobIds.delete(chatId);
      if (this.controls.get(chatId) === control) this.controls.delete(chatId);
      this.activeModes.delete(chatId);
      this.emit();
      if (shouldRerun && SillyTavern.getContext().chatId === chatId) {
        queueMicrotask(() => {
          void this.runAutomatic().catch((error) =>
            console.error("[Echoes] Deferred structured extraction failed.", error));
        });
      }
    });
    this.active.set(chatId, operation);
    this.emit();
    return operation;
  }

  private async run(mode: StructuredExtractionMode, userInitiated: boolean, signal: AbortSignal): Promise<void> {
    const lockedChatId = SillyTavern.getContext().chatId!;
    const continueAutomatically = mode === "auto";
    let firstBatch = true;
    while (true) {
      let state: WorldbookMemoryState | null = null;
      try {
        signal.throwIfAborted();
        state = await this.store.load();
        if (state.catalog.chatId !== lockedChatId) throw new Error("结构化记忆世界书与当前聊天不匹配。");
        if (mode === "auto" && !state.catalog.automation.enabled && !(userInitiated && firstBatch)) return;
        const cleaning = this.cleaningOptions.get(lockedChatId);
        if (mode === "cleaning" && !cleaning) throw new Error("清洗范围已不存在，请重新选择楼层。");
        const prepared = mode === "cleaning"
          ? await prepareCleaningExtraction(state, getSettings(), cleaning!)
          : await prepareExtraction(state, getSettings(), mode);
        const outcome = await this.executePrepared(state, prepared, signal);
        if (outcome !== "committed") return;
        firstBatch = false;
      } catch (error) {
        if (error instanceof ExtractionBatchUnavailableError) {
          if (error.mode === "manual" && userInitiated) throw error;
          return;
        }
        if (this.pauses.get(lockedChatId)?.startsWith("用户停止了")) return;
        const message = error instanceof Error ? error.message : String(error);
        const blocked = error instanceof ExtractionCheckpointMissingError;
        this.pauses.set(lockedChatId, message);
        this.traces.set(lockedChatId, {
          chatId: lockedChatId,
          worldbookName: state?.worldbookName ?? window.TavernHelper?.getChatWorldbookName("current") ?? "",
          state: blocked ? "blocked" : "failed",
          startedAt: new Date().toISOString(),
          completedAt: new Date().toISOString(),
          applied: 0,
          rejected: 0,
          attempts: [],
          message,
        });
        this.emit();
        if (userInitiated) throw error;
        return;
      }
      if (!continueAutomatically || SillyTavern.getContext().chatId !== lockedChatId) return;
      mode = "auto";
    }
  }

  private async executePrepared(
    state: WorldbookMemoryState,
    prepared: PreparedExtraction,
    signal: AbortSignal,
  ): Promise<"committed" | "paused" | "review"> {
    const startedAt = new Date().toISOString();
    let attempts: ProviderAttempt[] = [];
    let request = structuredClone(prepared.request);
    this.traces.set(prepared.request.chatId, {
      chatId: prepared.request.chatId,
      worldbookName: state.worldbookName,
      state: "running",
      batch: prepared.batch,
      startedAt,
      applied: 0,
      rejected: 0,
      attempts: [],
      message: "等待结构化记忆副 API。",
    });
    this.emit();

    while (true) {
      signal.throwIfAborted();
      const accepted = echoesApi.startExtraction(request).then((initial) => {
        if (signal.aborted) {
          void echoesApi.cancelJob(initial.id).catch((error) =>
            console.error("[Echoes] Failed to cancel late structured-memory job.", error));
        } else {
          this.activeJobIds.set(prepared.request.chatId, initial.id);
        }
        return initial;
      });
      const initial = await abortable(accepted, signal);
      const job = await waitForJob(initial, (current) => {
        this.activeJobIds.set(prepared.request.chatId, current.id);
        this.traces.set(prepared.request.chatId, {
          chatId: prepared.request.chatId,
          worldbookName: state.worldbookName,
          state: "running",
          batch: prepared.batch,
          startedAt,
          applied: 0,
          rejected: 0,
          attempts,
          message: current.message,
        });
        this.emit();
      }, signal);
      signal.throwIfAborted();
      const result = job.result!;
      attempts = [...attempts, ...result.attempts];
      result.attempts = attempts;
      if (result.outcome === "decision_required" && result.decisionRequired) {
        signal.throwIfAborted();
        const decision = result.decisionRequired;
        const proceed = Boolean(decision.nextEndpointId) && window.confirm(
          `${decision.message}\n\n切换到下一端点可能产生重复计费。确定继续；取消则保留当前检查点并暂停自动提取。`,
        );
        if (!proceed) {
          const reason = "用户停止了不确定结果续接；本页面会话内不会自动重试。";
          this.pauses.set(prepared.request.chatId, reason);
          this.traces.set(prepared.request.chatId, {
            chatId: prepared.request.chatId,
            worldbookName: state.worldbookName,
            state: "paused",
            batch: prepared.batch,
            startedAt,
            completedAt: new Date().toISOString(),
            applied: 0,
            rejected: 0,
            attempts,
            message: reason,
          });
          this.emit();
          return "paused";
        }
        request = {
          ...request,
          resumeAfterEndpointId: decision.failedEndpointId,
        };
        continue;
      }

      signal.throwIfAborted();
      const reviewItems = normalizeReviewItems(result);
      result.reviewItems = reviewItems;
      if (prepared.batch.mode === "cleaning" || reviewItems.some((item) => item.state === "rejected")) {
        const review: PendingExtractionReview = {
          chatId: prepared.request.chatId,
          worldbookName: state.worldbookName,
          prepared: structuredClone(prepared),
          result: structuredClone(result),
          jobId: job.id,
          selectedIndexes: reviewItems.filter((item) => item.state === "valid").map((item) => item.index),
          createdAt: new Date().toISOString(),
        };
        this.reviews.set(prepared.request.chatId, review);
        const reviewMessage = prepared.batch.mode === "cleaning"
          ? "记忆清洗结果等待审核；提交后不会移动正常提取检查点。"
          : "批次包含无效操作，等待人工审核。";
        this.pauses.set(prepared.request.chatId, reviewMessage);
        this.traces.set(prepared.request.chatId, {
          chatId: prepared.request.chatId,
          worldbookName: state.worldbookName,
          state: "review_required",
          batch: prepared.batch,
          startedAt,
          completedAt: new Date().toISOString(),
          applied: 0,
          rejected: reviewItems.filter((item) => item.state === "rejected").length,
          attempts,
          message: reviewMessage,
        });
        this.emit();
        return "review";
      }

      signal.throwIfAborted();
      await this.verifyCurrentMessages(prepared);
      const summary = await this.store.commitExtractionBatch({
        worldbookName: state.worldbookName,
        chatId: prepared.request.chatId,
        batch: prepared.batch,
        expectedCheckpoint: prepared.expectedCheckpoint,
        operations: result.operations,
        jobId: job.id,
        signal,
      });
      this.pauses.delete(prepared.request.chatId);
      this.traces.set(prepared.request.chatId, {
        chatId: prepared.request.chatId,
        worldbookName: state.worldbookName,
        state: "completed",
        batch: prepared.batch,
        startedAt,
        completedAt: new Date().toISOString(),
        applied: result.operations.length,
        rejected: 0,
        attempts,
        message: `已提交：新增 ${summary.added}，修改 ${summary.updated}，删除 ${summary.deleted}。`,
      });
      this.emit();
      return "committed";
    }
  }

  private async verifyCurrentMessages(prepared: PreparedExtraction): Promise<void> {
    const messages = currentBatchMessages(prepared);
    if (messages === null) return;
    if (messages.length !== prepared.batch.messageIds.length
      || await structuredExtractionMessageHash(messages) !== prepared.batch.sourceHash) {
      throw new Error("未提交批次的聊天消息在任务期间发生变化，结果已丢弃。");
    }
  }

  private emit(): void {
    for (const listener of this.listeners) listener();
  }
}

function normalizeReviewItems(result: ExtractionResult): ExtractionReviewItem[] {
  if (Array.isArray(result.reviewItems)) return result.reviewItems;
  const items: ExtractionReviewItem[] = result.operations.map((operation, index) => ({
    index,
    state: "valid",
    operation,
  }));
  result.rejectedOperations.forEach((item, offset) => {
    items.push({
      index: result.operations.length + offset,
      state: "rejected",
      operation: item.operation as MemoryExtractionOperation,
      reason: item.reason,
    });
  });
  return items.sort((left, right) => left.index - right.index);
}

export const extractionCoordinator = new ExtractionCoordinator();
