import { parse as parseYaml } from "yaml";

import type {
  FailoverDecisionRequired,
  JobRecord,
  StatusSnapshot,
  StatusState,
  StatusTrace,
  StatusUpdateRequest,
  StatusUpdateResult,
} from "../../shared/domain";
import { statusStateSchema } from "../../shared/schemas";
import {
  applyStatusOperations,
  statusStateHash,
  validateStatusState,
} from "../../shared/status-core";
import { echoesApi } from "../api/client";
import { getSettings } from "../state/settings";
import {
  StatusWorldbookStore,
  type StatusWorldbookState,
} from "../worldbook/status-worldbook";
import {
  prepareStatusRequest,
  statusSourceHash,
  selectStatusSourceMessages,
} from "./status-request";
import { renderStatusInjection } from "./status-injection";
import {
  StatusSnapshotStore,
  StatusSnapshotConflictError,
  statusMessageId,
  statusSwipeId,
  type StatusSnapshotRecord,
} from "./status-snapshots";

const TERMINAL_STATES = new Set(["succeeded", "failed", "cancelled", "ambiguous"]);
const MAIN_GENERATION_TYPES = new Set(["chat", "normal", "continue", "regenerate", "swipe", "impersonate"]);

function sleep(durationMs: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, durationMs));
}

async function waitForJob<TResult>(job: JobRecord<TResult>): Promise<JobRecord<TResult>> {
  const deadline = Date.now() + 2 * 60 * 60_000;
  let current = job;
  while (!TERMINAL_STATES.has(current.status) && Date.now() < deadline) {
    await sleep(600);
    current = await echoesApi.getJob<TResult>(current.id);
  }
  if (!TERMINAL_STATES.has(current.status)) throw new Error("Waiting for the status task timed out.");
  if (current.status !== "succeeded" || !current.result) {
    throw new Error(current.error?.message ?? current.message);
  }
  return current;
}

function decideAmbiguous(decision: FailoverDecisionRequired): Promise<boolean> {
  if (!decision.nextEndpointId) return Promise.resolve(false);
  return Promise.resolve(window.confirm(
    `${decision.message}\n\n选择“确定”将切换到下一端点并创建新请求；选择“取消”将保留旧状态。`,
  ));
}

function snapshotId(namespaceId: string, messageIndex: number, swipeId: number): string {
  const namespace = namespaceId.replace(/^status_namespace_/, "").slice(0, 36);
  return `status_${namespace}_${messageIndex}_${swipeId}`;
}

function lastAssistantIndex(): number {
  const chat = SillyTavern.getContext().chat;
  for (let index = chat.length - 1; index >= 0; index -= 1) {
    const message = chat[index]!;
    if (message.is_user !== true && message.role !== "user"
      && String(message.mes ?? message.message ?? "").trim()) return index;
  }
  return -1;
}

interface MutableStatusTraceContext {
  chatId: string;
  namespaceId: string;
  targetMessageId: string;
  targetSwipeId: number;
  sourceMessageIds: string[];
}

export class StatusCoordinator {
  readonly worldbook = new StatusWorldbookStore();
  readonly snapshots = new StatusSnapshotStore();
  private readonly pending = new Map<string, Promise<StatusSnapshot | null>>();
  private readonly rerunOrigins = new Map<string, "auto" | "manual">();
  private readonly traces = new Map<string, StatusTrace>();
  private lastInjection: { worldbookName: string; token: symbol } | null = null;

  load(): Promise<StatusWorldbookState> {
    return this.worldbook.load();
  }

  get trace(): StatusTrace | null {
    const chatId = SillyTavern.getContext().chatId;
    const trace = chatId ? this.traces.get(chatId) : undefined;
    return trace ? structuredClone(trace) : null;
  }

  history(state: StatusWorldbookState): StatusSnapshotRecord[] {
    return this.snapshots.history(state.catalog.namespaceId);
  }

  current(state: StatusWorldbookState): StatusSnapshotRecord | null {
    return this.snapshots.latest(state.catalog.namespaceId);
  }

  manualStateToken(state: StatusWorldbookState): string {
    const context = SillyTavern.getContext();
    const index = lastAssistantIndex();
    return JSON.stringify([context.chatId, window.TavernHelper?.getChatWorldbookName("current"),
      state.catalog.namespaceId, state.catalog.profile.initialState, state.catalog.profile.validation,
      index, context.chat[index] ? [statusMessageId(context.chat[index]!, index), statusSwipeId(context.chat[index]!),
        context.chat[index]!.mes ?? context.chat[index]!.message] : null, this.current(state)]);
  }

  async generationState(state: StatusWorldbookState, type = "normal"): Promise<StatusState> {
    const record = type === "regenerate" || type === "swipe"
      ? this.snapshots.latestBefore(lastAssistantIndex(), state.catalog.namespaceId)
      : this.snapshots.latest(state.catalog.namespaceId);
    return (await this.verifiedSnapshot(record))?.state ?? state.catalog.profile.initialState;
  }

  runAutomatic(): Promise<StatusSnapshot | null> {
    const chatId = SillyTavern.getContext().chatId;
    if (!chatId) return Promise.resolve(null);
    const existing = this.pending.get(chatId);
    if (existing) {
      if (!this.rerunOrigins.has(chatId)) this.rerunOrigins.set(chatId, "auto");
      return existing;
    }
    return this.startUpdate("auto", chatId);
  }

  async synchronize(): Promise<StatusSnapshot | null> {
    const chatId = SillyTavern.getContext().chatId;
    if (!chatId) return null;
    const existing = this.pending.get(chatId);
    if (existing) {
      this.rerunOrigins.set(chatId, "manual");
      return existing;
    }
    return this.startUpdate("manual", chatId);
  }

  async saveManualState(rawState: unknown, origin: "manual" | "restored" = "manual", expectedToken?: string): Promise<StatusSnapshot> {
    const state = await this.load();
    const token = this.manualStateToken(state);
    if (expectedToken !== undefined && expectedToken !== token) throw new StatusSnapshotConflictError();
    const guard = () => {
      if (this.manualStateToken(state) !== token) throw new StatusSnapshotConflictError();
    };
    const targetIndex = lastAssistantIndex();
    if (targetIndex < 0) throw new Error("The chat has no assistant message to own a status snapshot.");
    const target = SillyTavern.getContext().chat[targetIndex]!;
    const targetMessageId = statusMessageId(target, targetIndex);
    const targetSwipeId = statusSwipeId(target);
    const previousRecord = this.snapshots.latestBefore(targetIndex, state.catalog.namespaceId);
    const existing = this.snapshots.selected(targetIndex, state.catalog.namespaceId);
    const previous = await this.verifiedSnapshot(previousRecord);
    const candidate = statusStateSchema.parse(rawState);
    const baseState = previous?.state ?? state.catalog.profile.initialState;
    validateStatusState(candidate, baseState, state.catalog.profile.validation);
    const now = new Date().toISOString();
    const { originalMessages: sourceMessages } = selectStatusSourceMessages({
      baseSnapshot: previous, targetMessageIndex: targetIndex,
    });
    const snapshot: StatusSnapshot = {
      formatVersion: 1,
      namespaceId: state.catalog.namespaceId,
      snapshotId: snapshotId(state.catalog.namespaceId, targetIndex, targetSwipeId),
      targetMessageId,
      targetSwipeId,
      ...(previous ? { parentSnapshotId: previous.snapshotId } : {}),
      baseStateHash: await statusStateHash(baseState),
      sourceMessageIds: sourceMessages.map((message) => message.id),
      sourceHash: await statusSourceHash(sourceMessages),
      state: candidate,
      stateHash: await statusStateHash(candidate),
      revision: (existing?.revision ?? 0) + 1,
      origin,
      createdAt: existing?.createdAt ?? now,
      updatedAt: now,
    };
    await this.snapshots.write({
      lockedChatId: state.catalog.chatId,
      messageIndex: targetIndex,
      messageId: targetMessageId,
      swipeId: targetSwipeId,
      snapshot,
      expectedSnapshot: existing,
      expectedParent: previousRecord,
      guard,
    });
    this.rerunOrigins.delete(state.catalog.chatId);
    return snapshot;
  }

  restoreSnapshot(snapshot: StatusSnapshot): Promise<StatusSnapshot> {
    return this.saveManualState(snapshot.state, "restored");
  }

  parseYaml(value: string): StatusState {
    return statusStateSchema.parse(parseYaml(value));
  }

  async prepareInjection(type: string | undefined): Promise<void> {
    const generationType = type ?? "normal";
    if (!MAIN_GENERATION_TYPES.has(generationType)) {
      await this.clearInjection();
      return;
    }
    let state = await this.load();
    await this.worldbook.cleanupStale(state.worldbookName);
    await this.worldbook.clearInjection(state.worldbookName);
    const ownership = { worldbookName: state.worldbookName, token: Symbol() };
    this.lastInjection = ownership;
    if (!state.catalog.enabled) return;
    const pending = this.pending.get(state.catalog.chatId);
    if (pending) {
      const timeoutMs = Math.min(60_000, state.catalog.profile.injection.maxWaitMs);
      const completed = await Promise.race([
        pending.then(() => true, () => false),
        sleep(timeoutMs).then(() => false),
      ]);
      if (!completed) toastr.warning("状态任务尚未完成，本次生成使用最近有效状态。", "Echoes 状态滞后");
      state = await this.load();
    }
    const current = await this.generationState(state, generationType);
    const isCurrent = () => this.lastInjection === ownership
      && SillyTavern.getContext().chatId === state.catalog.chatId
      && window.TavernHelper?.getChatWorldbookName("current") === state.worldbookName;
    if (!isCurrent()) return;
    await this.worldbook.writeInjection(state, (catalog) =>
      renderStatusInjection(catalog, current).trim(), isCurrent);
  }

  async previewInjection(): Promise<string> {
    const worldbook = window.TavernHelper?.getChatWorldbookName("current");
    if (!worldbook) return "";
    const state = await this.worldbook.inspect(worldbook).catch(() => null);
    if (!state?.catalog.enabled) return "";
    const current = await this.verifiedSnapshot(this.snapshots.latest(state.catalog.namespaceId));
    return renderStatusInjection(state.catalog, current?.state ?? state.catalog.profile.initialState);
  }

  async clearInjection(): Promise<void> {
    const ownership = this.lastInjection;
    const worldbookName = ownership?.worldbookName
      ?? window.TavernHelper?.getChatWorldbookName("current")
      ?? null;
    if (worldbookName) await this.worldbook.clearInjection(worldbookName).catch(() => undefined);
    if (this.lastInjection === ownership) this.lastInjection = null;
  }

  private startUpdate(
    origin: "auto" | "manual",
    chatId: string,
  ): Promise<StatusSnapshot | null> {
    const operation = this.updateLatest(origin, chatId).finally(() => {
      if (this.pending.get(chatId) !== operation) return;
      this.pending.delete(chatId);
      const rerunOrigin = this.rerunOrigins.get(chatId);
      this.rerunOrigins.delete(chatId);
      if (!rerunOrigin || SillyTavern.getContext().chatId !== chatId) return;
      queueMicrotask(() => {
        const rerun = rerunOrigin === "manual" ? this.synchronize() : this.runAutomatic();
        void rerun.catch((error) => {
          console.error("[Echoes] Deferred status update failed.", error);
        });
      });
    });
    this.pending.set(chatId, operation);
    return operation;
  }

  private async updateLatest(
    origin: "auto" | "manual",
    lockedChatId: string,
  ): Promise<StatusSnapshot | null> {
    const startedAt = new Date().toISOString();
    const traceContext: MutableStatusTraceContext = {
      chatId: lockedChatId,
      namespaceId: "status_namespace_unavailable",
      targetMessageId: "unavailable",
      targetSwipeId: 0,
      sourceMessageIds: [],
    };
    try {
      if (SillyTavern.getContext().chatId !== lockedChatId) return null;
      return await this.performUpdateLatest(origin, startedAt, traceContext);
    } catch (error) {
      if (error instanceof StatusSnapshotConflictError) {
        this.rerunOrigins.delete(lockedChatId);
        this.setTrace({
          ...traceContext, startedAt, completedAt: new Date().toISOString(),
          outcome: "discarded", operationCount: 0, attempts: [], message: error.message,
        });
        return null;
      }
      this.setTrace({
        ...traceContext,
        startedAt,
        completedAt: new Date().toISOString(),
        outcome: "failed",
        operationCount: 0,
        attempts: [],
        message: error instanceof Error ? error.message : String(error),
      });
      throw error;
    }
  }

  private async performUpdateLatest(
    origin: "auto" | "manual",
    startedAt: string,
    traceContext: MutableStatusTraceContext,
  ): Promise<StatusSnapshot | null> {
    const state = await this.load();
    traceContext.chatId = state.catalog.chatId;
    traceContext.namespaceId = state.catalog.namespaceId;
    const skip = (message: string, record = true): null => {
      if (record) {
        this.setTrace({
          ...traceContext,
          startedAt,
          completedAt: new Date().toISOString(),
          outcome: "skipped",
          operationCount: 0,
          attempts: [],
          message,
        });
      }
      return null;
    };
    if (!state.catalog.enabled) {
      return skip("状态记忆未启用：请在本页或“状态注入”页打开“状态记忆”开关后重试。仅打开“自动更新状态”不会启动同步。");
    }
    // Auto updates stay quiet when the user has simply turned automation off.
    if (origin === "auto" && !state.catalog.autoUpdate) return skip("自动更新未启用，已跳过。", false);
    const targetIndex = lastAssistantIndex();
    if (targetIndex < 0) return skip("当前聊天没有可用于承载状态快照的 AI 回复。", origin === "manual");
    const target = SillyTavern.getContext().chat[targetIndex]!;
    const targetMessageId = statusMessageId(target, targetIndex);
    const targetSwipeId = statusSwipeId(target);
    traceContext.targetMessageId = targetMessageId;
    traceContext.targetSwipeId = targetSwipeId;
    const previousRecord = this.snapshots.latestBefore(targetIndex, state.catalog.namespaceId);
    const existing = this.snapshots.selected(targetIndex, state.catalog.namespaceId);
    const previous = await this.verifiedSnapshot(previousRecord);
    const prepared = await prepareStatusRequest({
      catalog: state.catalog,
      baseSnapshot: previous,
      targetMessageIndex: targetIndex,
    });
    traceContext.sourceMessageIds = prepared.originalMessages.map((message) => message.id);
    if (existing?.sourceHash === prepared.sourceHash
      && existing.targetMessageId === targetMessageId
      && existing.targetSwipeId === targetSwipeId) {
      this.setTrace({
        chatId: state.catalog.chatId,
        namespaceId: state.catalog.namespaceId,
        targetMessageId,
        targetSwipeId,
        sourceMessageIds: prepared.originalMessages.map((message) => message.id),
        startedAt,
        completedAt: new Date().toISOString(),
        outcome: "unchanged",
        operationCount: 0,
        attempts: [],
        message: "The current swipe already has a matching status snapshot.",
      });
      return existing;
    }
    const settings = getSettings();
    if (prepared.rangeNotice) {
      toastr.warning(prepared.rangeNotice, "Echoes 状态更新范围");
      console.warn("[Echoes] Status update range limited.", prepared.rangeNotice);
    }
    const workflow = settings.generationWorkflows.status;
    const group = settings.generationGroups.find((candidate) => candidate.id === workflow.groupId);
    if (!group) throw new Error("请先配置状态更新使用的生成端点组。");
    const baseState = previous?.state ?? state.catalog.profile.initialState;
    const baseStateHash = await statusStateHash(baseState);
    let resumeAfterEndpointId: string | undefined;
    let result: StatusUpdateResult;
    while (true) {
      const request: StatusUpdateRequest = {
        chatId: state.catalog.chatId,
        namespaceId: state.catalog.namespaceId,
        targetMessageId,
        targetSwipeId,
        baseState,
        baseStateHash,
        promptMessages: prepared.promptMessages,
        messages: prepared.originalMessages,
        validation: state.catalog.profile.validation,
        generationGroup: group,
        failoverPolicy: workflow.failoverPolicy,
        ...(resumeAfterEndpointId ? { resumeAfterEndpointId } : {}),
      };
      const job = await echoesApi.startStatusUpdate(request);
      result = (await waitForJob(job)).result!;
      if (!result.decisionRequired) break;
      if (!await decideAmbiguous(result.decisionRequired)) {
        this.setTrace({
          chatId: state.catalog.chatId,
          namespaceId: state.catalog.namespaceId,
          targetMessageId,
          targetSwipeId,
          sourceMessageIds: prepared.originalMessages.map((message) => message.id),
          startedAt,
          completedAt: new Date().toISOString(),
          outcome: "decision_required",
          operationCount: 0,
          attempts: result.attempts,
          message: "Kept the previous status after an ambiguous provider result.",
        });
        return null;
      }
      resumeAfterEndpointId = result.decisionRequired.failedEndpointId;
    }
    if (result.outcome !== "completed" || !result.state || !result.stateHash) return null;
    const recomputed = applyStatusOperations({
      baseState,
      operations: result.operations,
      evidenceMessageIds: prepared.originalMessages.map((message) => message.id),
      validation: state.catalog.profile.validation,
    });
    const recomputedHash = await statusStateHash(recomputed);
    if (recomputedHash !== result.stateHash || recomputedHash !== await statusStateHash(result.state)) {
      throw new Error("The browser status verification did not match the server result.");
    }
    if (SillyTavern.getContext().chatId !== state.catalog.chatId) {
      this.setTrace({
        chatId: state.catalog.chatId,
        namespaceId: state.catalog.namespaceId,
        targetMessageId,
        targetSwipeId,
        sourceMessageIds: prepared.originalMessages.map((message) => message.id),
        startedAt,
        completedAt: new Date().toISOString(),
        outcome: "discarded",
        operationCount: result.operations.length,
        attempts: result.attempts,
        message: "Chat changed before the status result was written.",
      });
      return null;
    }
    const currentTarget = SillyTavern.getContext().chat[targetIndex];
    let currentSourceHash: string | null = null;
    if (currentTarget
      && statusMessageId(currentTarget, targetIndex) === targetMessageId
      && statusSwipeId(currentTarget) === targetSwipeId) {
      try {
        currentSourceHash = (await prepareStatusRequest({
          catalog: state.catalog,
          baseSnapshot: previous,
          targetMessageIndex: targetIndex,
        })).sourceHash;
      } catch {
        currentSourceHash = null;
      }
    }
    const sourceChanged = !currentTarget
      || statusMessageId(currentTarget, targetIndex) !== targetMessageId
      || statusSwipeId(currentTarget) !== targetSwipeId
      || currentSourceHash !== prepared.sourceHash;
    if (sourceChanged) {
      if (origin === "manual" || !this.rerunOrigins.has(state.catalog.chatId)) {
        this.rerunOrigins.set(state.catalog.chatId, origin);
      }
      this.setTrace({
        chatId: state.catalog.chatId,
        namespaceId: state.catalog.namespaceId,
        targetMessageId,
        targetSwipeId,
        sourceMessageIds: prepared.originalMessages.map((message) => message.id),
        startedAt,
        completedAt: new Date().toISOString(),
        outcome: "discarded",
        operationCount: result.operations.length,
        attempts: result.attempts,
        message: "The target swipe changed while the status task was running; a fresh update was queued.",
      });
      return null;
    }
    const now = new Date().toISOString();
    const snapshot: StatusSnapshot = {
      formatVersion: 1,
      namespaceId: state.catalog.namespaceId,
      snapshotId: snapshotId(state.catalog.namespaceId, targetIndex, targetSwipeId),
      targetMessageId,
      targetSwipeId,
      ...(previous ? { parentSnapshotId: previous.snapshotId } : {}),
      baseStateHash,
      sourceMessageIds: prepared.originalMessages.map((message) => message.id),
      sourceHash: prepared.sourceHash,
      state: recomputed,
      stateHash: recomputedHash,
      revision: (existing?.revision ?? 0) + 1,
      origin,
      createdAt: existing?.createdAt ?? now,
      updatedAt: now,
    };
    await this.snapshots.write({
      lockedChatId: state.catalog.chatId,
      messageIndex: targetIndex,
      messageId: targetMessageId,
      swipeId: targetSwipeId,
      snapshot,
      expectedSnapshot: existing,
      expectedParent: previousRecord,
    });
    this.setTrace({
      chatId: state.catalog.chatId,
      namespaceId: state.catalog.namespaceId,
      targetMessageId,
      targetSwipeId,
      sourceMessageIds: snapshot.sourceMessageIds,
      startedAt,
      completedAt: new Date().toISOString(),
      outcome: "completed",
      operationCount: result.operations.length,
      attempts: result.attempts,
      ...(prepared.rangeNotice ? { message: prepared.rangeNotice } : {}),
    });
    return snapshot;
  }

  private setTrace(trace: StatusTrace): void {
    this.traces.set(trace.chatId, trace);
  }

  private async verifiedSnapshot(record: StatusSnapshotRecord | null): Promise<StatusSnapshot | null> {
    if (!record) return null;
    return await statusStateHash(record.snapshot.state) === record.snapshot.stateHash
      ? record.snapshot
      : null;
  }
}

export const statusCoordinator = new StatusCoordinator();
