import type { SummarySlice } from "../shared/domain";
import { DEFAULT_CONTINUITY, currentFact, refKey, renderContinuity, traverseMemoryLinks, type MemoryReference } from "../shared/continuity";
import { declaredAliases } from "../shared/extraction-context";
import { getSettings } from "./state/settings";
import { WorldbookMemoryStore } from "./worldbook/worldbook-memory";
import { readMemoryLinks } from "./worldbook/memory-links";
import type { SummaryWorldbookState } from "./worldbook/summary-worldbook";

export interface AssociatedMemory { id: string; title: string; text: string }
export const renderSummaryBody = (slice: SummarySlice) => [slice.content, renderContinuity(slice.continuity)].filter(Boolean).join("\n");

export async function associatedMemories(state: SummaryWorldbookState, slices: SummarySlice[], query: string): Promise<AssociatedMemory[]> {
  const config = getSettings().continuity?.associations ?? DEFAULT_CONTINUITY.associations;
  if (!config.enabled || !config.maxItems) return [];
  const store = new WorldbookMemoryStore();
  const memory = await store.inspect(state.worldbookName);
  const links = await readMemoryLinks(state.worldbookName);
  const rows = memory.rows.filter((row) => row.enabled && currentFact(row.continuity));
  const summaries = state.slices.filter((slice) => slice.batch.state !== "stale" && slice.continuity?.validity !== "superseded"
    && !state.catalog.pendingRetrievalDeletes.includes(slice.id));
  const roots: MemoryReference[] = slices.map((slice) => ({ kind: "summary", id: slice.id }));
  const names = new Map<string, Set<string>>();
  for (const row of rows) for (const name of [row.dataName, ...declaredAliases(row, memory.catalog.types)]) {
    const key = name.trim().toLowerCase();
    const ids = names.get(key) ?? new Set<string>();
    ids.add(row.id); names.set(key, ids);
  }
  const matching = rows.filter((row) => [row.dataName, ...declaredAliases(row, memory.catalog.types)]
    .some((name) => name.length > 1 && names.get(name.trim().toLowerCase())?.size === 1 && query.toLowerCase().includes(name.toLowerCase())));
  // Explicitly linked entities only; a name match seeds traversal, never creates a link.
  const available = new Set([...rows.map((row) => `row:${row.id}`), ...summaries.map((slice) => `summary:${slice.id}`)]);
  const visited = new Set(roots.map(refKey));
  const references = [
    ...traverseMemoryLinks(roots, links.links, available, config.maxDepth, config.maxItems),
    ...traverseMemoryLinks([...roots, ...matching.map((row) => ({ kind: "row" as const, id: row.id }))], links.links, available, config.maxDepth, config.maxItems),
  ].filter((ref) => {
    if (visited.has(refKey(ref))) return false;
    visited.add(refKey(ref)); return true;
  }).slice(0, config.maxItems);
  return references.flatMap((ref): AssociatedMemory[] => {
    if (ref.kind === "summary") {
      const slice = summaries.find((item) => item.id === ref.id)!;
      return [{ id: refKey(ref), title: slice.title, text: `[关联经历：${slice.timestamp} / ${slice.title}]\n${renderSummaryBody(slice)}` }];
    }
    const row = rows.find((item) => item.id === ref.id)!;
    const type = memory.catalog.types.find((item) => item.id === row.typeId)!;
    const details = type.columns.filter((column) => row.values[column.id] !== undefined)
      .map((column) => `${column.name}：${typeof row.values[column.id] === "string" ? row.values[column.id] : JSON.stringify(row.values[column.id])}`).join("\n");
    return [{ id: refKey(ref), title: row.dataName,
      text: `[关联资料：${row.dataName}]\n${details}\n${renderContinuity(row.continuity)}`.trim() }];
  });
}

export function statusTriggerQueries(state: Record<string, unknown> | undefined, nearDays: number): Array<{ id: string; text: string }> {
  if (!state) return [];
  const scene = state["时空状态"] as Record<string, unknown> | undefined;
  const result: Array<{ id: string; text: string }> = [];
  const text = (value: unknown) => typeof value === "string" ? value.trim() : value && typeof value === "object" ? JSON.stringify(value) : "";
  for (const [key, id] of [["当前地点", "trigger_place"], ["在场角色", "trigger_people"]] as const) {
    const value = text(scene?.[key]);
    if (value && !/^(?:未知|未明确|无|-)$/u.test(value)) result.push({ id, text: `${key}：${value}`.slice(0, 2000) });
  }
  if (result.length > 1) {
    const sceneText = result.map((item) => item.text).join("\n");
    result.splice(0, result.length, { id: "trigger_scene", text: sceneText });
  }
  const commitments = state["计划与承诺"];
  if (commitments && typeof commitments === "object" && !Array.isArray(commitments)) {
    const date = text(scene?.["日期"]).match(/(\d{4})[-年](\d{1,2})[-月](\d{1,2})/);
    const now = date ? Date.UTC(Number(date[1]), Number(date[2]) - 1, Number(date[3])) : NaN;
    for (const [key, value] of Object.entries(commitments)) {
      const content = text(value);
      if (!content || /已完成|已取消/.test(key)
        || (value && typeof value === "object" && ["已完成", "已取消"].includes(String((value as Record<string, unknown>)["状态"] ?? "")))) continue;
      const deadlines = [...content.matchAll(/(\d{4})[-年](\d{1,2})[-月](\d{1,2})/g)];
      const near = Number.isFinite(now) && deadlines.some((match) => {
        const days = (Date.UTC(Number(match[1]), Number(match[2]) - 1, Number(match[3])) - now) / 86400000;
        return days >= 0 && days <= nearDays;
      });
      if (/未解决|待办|未完成/.test(key) || near) result.push({ id: `trigger_commitment_${result.length}`, text: `${key}：${content}`.slice(0, 2000) });
    }
  }
  return result;
}
