import { MemoryPanel } from "./workbench/app";
import { installConsoleLogRecorder } from "./workbench/logs";
import {
  installRecallInterceptor,
  recallCoordinator,
} from "./recall-coordinator";
import { statusCoordinator } from "./status/status-coordinator";

let panel: MemoryPanel | null = null;
let initialized = false;

function addLaunchControls(): void {
  if (!document.getElementById("echoes-memory-launcher")) {
    const launcher = document.createElement("div");
    launcher.id = "echoes-memory-launcher";
    launcher.className = "list-group-item flex-container flexGap5 interactable";
    launcher.setAttribute("role", "button");
    launcher.setAttribute("aria-label", "打开 Echoes Memory");
    launcher.tabIndex = 0;
    launcher.title = "打开 Echoes Memory";
    launcher.innerHTML = '<i class="fa-solid fa-table-columns fa-fw"></i><span>Echoes Memory</span>';
    launcher.addEventListener("click", () => void panel?.open());
    launcher.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        void panel?.open();
      }
    });
    document.querySelector("#extensionsMenu")?.append(launcher);
  }

  if (!document.getElementById("echoes-memory-settings-entry")) {
    const entry = document.createElement("div");
    entry.id = "echoes-memory-settings-entry";
    entry.className = "echoes-settings-entry";
    entry.innerHTML = `
      <div class="inline-drawer">
        <div class="inline-drawer-toggle inline-drawer-header">
          <b>Echoes Memory</b>
          <div class="inline-drawer-icon fa-solid fa-circle-chevron-down down"></div>
        </div>
        <div class="inline-drawer-content">
          <button type="button" class="menu_button echoes-settings-open" data-echoes-open>
            <i class="fa-solid fa-table-columns"></i> 打开 Echoes 记忆面板
          </button>
        </div>
      </div>`;
    entry.querySelector("[data-echoes-open]")!.addEventListener("click", () => void panel?.open());
    document.querySelector("#extensions_settings2")?.append(entry);
  }
}

function initialize(): void {
  if (initialized || !document.body) return;
  initialized = true;
  installConsoleLogRecorder();
  panel = new MemoryPanel();
  addLaunchControls();

  const events = SillyTavern.getContext().eventSource;
  const refresh = () => {
    if (!document.getElementById("echoes-memory-overlay")?.classList.contains("echoes-hidden")) {
      void panel?.reload();
    }
    void panel?.checkSummaryAutomation();
    void panel?.checkExtractionAutomation();
  };
  events?.on("chat_changed", refresh);
  events?.on("chat_id_changed", refresh);
  const clearRecall = () => void recallCoordinator.clear();
  events?.on("generation_ended", clearRecall);
  events?.on("generation_stopped", clearRecall);
  events?.on("chat_changed", clearRecall);
  events?.on("chat_id_changed", clearRecall);
  const clearStatus = () => void statusCoordinator.clearInjection();
  events?.on("generation_ended", clearStatus);
  events?.on("generation_stopped", clearStatus);
  events?.on("chat_changed", clearStatus);
  events?.on("chat_id_changed", clearStatus);
  events?.on("generation_ended", () => void statusCoordinator.runAutomatic().catch((error) => {
    toastr.error(error instanceof Error ? error.message : String(error), "Echoes 状态更新失败");
  }));
  events?.on("generation_stopped", () => void statusCoordinator.runAutomatic().catch((error) => {
    toastr.error(error instanceof Error ? error.message : String(error), "Echoes 状态更新失败");
  }));
  const updateLatestStatus = (messageId: number | string) => {
    const chat = SillyTavern.getContext().chat;
    let latestAssistant = -1;
    for (let index = chat.length - 1; index >= 0; index -= 1) {
      if (chat[index]?.is_user !== true && chat[index]?.role !== "user") {
        latestAssistant = index;
        break;
      }
    }
    if (latestAssistant < 0) return;
    const stableId = String(chat[latestAssistant]?.message_id ?? chat[latestAssistant]?.id ?? latestAssistant);
    if (String(messageId) !== String(latestAssistant) && String(messageId) !== stableId) return;
    void statusCoordinator.runAutomatic().catch((error) => {
      toastr.error(error instanceof Error ? error.message : String(error), "Echoes 状态更新失败");
    });
  };
  events?.on("message_edited", updateLatestStatus);
  events?.on("message_swiped", updateLatestStatus);
  const summaryCheck = () => void panel?.checkSummaryAutomation();
  const extractionCheck = () => void panel?.checkExtractionAutomation();
  events?.on("user_message_rendered", summaryCheck);
  events?.on("user_message_rendered", extractionCheck);
  events?.on("message_edited", summaryCheck);
  events?.on("message_swiped", summaryCheck);
  events?.on("message_deleted", summaryCheck);
  void panel.checkSummaryAutomation();
  void panel.checkExtractionAutomation();
  console.log("[Echoes] Browser extension initialized.");
}

export function onActivate(): void {
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", initialize, { once: true });
  } else {
    initialize();
  }
}

installRecallInterceptor();
onActivate();
