import type { ChatMessageInput, SummaryBatchInput, SummaryBatchMetadata, SummarySlice } from "../../shared/domain";

export function createBatchOrder(messages: ChatMessageInput[]) {
  const positions = new Map(messages.map((message, index) => [message.id, index]));
  const starts = new WeakMap<SummaryBatchInput, number | null>();
  const start = (batch: SummaryBatchInput): number | null => {
    if (starts.has(batch)) return starts.get(batch)!;
    let value: number | null = null;
    for (const [offset, id] of batch.messageIds.entries()) {
      const index = positions.get(id);
      if (index !== undefined) { value = Math.max(0, index - offset); break; }
    }
    starts.set(batch, value);
    return value;
  };
  const compare = (left: SummaryBatchMetadata, right: SummaryBatchMetadata): number => {
    const a = start(left), b = start(right);
    if (a !== null && b !== null) return a - b || left.messageIds.length - right.messageIds.length;
    return left.createdAt.localeCompare(right.createdAt);
  };
  return { start, compare };
}

export function batchSourceStart(batch: SummaryBatchInput, messages: ChatMessageInput[]): number | null {
  return createBatchOrder(messages).start(batch);
}

export function compareSummaryBatches(
  left: SummaryBatchMetadata, right: SummaryBatchMetadata, messages: ChatMessageInput[],
): number {
  return createBatchOrder(messages).compare(left, right);
}

export function summarySuffix(slices: SummarySlice[], batchNumber: number, messages: ChatMessageInput[]): SummarySlice[] {
  const selected = slices.find((slice) => slice.batch.batchNumber === batchNumber)?.batch;
  if (!selected || selected.source?.kind === "imported") throw new Error("找不到可重置的聊天总结批次。");
  const selectedIndex = slices.findIndex((slice) => slice.batch.id === selected.id);
  const { compare } = createBatchOrder(messages);
  return slices.filter((slice, index) => slice.batch.source?.kind !== "imported"
    && (slice.batch.id === selected.id || compare(slice.batch, selected) > 0
      || (compare(slice.batch, selected) === 0 && index >= selectedIndex)));
}
