import type { StatusSnapshot } from "../../shared/domain";
import { statusSnapshotSchema } from "../../shared/schemas";
import { messageWriteCoordinator } from "../chat/message-write-coordinator";

export interface StatusSnapshotRecord {
  messageIndex: number;
  messageId: string;
  swipeId: number;
  selected: boolean;
  snapshot: StatusSnapshot;
}

export class StatusSnapshotConflictError extends Error {
  constructor() {
    super("状态已被修改，本次结果未覆盖已保存的状态。");
    this.name = "StatusSnapshotConflictError";
  }
}

function helper(): TavernHelperApi & Required<Pick<TavernHelperApi, "getVariables" | "updateVariablesWith">> {
  const api = window.TavernHelper;
  if (!api || typeof api.getVariables !== "function" || typeof api.updateVariablesWith !== "function") {
    throw new Error("Echoes requires TavernHelper message variable APIs for status memory.");
  }
  return api as TavernHelperApi & Required<Pick<TavernHelperApi, "getVariables" | "updateVariablesWith">>;
}

export function statusMessageId(message: Record<string, unknown>, index: number): string {
  return String(message.message_id ?? message.id ?? index);
}

export function statusSwipeId(message: Record<string, unknown>): number {
  const value = Number(message.swipe_id ?? 0);
  return Number.isInteger(value) && value >= 0 ? value : 0;
}

function parseSnapshot(value: unknown, namespaceId: string): StatusSnapshot | null {
  const parsed = statusSnapshotSchema.safeParse(value);
  return parsed.success && parsed.data.namespaceId === namespaceId ? parsed.data : null;
}

function rawSwipeVariables(message: Record<string, unknown>, swipeId: number): Record<string, unknown> | null {
  const variables = message.variables;
  if (Array.isArray(variables)) return variables[swipeId] ?? null;
  if (variables && typeof variables === "object") {
    return (variables as Record<number, Record<string, unknown>>)[swipeId] ?? null;
  }
  const swipeData = Array.isArray(message.swipes_data)
    ? message.swipes_data[swipeId] as Record<string, unknown> | undefined
    : undefined;
  const nested = swipeData?.variables;
  return nested && typeof nested === "object" ? nested as Record<string, unknown> : null;
}

export class StatusSnapshotStore {
  selected(messageIndex: number, namespaceId: string): StatusSnapshot | null {
    const variables = helper().getVariables({ type: "message", message_id: messageIndex });
    return parseSnapshot(variables.echoes_status, namespaceId);
  }

  history(namespaceId: string): StatusSnapshotRecord[] {
    const messages = SillyTavern.getContext().chat;
    const records = new Map<string, StatusSnapshotRecord>();
    for (const [messageIndex, message] of messages.entries()) {
      const messageId = statusMessageId(message, messageIndex);
      const selectedSwipe = statusSwipeId(message);
      const swipeCount = Math.max(
        1,
        Array.isArray(message.swipes) ? message.swipes.length : 0,
        Array.isArray(message.variables) ? message.variables.length : 0,
      );
      for (let swipeId = 0; swipeId < swipeCount; swipeId += 1) {
        const variables = swipeId === selectedSwipe
          ? helper().getVariables({ type: "message", message_id: messageIndex })
          : rawSwipeVariables(message, swipeId);
        const snapshot = parseSnapshot(variables?.echoes_status, namespaceId);
        if (!snapshot) continue;
        records.set(snapshot.snapshotId, {
          messageIndex,
          messageId,
          swipeId,
          selected: swipeId === selectedSwipe,
          snapshot,
        });
      }
    }
    return [...records.values()].sort((left, right) =>
      left.messageIndex - right.messageIndex || left.swipeId - right.swipeId);
  }

  latestBefore(messageIndex: number, namespaceId: string): StatusSnapshotRecord | null {
    const messages = SillyTavern.getContext().chat;
    for (let index = Math.min(messageIndex - 1, messages.length - 1); index >= 0; index -= 1) {
      const message = messages[index]!;
      if (message.is_user === true || message.role === "user") continue;
      const snapshot = this.selected(index, namespaceId);
      if (snapshot) {
        return {
          messageIndex: index,
          messageId: statusMessageId(message, index),
          swipeId: statusSwipeId(message),
          selected: true,
          snapshot,
        };
      }
    }
    return null;
  }

  latest(namespaceId: string): StatusSnapshotRecord | null {
    return this.latestBefore(SillyTavern.getContext().chat.length, namespaceId);
  }

  async write(options: {
    lockedChatId: string;
    messageIndex: number;
    messageId: string;
    swipeId: number;
    snapshot: StatusSnapshot;
    expectedSnapshot?: StatusSnapshot | null;
    expectedParent?: StatusSnapshotRecord | null;
    guard?: () => void;
  }): Promise<void> {
    await messageWriteCoordinator.run(async () => {
      options.guard?.();
      const context = SillyTavern.getContext();
      const message = context.chat[options.messageIndex];
      if (context.chatId !== options.lockedChatId
        || !message
        || statusMessageId(message, options.messageIndex) !== options.messageId
        || statusSwipeId(message) !== options.swipeId) {
        throw new Error("The target chat or swipe changed before the status snapshot could be saved.");
      }
      const parsed = statusSnapshotSchema.parse(options.snapshot);
      await helper().updateVariablesWith((variables) => {
        options.guard?.();
        if (options.expectedSnapshot !== undefined
          && JSON.stringify(parseSnapshot(variables.echoes_status, parsed.namespaceId))
            !== JSON.stringify(options.expectedSnapshot)) throw new StatusSnapshotConflictError();
        if (options.expectedParent !== undefined
          && JSON.stringify(this.latestBefore(options.messageIndex, parsed.namespaceId))
            !== JSON.stringify(options.expectedParent)) throw new StatusSnapshotConflictError();
        return { ...variables, echoes_status: parsed };
      }, { type: "message", message_id: options.messageIndex });
    });
  }
}
