import { z } from "zod";

const time = z.string().regex(/^(?:unknown|\d{4}(?:-(?:0[1-9]|1[0-2])(?:-(?:0[1-9]|[12]\d|3[01])(?:T(?:[01]\d|2[0-3]))?)?)?)$/)
  .refine((value) => {
    if (value === "unknown" || value.length < 10) return true;
    const [year, month, day] = value.slice(0, 10).split("-").map(Number) as [number, number, number];
    const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
    return day <= [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1]!;
  }, "Invalid calendar date.");
export const continuitySchema = z.object({
  eventTime: time.optional(),
  learnedTime: time.optional(),
  validFrom: time.optional(),
  validUntil: time.optional(),
  validity: z.enum(["current", "historical", "superseded"]).optional(),
  changeKind: z.enum(["fact_change", "knowledge_change", "canon_correction", "unclassified"]).optional(),
  note: z.string().max(4000).optional(),
  knowledge: z.array(z.object({
    character: z.string().trim().min(1).max(240),
    state: z.enum(["known", "believed", "suspected", "misunderstood", "unknown"]),
    claim: z.string().trim().min(1).max(4000),
    learnedTime: time.optional(),
  }).strict()).max(50).optional(),
}).strict().superRefine((value, context) => {
  const from = value.validFrom, until = value.validUntil;
  if (from && until && from !== "unknown" && until !== "unknown") {
    const precision = Math.min(from.length, until.length);
    if (from.slice(0, precision) > until.slice(0, precision))
      context.addIssue({ code: "custom", path: ["validUntil"], message: "有效终点不能早于有效起点。" });
  }
});
export type ContinuityAttributes = z.infer<typeof continuitySchema>;
export const aliasSchema = z.array(z.string().trim().min(1).max(240)).max(100);

export const continuitySettingsSchema = z.object({
  extractAttributes: z.boolean().default(false),
  associations: z.object({
    enabled: z.boolean().default(false), maxDepth: z.number().int().min(1).max(3).default(1),
    maxItems: z.number().int().min(0).max(50).default(5),
  }).default({ enabled: false, maxDepth: 1, maxItems: 5 }),
  triggers: z.object({
    enabled: z.boolean().default(false), maxQueries: z.number().int().min(1).max(4).default(2),
    nearDays: z.number().int().min(0).max(30).default(3),
  }).default({ enabled: false, maxQueries: 2, nearDays: 3 }),
  supplement: z.object({
    auto: z.boolean().default(false), maxRequests: z.number().int().min(0).max(3).default(1),
    maxWaitMs: z.number().int().min(1000).max(120000).default(15000),
    maxItems: z.number().int().min(1).max(20).default(3),
    minimumHits: z.number().int().min(0).max(100).default(2),
    allowPaid: z.boolean().default(false),
  }).default({ auto: false, maxRequests: 1, maxWaitMs: 15000, maxItems: 3, minimumHits: 2, allowPaid: false }),
});
export type ContinuitySettings = z.infer<typeof continuitySettingsSchema>;
export const DEFAULT_CONTINUITY = continuitySettingsSchema.parse({});

export function currentFact(attributes?: ContinuityAttributes): boolean {
  return attributes?.validity !== "superseded" && attributes?.validity !== "historical";
}
const states = { known: "已知", believed: "相信", suspected: "怀疑", misunderstood: "误解", unknown: "未知" };
export function renderContinuity(value?: ContinuityAttributes): string {
  if (!value) return "";
  const labels = { current: "当前资料", historical: "历史经历，非当前事实", superseded: "已更正失效，非当前事实" };
  return [
    value.eventTime && `事件发生时间：${value.eventTime}`,
    value.learnedTime && `信息得知时间：${value.learnedTime}`,
    value.validFrom && `事实有效起点：${value.validFrom}`,
    value.validUntil && `事实有效终点：${value.validUntil}`,
    value.validity && labels[value.validity],
    value.note && `限定说明：${value.note}`,
    ...(value.knowledge ?? []).map((item) => `【角色认知：${item.character} / ${states[item.state]}${item.learnedTime ? ` / 得知于 ${item.learnedTime}` : ""}】${item.claim}`),
  ].filter(Boolean).join("\n");
}

export const CONTINUITY_EXTRACTION_GUIDE = `Optional temporal and knowledge attributes are enabled. Use Chinese natural-language values. Preserve the original independent timestamp and complete narrative content. You may additionally return "continuity": {"eventTime":"YYYY[-MM[-DD[THH]]] | unknown","learnedTime":"same time format","validFrom":"same time format","validUntil":"same time format","validity":"current | historical | superseded","changeKind":"fact_change | knowledge_change | canon_correction | unclassified","note":"uncertainty or scope","knowledge":[{"character":"exact character name","state":"known | believed | suspected | misunderstood | unknown","claim":"specific proposition","learnedTime":"optional supported time"}]}. All fields are optional. Only use supported dates; omit unknown attributes rather than inventing precision. Knowledge states refer to specific claims, not the entire scene. Preserve uncertainty; a later discovery is not earlier knowledge. Omission does not change existing attributes or default character-known rules. Distinguish an actual change from a correction to a previously erroneous record. Use superseded only if the entire record is invalidated. No conflict-priority rules or evidenceMessageIds.`;

export const memoryReferenceSchema = z.object({ kind: z.enum(["row", "summary"]), id: z.string().min(1).max(240) }).strict();
export type MemoryReference = z.infer<typeof memoryReferenceSchema>;
export const memoryLinkSchema = z.object({
  id: z.string().min(1).max(240), from: memoryReferenceSchema, to: memoryReferenceSchema,
  relation: z.string().trim().min(1).max(120), enabled: z.boolean(),
}).strict();
export type MemoryLink = z.infer<typeof memoryLinkSchema>;
export const refKey = (ref: MemoryReference) => `${ref.kind}:${ref.id}`;

export function traverseMemoryLinks(roots: MemoryReference[], links: MemoryLink[], available: Set<string>, maxDepth: number, maximum: number): MemoryReference[] {
  if (maximum <= 0 || maxDepth <= 0) return [];
  const seen = new Set(roots.map(refKey));
  let frontier = roots;
  const result: MemoryReference[] = [];
  for (let depth = 0; depth < maxDepth && result.length < maximum; depth++) {
    const next: MemoryReference[] = [];
    for (const root of frontier) for (const link of links) {
      if (!link.enabled) continue;
      const target = refKey(link.from) === refKey(root) ? link.to : refKey(link.to) === refKey(root) ? link.from : null;
      if (!target || seen.has(refKey(target)) || !available.has(refKey(target))) continue;
      seen.add(refKey(target)); result.push(target); next.push(target);
      if (result.length >= maximum) return result;
    }
    frontier = next;
  }
  return result;
}
