class WorldbookWriteCoordinator {
  private readonly chains = new Map<string, Promise<void>>();

  run<T>(worldbookName: string, operation: () => Promise<T>): Promise<T> {
    const previous = this.chains.get(worldbookName) ?? Promise.resolve();
    const result = previous.then(operation, operation);
    const settled = result.then(() => undefined, () => undefined);
    this.chains.set(worldbookName, settled);
    void settled.then(() => {
      if (this.chains.get(worldbookName) === settled) this.chains.delete(worldbookName);
    });
    return result;
  }
}

export const worldbookWriteCoordinator = new WorldbookWriteCoordinator();
